-- =============================================================== 20260929120000_remove_deleted_tag_from_contacts.sql
set check_function_bodies = off;

CREATE OR REPLACE FUNCTION public.handle_tag_deleted()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  update public.contacts set tags = array_remove(tags, old.id) where tags @> array[old.id];
  return old;
end;
$function$
;

CREATE TRIGGER on_tag_deleted AFTER DELETE ON public.tags FOR EACH ROW EXECUTE FUNCTION public.handle_tag_deleted();

CREATE OR REPLACE FUNCTION "public"."handle_contact_saved"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$declare contact_avatar text;
declare emails_length int8;
declare item jsonb;

begin
    if new.avatar is not null then
        return new;
    end if;

    if tg_op = 'UPDATE' and new.email_jsonb is not distinct from old.email_jsonb then
        return new;
    end if;

    select coalesce(jsonb_array_length(new.email_jsonb), 0) into emails_length;

    if emails_length = 0 then
        return new;
    end if;

    for item in select jsonb_array_elements(new.email_jsonb)
    loop
        select public.get_avatar_for_email(item->>'email') into contact_avatar;
        if (contact_avatar is not null) then
            exit;
        end if;
    end loop;

    if contact_avatar is null then
        return new;
    end if;

    new.avatar = concat('{"src":"', contact_avatar, '"}');
    return new;
end;$$;

-- =============================================================== 20261010054346_global_search.sql
alter table "public"."tasks" add column "created_at" timestamp with time zone not null default now();

-- Existing rows have no creation time to recover, so fall back to the best
-- available proxy: when the task was completed, a due date that has already
-- passed, or the contact's first_seen. `least(..., now())` keeps the result in
-- the past -- global_search sorts on this column, and a future date would put
-- every open task above every note, contact and deal. A bare `now()` would be
-- no better: it would tie every open task at the top of that same sort.
update "public"."tasks" t
set "created_at" = least(
    coalesce(
        t."done_date",
        case when t."due_date" < now() then t."due_date" end,
        c."first_seen"
    ),
    now()
)
from "public"."contacts" c
where c."id" = t."contact_id";

create extension if not exists "unaccent" with schema "extensions";

-- unaccent() is only STABLE (its dictionary could change), which generated
-- columns reject. The dictionary is fixed here, so the wrapper is immutable.
create or replace function public.search_unaccent(value text) returns text
    language sql immutable strict parallel safe
    set search_path to ''
    as $$ select extensions.unaccent('extensions.unaccent'::regdictionary, value) $$;

-- Documents and queries are normalized the same way: unaccented, lowercased,
-- split on anything that is not a letter or a digit. So "hélène.dupont@acme-fr.example.org"
-- indexes as helene, dupont, acme, fr and any of those prefixes finds it.
create or replace function public.search_document(variadic parts text[]) returns tsvector
    language sql immutable parallel safe
    set search_path to ''
    as $$
        select to_tsvector(
            'simple'::regconfig,
            regexp_replace(public.search_unaccent(array_to_string(parts, ' ')), '[^[:alnum:]]+', ' ', 'g')
        )
    $$;

-- Every word of the query must match, each one as a prefix: "tho dup" finds
-- "Thomas Dupont". Returns null (matching nothing) for a blank query.
create or replace function public.search_query(query text) returns tsquery
    language sql immutable strict parallel safe
    set search_path to ''
    as $$
        select to_tsquery('simple'::regconfig, string_agg(word || ':*', ' & '))
        from regexp_split_to_table(lower(public.search_unaccent(query)), '[^[:alnum:]]+') as word
        where word <> ''
    $$;

create or replace function public.search_attachment_titles(attachments jsonb[]) returns text
    language sql immutable parallel safe
    set search_path to ''
    as $$ select string_agg(attachment ->> 'title', ' ') from unnest(attachments) as attachment $$;

alter table public.companies add column fts tsvector generated always as (
    public.search_document(name, sector, description, website::text, phone_number, zipcode, city, state_abbr)
) stored;

alter table public.contacts add column fts tsvector generated always as (
    public.search_document(
        first_name,
        last_name,
        title,
        background,
        jsonb_path_query_array(email_jsonb, '$[*]."email"')::text,
        jsonb_path_query_array(phone_jsonb, '$[*]."number"')::text
    )
) stored;

alter table public.deals add column fts tsvector generated always as (
    public.search_document(name, category, description)
) stored;

alter table public.tasks add column fts tsvector generated always as (
    public.search_document(text, type)
) stored;

alter table public.contact_notes add column fts tsvector generated always as (
    public.search_document(text, public.search_attachment_titles(attachments))
) stored;

alter table public.deal_notes add column fts tsvector generated always as (
    public.search_document(text, public.search_attachment_titles(attachments))
) stored;

-- Partial indexes mirror what global_search() returns: open tasks, live deals.
create index companies_fts_idx on public.companies using gin (fts);
create index contacts_fts_idx on public.contacts using gin (fts);
create index deals_fts_idx on public.deals using gin (fts) where archived_at is null;
create index tasks_fts_idx on public.tasks using gin (fts) where done_date is null;
create index contact_notes_fts_idx on public.contact_notes using gin (fts);
create index deal_notes_fts_idx on public.deal_notes using gin (fts);

-- A word found in most rows (a common word, a 2-letter prefix) makes the GIN
-- path fetch and sort every match. Walking a date index backwards instead stops
-- at the first max_results matches. The planner picks between the two per
-- query, which needs fine-grained lexeme statistics on the large tables.
create index contacts_first_seen_idx on public.contacts using btree (first_seen desc nulls last);
create index tasks_open_created_at_idx on public.tasks using btree (created_at desc) where done_date is null;
create index contact_notes_date_idx on public.contact_notes using btree (date desc nulls last);
create index deal_notes_date_idx on public.deal_notes using btree (date desc nulls last);

alter table public.contacts alter column fts set statistics 10000;
alter table public.tasks alter column fts set statistics 10000;
alter table public.contact_notes alter column fts set statistics 10000;
alter table public.deal_notes alter column fts set statistics 10000;

-- Each branch takes its own newest max_results matches (at most 200), so the
-- union never holds more than 6 * max_results rows, and the lookups that build
-- display labels only run on those. `content` carries the searched fields in
-- their original form, so the client can show and highlight where the words
-- matched. The SQL is built per call with the tsquery inlined as a literal:
-- with a parameter the planner could not tell a rare word (use the GIN index)
-- from a common one (walk the date index).
create or replace function public.global_search(
    query text,
    resources text[] default null,
    max_results integer default 50
) returns table (
    resource text,
    record_id bigint,
    title text,
    subtitle text,
    contact_id bigint,
    deal_id bigint,
    date timestamp with time zone,
    content text
)
    language plpgsql stable security invoker
    set search_path to ''
    as $$
declare
    tsq tsquery := public.search_query(query);
    branch_templates constant jsonb := jsonb_build_object(
        'companies', $q$
            select 'companies', c.id, c.name, c.sector, null::bigint, null::bigint, c.created_at,
                concat_ws(' · ', c.sector, c.description, c.website::text, c.phone_number, c.zipcode, c.city, c.state_abbr)
            from public.companies c
            where c.fts @@ %1$L::tsquery
            order by c.created_at desc
            limit %2$s $q$,
        'contacts', $q$
            select 'contacts', co.id, concat_ws(' ', co.first_name, co.last_name),
                (select cc.name from public.companies cc where cc.id = co.company_id), co.id, null::bigint, co.first_seen,
                concat_ws(' · ', co.title, co.background,
                    (select string_agg(e ->> 'email', ' ') from jsonb_array_elements(co.email_jsonb) e),
                    (select string_agg(p ->> 'number', ' ') from jsonb_array_elements(co.phone_jsonb) p))
            from public.contacts co
            where co.fts @@ %1$L::tsquery
            order by co.first_seen desc nulls last
            limit %2$s $q$,
        'deals', $q$
            select 'deals', d.id, d.name,
                (select dc.name from public.companies dc where dc.id = d.company_id), null::bigint, d.id, d.created_at,
                concat_ws(' · ', d.category, d.description)
            from public.deals d
            where d.archived_at is null and d.fts @@ %1$L::tsquery
            order by d.created_at desc
            limit %2$s $q$,
        'tasks', $q$
            select 'tasks', t.id, left(t.text, 200),
                (select concat_ws(' ', tc.first_name, tc.last_name) from public.contacts tc where tc.id = t.contact_id),
                t.contact_id, null::bigint, t.created_at,
                concat_ws(' · ', t.text, t.type)
            from public.tasks t
            where t.done_date is null and t.fts @@ %1$L::tsquery
            order by t.created_at desc
            limit %2$s $q$,
        'contact_notes', $q$
            select 'contact_notes', cn.id, left(cn.text, 200),
                (select concat_ws(' ', nc.first_name, nc.last_name) from public.contacts nc where nc.id = cn.contact_id),
                cn.contact_id, null::bigint, cn.date,
                concat_ws(' · ', cn.text, public.search_attachment_titles(cn.attachments))
            from public.contact_notes cn
            where cn.fts @@ %1$L::tsquery
            order by cn.date desc nulls last
            limit %2$s $q$,
        'deal_notes', $q$
            select 'deal_notes', dn.id, left(dn.text, 200), nd.name, null::bigint, dn.deal_id, dn.date,
                concat_ws(' · ', dn.text, public.search_attachment_titles(dn.attachments))
            from public.deal_notes dn
                join public.deals nd on nd.id = dn.deal_id
            where nd.archived_at is null and dn.fts @@ %1$L::tsquery
            order by dn.date desc nulls last
            limit %2$s $q$
    );
    row_limit constant integer := least(coalesce(max_results, 50), 200);
    branches text[];
begin
    if tsq is null or row_limit < 1 then
        return;
    end if;

    select array_agg(format('(%s)', format(template, tsq::text, row_limit)))
    into branches
    from jsonb_each_text(branch_templates) as b(name, template)
    where resources is null or b.name = any(resources);

    if branches is null then
        return;
    end if;

    return query execute format(
        'select * from (%s) results order by 7 desc nulls last limit %s',
        array_to_string(branches, ' union all '),
        row_limit
    );
end
$$;

revoke execute on function public.global_search(text, text[], integer) from public, anon;
grant execute on function public.global_search(text, text[], integer) to authenticated, service_role;

-- The activity log serializes whole rows: keep the search vectors out of them.
create or replace view public.activity_log with (security_invoker = on) as
select
    ('company.' || c.id || '.created') as id,
    'company.created' as type,
    c.created_at as date,
    c.id as company_id,
    c.sales_id,
    (to_jsonb(c.*) - 'fts')::json as company,
    null::json as contact,
    null::json as deal,
    null::json as contact_note,
    null::json as deal_note
from public.companies c
union all
select
    ('contact.' || co.id || '.created') as id,
    'contact.created' as type,
    co.first_seen as date,
    co.company_id,
    co.sales_id,
    null::json as company,
    (to_jsonb(co.*) - 'fts')::json as contact,
    null::json as deal,
    null::json as contact_note,
    null::json as deal_note
from public.contacts co
union all
select
    ('contactNote.' || cn.id || '.created') as id,
    'contactNote.created' as type,
    cn.date,
    co.company_id,
    cn.sales_id,
    null::json as company,
    null::json as contact,
    null::json as deal,
    (to_jsonb(cn.*) - 'fts')::json as contact_note,
    null::json as deal_note
from public.contact_notes cn
    left join public.contacts co on co.id = cn.contact_id
union all
select
    ('deal.' || d.id || '.created') as id,
    'deal.created' as type,
    d.created_at as date,
    d.company_id,
    d.sales_id,
    null::json as company,
    null::json as contact,
    (to_jsonb(d.*) - 'fts')::json as deal,
    null::json as contact_note,
    null::json as deal_note
from public.deals d
union all
select
    ('dealNote.' || dn.id || '.created') as id,
    'dealNote.created' as type,
    dn.date,
    d.company_id,
    dn.sales_id,
    null::json as company,
    null::json as contact,
    null::json as deal,
    null::json as contact_note,
    (to_jsonb(dn.*) - 'fts')::json as deal_note
from public.deal_notes dn
    left join public.deals d on d.id = dn.deal_id;

-- =============================================================== 20261022120000_global_search_per_resource_cap.sql
-- Cap global_search results per resource instead of overall, so newer notes
-- that mention a name no longer crowd the matching contact out of the results.

CREATE OR REPLACE FUNCTION "public"."global_search"("query" "text", "resources" "text"[] DEFAULT NULL::"text"[], "max_results" integer DEFAULT 50) RETURNS TABLE("resource" "text", "record_id" bigint, "title" "text", "subtitle" "text", "contact_id" bigint, "deal_id" bigint, "date" timestamp with time zone, "content" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
declare
    tsq tsquery := public.search_query(query);
    branch_templates constant jsonb := jsonb_build_object(
        'companies', $q$
            select 'companies', c.id, c.name, c.sector, null::bigint, null::bigint, c.created_at,
                concat_ws(' · ', c.sector, c.description, c.website::text, c.phone_number, c.zipcode, c.city, c.state_abbr)
            from public.companies c
            where c.fts @@ %1$L::tsquery
            order by c.created_at desc
            limit %2$s $q$,
        'contacts', $q$
            select 'contacts', co.id, concat_ws(' ', co.first_name, co.last_name),
                (select cc.name from public.companies cc where cc.id = co.company_id), co.id, null::bigint, co.first_seen,
                concat_ws(' · ', co.title, co.background,
                    (select string_agg(e ->> 'email', ' ') from jsonb_array_elements(co.email_jsonb) e),
                    (select string_agg(p ->> 'number', ' ') from jsonb_array_elements(co.phone_jsonb) p))
            from public.contacts co
            where co.fts @@ %1$L::tsquery
            order by co.first_seen desc nulls last
            limit %2$s $q$,
        'deals', $q$
            select 'deals', d.id, d.name,
                (select dc.name from public.companies dc where dc.id = d.company_id), null::bigint, d.id, d.created_at,
                concat_ws(' · ', d.category, d.description)
            from public.deals d
            where d.archived_at is null and d.fts @@ %1$L::tsquery
            order by d.created_at desc
            limit %2$s $q$,
        'tasks', $q$
            select 'tasks', t.id, left(t.text, 200),
                (select concat_ws(' ', tc.first_name, tc.last_name) from public.contacts tc where tc.id = t.contact_id),
                t.contact_id, null::bigint, t.created_at,
                concat_ws(' · ', t.text, t.type)
            from public.tasks t
            where t.done_date is null and t.fts @@ %1$L::tsquery
            order by t.created_at desc
            limit %2$s $q$,
        'contact_notes', $q$
            select 'contact_notes', cn.id, left(cn.text, 200),
                (select concat_ws(' ', nc.first_name, nc.last_name) from public.contacts nc where nc.id = cn.contact_id),
                cn.contact_id, null::bigint, cn.date,
                concat_ws(' · ', cn.text, public.search_attachment_titles(cn.attachments))
            from public.contact_notes cn
            where cn.fts @@ %1$L::tsquery
            order by cn.date desc nulls last
            limit %2$s $q$,
        'deal_notes', $q$
            select 'deal_notes', dn.id, left(dn.text, 200), nd.name, null::bigint, dn.deal_id, dn.date,
                concat_ws(' · ', dn.text, public.search_attachment_titles(dn.attachments))
            from public.deal_notes dn
                join public.deals nd on nd.id = dn.deal_id
            where nd.archived_at is null and dn.fts @@ %1$L::tsquery
            order by dn.date desc nulls last
            limit %2$s $q$
    );
    row_limit constant integer := least(coalesce(max_results, 50), 200);
    branches text[];
begin
    if tsq is null or row_limit < 1 then
        return;
    end if;

    select array_agg(format('(%s)', format(template, tsq::text, row_limit)))
    into branches
    from jsonb_each_text(branch_templates) as b(name, template)
    where resources is null or b.name = any(resources);

    if branches is null then
        return;
    end if;

    return query execute format(
        'select * from (%s) results order by 7 desc nulls last',
        array_to_string(branches, ' union all ')
    );
end
$_$;

-- =============================================================== 20261026120000_deal_categories.sql
-- deals.fts is generated from category, so it is dropped before the swap and
-- rebuilt from categories, and global_search() is updated to read categories.
alter table "public"."deals" drop column "fts";

alter table "public"."deals" add column "categories" text[];

update "public"."deals" set "categories" = array["category"] where "category" is not null;

alter table "public"."deals" drop column "category";

alter table public.deals add column fts tsvector generated always as (
    public.search_document(variadic array[name, description] || categories)
) stored;

create index deals_fts_idx on public.deals using gin (fts) where archived_at is null;

CREATE OR REPLACE FUNCTION "public"."global_search"("query" "text", "resources" "text"[] DEFAULT NULL::"text"[], "max_results" integer DEFAULT 50) RETURNS TABLE("resource" "text", "record_id" bigint, "title" "text", "subtitle" "text", "contact_id" bigint, "deal_id" bigint, "date" timestamp with time zone, "content" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
declare
    tsq tsquery := public.search_query(query);
    branch_templates constant jsonb := jsonb_build_object(
        'companies', $q$
            select 'companies', c.id, c.name, c.sector, null::bigint, null::bigint, c.created_at,
                concat_ws(' · ', c.sector, c.description, c.website::text, c.phone_number, c.zipcode, c.city, c.state_abbr)
            from public.companies c
            where c.fts @@ %1$L::tsquery
            order by c.created_at desc
            limit %2$s $q$,
        'contacts', $q$
            select 'contacts', co.id, concat_ws(' ', co.first_name, co.last_name),
                (select cc.name from public.companies cc where cc.id = co.company_id), co.id, null::bigint, co.first_seen,
                concat_ws(' · ', co.title, co.background,
                    (select string_agg(e ->> 'email', ' ') from jsonb_array_elements(co.email_jsonb) e),
                    (select string_agg(p ->> 'number', ' ') from jsonb_array_elements(co.phone_jsonb) p))
            from public.contacts co
            where co.fts @@ %1$L::tsquery
            order by co.first_seen desc nulls last
            limit %2$s $q$,
        'deals', $q$
            select 'deals', d.id, d.name,
                (select dc.name from public.companies dc where dc.id = d.company_id), null::bigint, d.id, d.created_at,
                concat_ws(' · ', variadic d.categories || d.description)
            from public.deals d
            where d.archived_at is null and d.fts @@ %1$L::tsquery
            order by d.created_at desc
            limit %2$s $q$,
        'tasks', $q$
            select 'tasks', t.id, left(t.text, 200),
                (select concat_ws(' ', tc.first_name, tc.last_name) from public.contacts tc where tc.id = t.contact_id),
                t.contact_id, null::bigint, t.created_at,
                concat_ws(' · ', t.text, t.type)
            from public.tasks t
            where t.done_date is null and t.fts @@ %1$L::tsquery
            order by t.created_at desc
            limit %2$s $q$,
        'contact_notes', $q$
            select 'contact_notes', cn.id, left(cn.text, 200),
                (select concat_ws(' ', nc.first_name, nc.last_name) from public.contacts nc where nc.id = cn.contact_id),
                cn.contact_id, null::bigint, cn.date,
                concat_ws(' · ', cn.text, public.search_attachment_titles(cn.attachments))
            from public.contact_notes cn
            where cn.fts @@ %1$L::tsquery
            order by cn.date desc nulls last
            limit %2$s $q$,
        'deal_notes', $q$
            select 'deal_notes', dn.id, left(dn.text, 200), nd.name, null::bigint, dn.deal_id, dn.date,
                concat_ws(' · ', dn.text, public.search_attachment_titles(dn.attachments))
            from public.deal_notes dn
                join public.deals nd on nd.id = dn.deal_id
            where nd.archived_at is null and dn.fts @@ %1$L::tsquery
            order by dn.date desc nulls last
            limit %2$s $q$
    );
    row_limit constant integer := least(coalesce(max_results, 50), 200);
    branches text[];
begin
    if tsq is null or row_limit < 1 then
        return;
    end if;

    select array_agg(format('(%s)', format(template, tsq::text, row_limit)))
    into branches
    from jsonb_each_text(branch_templates) as b(name, template)
    where resources is null or b.name = any(resources);

    if branches is null then
        return;
    end if;

    return query execute format(
        'select * from (%s) results order by 7 desc nulls last',
        array_to_string(branches, ' union all ')
    );
end
$_$;

-- =============================================================== 20261030125021_user_invitations.sql
create table "public"."user_invitations" (
    "user_id" uuid not null
);

alter table "public"."user_invitations" enable row level security;

CREATE UNIQUE INDEX user_invitations_pkey ON public.user_invitations USING btree (user_id);

alter table "public"."user_invitations" add constraint "user_invitations_pkey" PRIMARY KEY using index "user_invitations_pkey";

revoke all on table "public"."user_invitations" from "anon", "authenticated";

grant all on table "public"."user_invitations" to "service_role";

set check_function_bodies = off;

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  sales_count int;
begin
  select count(id) into sales_count
  from public.sales;

  delete from public.user_invitations where user_id = new.id;
  if sales_count > 0 and not found and not new.is_sso_user then
    raise exception 'Sign up is not allowed';
  end if;

  insert into public.sales (first_name, last_name, email, user_id, administrator)
  values (
    coalesce(new.raw_user_meta_data ->> 'first_name', new.raw_user_meta_data -> 'custom_claims' ->> 'first_name', 'Pending'),
    coalesce(new.raw_user_meta_data ->> 'last_name', new.raw_user_meta_data -> 'custom_claims' ->> 'last_name', 'Pending'),
    new.email,
    new.id,
    case when sales_count > 0 then FALSE else TRUE end
  );
  return new;
end;
$function$
;

-- =============================================================== 20261102084227_global_search_rank_name_matches.sql
-- Weight the name A in the fts documents of companies, contacts and deals, so
-- global_search() can rank them by relevance and list name matches first.
-- db diff turns a generated column change into an invalid "set default": the
-- fts columns are dropped and rebuilt instead, with their indexes and
-- statistics target.
alter table "public"."companies" drop column "fts";

alter table "public"."contacts" drop column "fts";

alter table "public"."deals" drop column "fts";

alter table public.companies add column fts tsvector generated always as (
    setweight(public.search_document(name), 'A')
    || public.search_document(sector, description, website::text, phone_number, zipcode, city, state_abbr)
) stored;

alter table public.contacts add column fts tsvector generated always as (
    setweight(public.search_document(first_name, last_name), 'A')
    || public.search_document(
        title,
        background,
        jsonb_path_query_array(email_jsonb, '$[*]."email"')::text,
        jsonb_path_query_array(phone_jsonb, '$[*]."number"')::text
    )
) stored;

alter table public.deals add column fts tsvector generated always as (
    setweight(public.search_document(name), 'A')
    || public.search_document(variadic array[description] || categories)
) stored;

create index companies_fts_idx on public.companies using gin (fts);

create index contacts_fts_idx on public.contacts using gin (fts);

create index deals_fts_idx on public.deals using gin (fts) where archived_at is null;

alter table public.contacts alter column fts set statistics 10000;

set check_function_bodies = off;

CREATE OR REPLACE FUNCTION public.global_search(query text, resources text[] DEFAULT NULL::text[], max_results integer DEFAULT 50)
 RETURNS TABLE(resource text, record_id bigint, title text, subtitle text, contact_id bigint, deal_id bigint, date timestamp with time zone, content text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
#variable_conflict use_column
declare
    tsq tsquery := public.search_query(query);
    row_limit constant integer := least(coalesce(max_results, 50), 200);
begin
    if tsq is null or row_limit < 1 then
        return;
    end if;

    return query
    select resource, record_id, title, subtitle, contact_id, deal_id, date, content
    from (
        (select 'companies' as resource, c.id as record_id, c.name as title, c.sector as subtitle,
            null::bigint as contact_id, null::bigint as deal_id, c.created_at as date,
            concat_ws(' · ', c.sector, c.description, c.website::text, c.phone_number, c.zipcode, c.city, c.state_abbr) as content,
            ts_rank(c.fts, tsq) as rank
        from public.companies c
        where (resources is null or 'companies' = any(resources)) and c.fts @@ tsq
        order by rank desc, c.created_at desc
        limit row_limit)
        union all
        (select 'contacts', co.id, concat_ws(' ', co.first_name, co.last_name),
            (select cc.name from public.companies cc where cc.id = co.company_id), co.id, null::bigint, co.first_seen,
            concat_ws(' · ', co.title, co.background,
                (select string_agg(e ->> 'email', ' ') from jsonb_array_elements(co.email_jsonb) e),
                (select string_agg(p ->> 'number', ' ') from jsonb_array_elements(co.phone_jsonb) p)),
            ts_rank(co.fts, tsq) as rank
        from public.contacts co
        where (resources is null or 'contacts' = any(resources)) and co.fts @@ tsq
        order by rank desc, co.first_seen desc nulls last
        limit row_limit)
        union all
        (select 'deals', d.id, d.name,
            (select dc.name from public.companies dc where dc.id = d.company_id), null::bigint, d.id, d.created_at,
            concat_ws(' · ', variadic d.categories || d.description),
            ts_rank(d.fts, tsq) as rank
        from public.deals d
        where (resources is null or 'deals' = any(resources)) and d.archived_at is null and d.fts @@ tsq
        order by rank desc, d.created_at desc
        limit row_limit)
        union all
        (select 'tasks', t.id, left(t.text, 200),
            (select concat_ws(' ', tc.first_name, tc.last_name) from public.contacts tc where tc.id = t.contact_id),
            t.contact_id, null::bigint, t.created_at,
            concat_ws(' · ', t.text, t.type),
            0
        from public.tasks t
        where (resources is null or 'tasks' = any(resources)) and t.done_date is null and t.fts @@ tsq
        order by t.created_at desc
        limit row_limit)
        union all
        (select 'contact_notes', cn.id, left(cn.text, 200),
            (select concat_ws(' ', nc.first_name, nc.last_name) from public.contacts nc where nc.id = cn.contact_id),
            cn.contact_id, null::bigint, cn.date,
            concat_ws(' · ', cn.text, public.search_attachment_titles(cn.attachments)),
            0
        from public.contact_notes cn
        where (resources is null or 'contact_notes' = any(resources)) and cn.fts @@ tsq
        order by cn.date desc nulls last
        limit row_limit)
        union all
        (select 'deal_notes', dn.id, left(dn.text, 200), nd.name, null::bigint, dn.deal_id, dn.date,
            concat_ws(' · ', dn.text, public.search_attachment_titles(dn.attachments)),
            0
        from public.deal_notes dn
            join public.deals nd on nd.id = dn.deal_id
        where (resources is null or 'deal_notes' = any(resources)) and nd.archived_at is null and dn.fts @@ tsq
        order by dn.date desc nulls last
        limit row_limit)
    ) results
    order by rank desc, date desc nulls last;
end
$function$
;

-- =============================================================== 20261105134224_deals_expected_closing_date_range.sql
-- Out-of-range closing dates (typos such as 5-digit years, BC dates, infinity) break the deal page.
-- Clear the existing ones first: the constraint would not apply otherwise,
-- and any later update of such a row (e.g. moving the deal on the Kanban board) would be rejected.
update "public"."deals"
set "expected_closing_date" = null
where not ("expected_closing_date" between '1900-01-01' and '2900-12-31');

alter table "public"."deals" add constraint "deals_expected_closing_date_range" check ((("expected_closing_date" >= '1900-01-01'::date) and ("expected_closing_date" <= '2900-12-31'::date)));

-- =============================================================== 20261109180000_fetch_favicon_ico.sql
-- Try https://<domain>/favicon.ico first, and only fall back to favicon.show when it is not available
CREATE OR REPLACE FUNCTION "public"."get_domain_favicon"("domain_name" "text") RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare domain_status int8;
declare domain_host text;
declare favicon_url text;

begin
    if exists (select from favicons_excluded_domains as fav where fav.domain = domain_name) then
        return null;
    end if;

    domain_host = (regexp_matches(domain_name, '^(?:https?:\/\/)?(?:[^@\/\n]+@)?(?:www\.)?([^:\/?\n]+)', 'i'))[1];
    if domain_host is null then
        return null;
    end if;

    -- Try the favicon.ico of the domain first
    favicon_url = concat('https://', domain_host, '/favicon.ico');
    begin
        perform extensions.http_set_curlopt('CURLOPT_TIMEOUT_MS', '5000');
        select status from extensions.http_get(favicon_url) into domain_status;

        if domain_status = 200 then
            return favicon_url;
        end if;
    exception
        when others then
            null;
    end;

    -- Fallback to favicon.show
    return concat('https://favicon.show/', domain_host);
end;
$$;

-- =============================================================== 20261122100000_hub_sales_handles.sql
-- team hub, issue 21 (B2). Ours, not upstream's. Undo: reverts/ (same file name).
--
-- sales: each teammate gets a handle and the prefix of their
-- person codes. Upstream creates the sales row at sign-up, before a handle
-- can be named, so both columns are nullable and are set afterwards by an
-- administrator with set_teammate_handle().

-- The team: one row per teammate, loaded from team.json by
-- `python3 scripts/team.py sql`. Nothing else names the handles.
create table public.team_members (
    handle text primary key check (handle ~ '^[a-z][a-z0-9-]{1,30}$'),
    id_prefix text not null unique check (id_prefix ~ '^[A-Z]{2}$'),
    name text not null default ''
);

alter table public.team_members enable row level security;
revoke all on table public.team_members from public, anon, authenticated;
grant select on table public.team_members to authenticated, service_role;
create policy team_members_read on public.team_members
    for select to authenticated using (true);

alter table public.sales
    add column handle text,
    add column id_prefix text;

alter table public.sales
    add constraint sales_handle_key unique (handle),
    add constraint sales_id_prefix_key unique (id_prefix),
    add constraint sales_handle_known foreign key (handle) references public.team_members (handle),
    add constraint sales_id_prefix_matches_handle check ((handle is null) = (id_prefix is null));

-- handle -> prefix, from team_members. Null for anything else.
create function public.hub_prefix_for_handle(handle text) returns text
    language sql stable
    set search_path to ''
    as $$
        select tm.id_prefix from public.team_members tm where tm.handle = $1
    $$;

revoke all on function public.hub_prefix_for_handle(text) from public, anon, authenticated, service_role;
grant execute on function public.hub_prefix_for_handle(text) to authenticated, service_role;

-- Holds on every write to sales, whichever way it comes: the prefix is always
-- the handle's, and a handle does not change once that teammate owns a person
-- (their person codes carry the prefix).
create function public.hub_sales_handle_rule() returns trigger
    language plpgsql security definer
    set search_path to ''
    as $$
begin
    if tg_op = 'UPDATE'
        and new.handle is distinct from old.handle
        and exists (select 1 from public.contacts c where c.sales_id = old.id) then
        raise exception 'a handle cannot change once the teammate owns a person';
    end if;
    new.id_prefix := public.hub_prefix_for_handle(new.handle);
    return new;
end;
$$;

revoke all on function public.hub_sales_handle_rule() from public, anon, authenticated, service_role;

create trigger hub_sales_handle_rule
    before insert or update on public.sales
    for each row execute function public.hub_sales_handle_rule();

-- The one way a teammate gets a handle. Called by an administrator through
-- the API, or by the database owner in a direct SQL session.
create function public.set_teammate_handle(user_email text, handle text) returns text
    language plpgsql security definer
    set search_path to ''
    as $$
declare
    v_email text := lower(btrim($1));
    v_handle text := lower(btrim($2));
    v_owner text;
    v_sales_id bigint;
    v_current text;
begin
    if auth.uid() is not null then
        -- a signed in caller: administrators only
        if not public.is_admin() then
            raise exception 'only an administrator can set a handle';
        end if;
    else
        -- no sign-in: a direct session of the role that owns the table, or of a superuser
        select t.tableowner into v_owner
        from pg_catalog.pg_tables t
        where t.schemaname = 'public' and t.tablename = 'sales';
        if not (
            pg_catalog.pg_has_role(session_user, v_owner, 'usage')
            or (select r.rolsuper from pg_catalog.pg_roles r where r.rolname = session_user)
        ) then
            raise exception 'only an administrator can set a handle';
        end if;
    end if;

    if v_handle is null or public.hub_prefix_for_handle(v_handle) is null then
        raise exception 'unknown handle: it must be one of the handles in team.json';
    end if;

    select s.id, s.handle into v_sales_id, v_current
    from public.sales s
    where lower(s.email::text) = v_email;
    if v_sales_id is null then
        raise exception 'no teammate has that email';
    end if;

    if v_current is not distinct from v_handle then
        return public.hub_prefix_for_handle(v_handle);
    end if;

    if exists (select 1 from public.sales s where s.handle = v_handle and s.id <> v_sales_id) then
        raise exception 'that handle is already taken';
    end if;

    if exists (select 1 from public.contacts c where c.sales_id = v_sales_id) then
        raise exception 'a handle cannot change once the teammate owns a person';
    end if;

    update public.sales s set handle = v_handle where s.id = v_sales_id;
    return public.hub_prefix_for_handle(v_handle);
end;
$$;

revoke all on function public.set_teammate_handle(text, text) from public, anon, authenticated, service_role;
grant execute on function public.set_teammate_handle(text, text) to authenticated, service_role;

-- =============================================================== 20261122100100_hub_contacts.sql
-- team hub, issue 21 (B2). Ours, not upstream's. Undo: reverts/ (same file name).
--
-- contacts become people: a person code, a slug and a name key given by the
-- database on insert and never changed, the seven statuses, the stage one
-- duplicate rules, and no fetch of an avatar or an icon from the internet.
-- Written for a contacts table with no rows (the new columns are not null).

-- Upstream fetches an avatar from gravatar.com or the email's domain when a
-- contact is saved, and an icon from the company's website when a company is
-- saved. Both triggers go, found by the function they call. The functions stay.
do $$
declare
    t record;
begin
    for t in
        select tg.tgname, tg.tgrelid::regclass as rel
        from pg_catalog.pg_trigger tg
            join pg_catalog.pg_proc p on p.oid = tg.tgfoid
            join pg_catalog.pg_namespace n on n.oid = p.pronamespace
        where not tg.tgisinternal
            and n.nspname = 'public'
            and tg.tgrelid in ('public.contacts'::regclass, 'public.companies'::regclass)
            and p.proname in ('handle_contact_saved', 'handle_company_saved',
                              'get_avatar_for_email', 'get_domain_favicon')
    loop
        execute format('drop trigger %I on %s', t.tgname, t.rel);
    end loop;
end;
$$;

-- The name folded as normalize_name() in scripts/team.py folds it: accents to
-- ASCII, lowercase, periods and apostrophes dropped, other punctuation to one
-- space, titles and credentials dropped. Empty when nothing is left.
create function public.hub_name_fold(name text) returns text
    language plpgsql immutable
    set search_path to ''
    as $$
declare
    v text;
begin
    if name is null then
        return '';
    end if;
    v := normalize(name, NFKD);
    -- combining marks, left behind by the decomposition
    v := regexp_replace(v, '[̀-ͯ҃-҉᪰-᫿᷀-᷿⃐-⃿︠-︯]', '', 'g');
    v := lower(v);
    v := replace(v, '.', '');
    v := regexp_replace(v, '[''‘’ʼ`]', '', 'g');
    v := regexp_replace(v, '[^a-z0-9]+', ' ', 'g');
    select coalesce(string_agg(u.token, ' ' order by u.ord), '')
    into v
    from unnest(string_to_array(btrim(v), ' ')) with ordinality as u(token, ord)
    where u.token <> ''
        and u.token not in ('dr', 'md', 'rn', 'np', 'pa', 'phd', 'do', 'mr', 'mrs', 'ms');
    return v;
end;
$$;

-- What two spellings of one person share. The folded name; or, when the name
-- folds to nothing because it is written in another script, the name as
-- written, trimmed and lowercased. Empty for a name that is only a title,
-- only punctuation or only spaces.
create function public.hub_name_key(name text) returns text
    language plpgsql immutable
    set search_path to ''
    as $$
declare
    v_fold text := public.hub_name_fold(name);
    v_plain text := btrim(regexp_replace(coalesce(name, ''), '\s+', ' ', 'g'));
begin
    if v_fold <> '' then
        return v_fold;
    end if;
    if v_plain ~ '[^\u0001-\u007F]' then
        return lower(v_plain);
    end if;
    return '';
end;
$$;

revoke all on function public.hub_name_fold(text) from public, anon, authenticated, service_role;
revoke all on function public.hub_name_key(text) from public, anon, authenticated, service_role;
grant execute on function public.hub_name_fold(text) to authenticated, service_role;
grant execute on function public.hub_name_key(text) to authenticated, service_role;

alter table public.contacts
    add column person_code text not null,
    add column slug text not null,
    add column name_key text not null,
    add column quote_by_name boolean not null default false,
    add column contact_key text,
    add column referred_by text,
    add column referred_by_contact_id bigint;

alter table public.contacts
    alter column sales_id set not null,
    alter column status set default 'to-contact',
    alter column status set not null;

alter table public.contacts
    add constraint contacts_person_code_key unique (person_code),
    add constraint contacts_slug_key unique (slug),
    add constraint contacts_name_key_key unique (name_key),
    add constraint contacts_person_code_format check (person_code ~ '^[A-Z]{2}-[0-9]{2,}$'),
    add constraint contacts_status_known check (status in (
        'to-contact', 'contacted', 'replied', 'scheduled', 'interviewed', 'declined', 'do-not-contact')),
    add constraint contacts_referred_by_contact_id_fkey
        foreign key (referred_by_contact_id) references public.contacts(id);

create unique index contacts_contact_key_key on public.contacts using btree (contact_key)
    where contact_key is not null;

-- On insert the database gives the person code, the slug, the name key and
-- the contact key, whether the row comes from the app or from a function.
create function public.hub_contact_before_insert() returns trigger
    language plpgsql security definer
    set search_path to ''
    as $$
declare
    v_prefix text;
    v_name text;
    v_fold text;
    v_key text;
    v_other text;
    v_detail text;
    v_n integer;
    v_code text;
    v_base text;
    v_slug text;
    v_i integer := 1;
begin
    select s.id_prefix into v_prefix from public.sales s where s.id = new.sales_id;
    if v_prefix is null then
        raise exception 'this teammate has no handle yet';
    end if;

    v_name := btrim(coalesce(new.first_name, '') || ' ' || coalesce(new.last_name, ''));
    v_fold := public.hub_name_fold(v_name);
    v_key := public.hub_name_key(v_name);
    if v_key = '' then
        raise exception 'a person needs a name';
    end if;

    if new.status is null then
        new.status := 'to-contact';
    end if;

    -- The first contact detail given. One passed as contact_key is also filed
    -- under its kind; without one, the first email, phone or LinkedIn address
    -- of the row is taken.
    v_detail := nullif(btrim(coalesce(new.contact_key, '')), '');
    if v_detail is not null then
        if position('@' in v_detail) > 0 then
            if new.email_jsonb is null or jsonb_typeof(new.email_jsonb) <> 'array'
                or jsonb_array_length(new.email_jsonb) = 0 then
                new.email_jsonb := jsonb_build_array(
                    jsonb_build_object('email', lower(v_detail), 'type', 'Work'));
            end if;
        elsif lower(v_detail) like '%linkedin.com%' then
            if coalesce(btrim(new.linkedin_url), '') = '' then
                new.linkedin_url := v_detail;
            end if;
        elsif v_detail ~ '^[0-9 +()-]+$' and v_detail ~ '[0-9]' then
            if new.phone_jsonb is null or jsonb_typeof(new.phone_jsonb) <> 'array'
                or jsonb_array_length(new.phone_jsonb) = 0 then
                new.phone_jsonb := jsonb_build_array(
                    jsonb_build_object('number', v_detail, 'type', 'Work'));
            end if;
        end if;
    else
        if jsonb_typeof(new.email_jsonb) = 'array' then
            v_detail := nullif(btrim(coalesce(new.email_jsonb -> 0 ->> 'email', '')), '');
        end if;
        if v_detail is null and jsonb_typeof(new.phone_jsonb) = 'array' then
            v_detail := nullif(btrim(coalesce(new.phone_jsonb -> 0 ->> 'number', '')), '');
        end if;
        if v_detail is null then
            v_detail := nullif(btrim(coalesce(new.linkedin_url, '')), '');
        end if;
    end if;
    new.contact_key := lower(v_detail);

    -- One insert of a person at a time, so two at once can neither share a
    -- number nor both pass the duplicate checks.
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('hub.contacts.identity', 0));

    select c.person_code into v_other from public.contacts c where c.name_key = v_key limit 1;
    if v_other is not null then
        raise exception 'this person is already on file as %', v_other;
    end if;
    if new.contact_key is not null then
        select c.person_code into v_other from public.contacts c
        where c.contact_key = new.contact_key limit 1;
        if v_other is not null then
            raise exception 'this contact detail is already on file for %', v_other;
        end if;
    end if;

    select coalesce(max(substring(c.person_code from '[0-9]+$')::integer), 0) + 1
    into v_n
    from public.contacts c
    where c.person_code like v_prefix || '-%';
    v_code := v_prefix || '-' || case when v_n < 10 then '0' || v_n::text else v_n::text end;

    v_base := rtrim(left(replace(v_fold, ' ', '-'), 80), '-');
    if v_base = '' then
        v_base := 'person-' || lower(v_code);
    end if;
    v_slug := v_base;
    while exists (select 1 from public.contacts c where c.slug = v_slug) loop
        v_i := v_i + 1;
        v_slug := v_base || '-' || v_i::text;
    end loop;

    new.person_code := v_code;
    new.slug := v_slug;
    new.name_key := v_key;
    return new;
end;
$$;

-- On update the three given values stay as they are, a status sent as null
-- keeps the old one, a new owner must have a handle, and a changed contact
-- key is held to the same no sharing rule.
create function public.hub_contact_before_update() returns trigger
    language plpgsql security definer
    set search_path to ''
    as $$
declare
    v_other text;
begin
    if new.person_code is distinct from old.person_code then
        raise exception 'a person code is never changed';
    end if;
    if new.slug is distinct from old.slug then
        raise exception 'a slug is never changed';
    end if;
    if new.name_key is distinct from old.name_key then
        raise exception 'a name key is never changed';
    end if;
    if new.status is null then
        new.status := old.status;
    end if;
    if new.sales_id is distinct from old.sales_id
        and not exists (select 1 from public.sales s
                        where s.id = new.sales_id and s.id_prefix is not null) then
        raise exception 'this teammate has no handle yet';
    end if;
    if new.contact_key is distinct from old.contact_key then
        new.contact_key := lower(nullif(btrim(coalesce(new.contact_key, '')), ''));
        if new.contact_key is not null then
            perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('hub.contacts.identity', 0));
            select c.person_code into v_other from public.contacts c
            where c.contact_key = new.contact_key and c.id <> old.id limit 1;
            if v_other is not null then
                raise exception 'this contact detail is already on file for %', v_other;
            end if;
        end if;
    end if;
    return new;
end;
$$;

revoke all on function public.hub_contact_before_insert() from public, anon, authenticated, service_role;
revoke all on function public.hub_contact_before_update() from public, anon, authenticated, service_role;

-- Named to fire after upstream's before insert triggers (they fire in name
-- order), so the owner upstream fills in from the sign-in is already there.
create trigger zz_hub_1_contact_identity
    before insert on public.contacts
    for each row execute function public.hub_contact_before_insert();

create trigger zz_hub_1_contact_fixed
    before update on public.contacts
    for each row execute function public.hub_contact_before_update();

-- The people list reads this view, so it gains the new columns. A view cannot
-- take new columns in the middle, so it is dropped and made again.
drop view public.contacts_summary;

create view public.contacts_summary with (security_invoker = on) as
select
    co.id,
    co.first_name,
    co.last_name,
    co.gender,
    co.title,
    co.background,
    co.avatar,
    co.first_seen,
    co.last_seen,
    co.has_newsletter,
    co.status,
    co.tags,
    co.company_id,
    co.sales_id,
    co.linkedin_url,
    co.email_jsonb,
    co.phone_jsonb,
    (jsonb_path_query_array(co.email_jsonb, '$[*]."email"'))::text as email_fts,
    (jsonb_path_query_array(co.phone_jsonb, '$[*]."number"'))::text as phone_fts,
    c.name as company_name,
    count(distinct t.id) filter (where t.done_date is null) as nb_tasks,
    co.person_code,
    co.slug,
    co.name_key,
    co.quote_by_name,
    co.contact_key,
    co.referred_by,
    co.referred_by_contact_id
from public.contacts co
    left join public.tasks t on co.id = t.contact_id
    left join public.companies c on co.company_id = c.id
group by co.id, c.name;

revoke all on table public.contacts_summary from public, anon, authenticated, service_role;
grant all on table public.contacts_summary to authenticated;
grant all on table public.contacts_summary to service_role;

-- =============================================================== 20261122100200_hub_contact_notes.sql
-- team hub, issue 21 (B2). Ours, not upstream's. Undo: reverts/ (same file name).
--
-- contact_notes become touches: a channel, a next step and its due date, and
-- the view of who needs a follow-up. Written for a table with no rows.

alter table public.contact_notes
    add column channel text not null default 'other',
    add column next_step text,
    add column next_due date;

alter table public.contact_notes
    alter column date set not null,
    alter column sales_id set not null,
    alter column text set not null;

alter table public.contact_notes
    add constraint contact_notes_channel_known check (channel in (
        'email', 'linkedin', 'phone', 'intro', 'in-person', 'other')),
    add constraint contact_notes_next_due_needs_next_step check (
        next_due is null or (next_step is not null and btrim(next_step) <> ''));

-- Upstream's clients send a missing date as an explicit null, which skips the
-- column default. A touch with no date given happened now.
create function public.hub_contact_note_defaults() returns trigger
    language plpgsql
    set search_path to ''
    as $$
begin
    if new.date is null then
        new.date := now();
    end if;
    return new;
end;
$$;

revoke all on function public.hub_contact_note_defaults() from public, anon, authenticated, service_role;

create trigger hub_contact_note_defaults
    before insert on public.contact_notes
    for each row execute function public.hub_contact_note_defaults();

-- Per person, the newest touch that has a next step, with its due date.
create view public.follow_ups with (security_invoker = on) as
select distinct on (cn.contact_id)
    cn.contact_id,
    co.person_code,
    co.slug,
    co.sales_id as owner_id,
    cn.id as contact_note_id,
    cn.date,
    cn.sales_id,
    cn.channel,
    cn.next_step,
    cn.next_due
from public.contact_notes cn
    join public.contacts co on co.id = cn.contact_id
where cn.next_step is not null and btrim(cn.next_step) <> ''
order by cn.contact_id, cn.date desc, cn.id desc;

revoke all on table public.follow_ups from public, anon, authenticated, service_role;
grant select on table public.follow_ups to authenticated;
grant select on table public.follow_ups to service_role;

-- =============================================================== 20261122100300_hub_interviews.sql
-- team hub, issue 21 (B2). Ours, not upstream's. Undo: reverts/ (same file name).
--
-- Interviews, their verbatim transcripts, their hypothesis links and the
-- inbox of recordings not yet tied to a person. All four are "function only":
-- a signed in teammate reads them, and rows change only inside the fixed
-- write actions of the next issue, which run as the owner. So no insert,
-- update or delete is granted here to anyone but the owner.

create table public.interviews (
    id bigint generated always as identity primary key,
    contact_id bigint not null references public.contacts(id),
    date date not null,
    interviewer_id bigint not null references public.sales(id),
    source text not null,
    granola_id text,
    consent_to_record boolean not null,
    title text not null,
    overview text not null,
    created_at timestamp with time zone not null default now(),
    created_by bigint not null references public.sales(id),
    constraint interviews_source_known check (source in ('granola', 'paste', 'other')),
    constraint interviews_consent_given check (consent_to_record is true)
);

create unique index interviews_granola_id_key on public.interviews using btree (granola_id)
    where granola_id is not null;
create index interviews_contact_id_idx on public.interviews using btree (contact_id);

-- sha256 of a text as hex. convert_to() is only STABLE because conversions
-- can be redefined; to UTF8 in a UTF8 database it is fixed, so the wrapper is
-- immutable and a generated column can use it.
create function public.hub_sha256(value text) returns text
    language sql immutable strict parallel safe
    set search_path to ''
    as $$ select pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(value, 'UTF8')), 'hex') $$;

revoke all on function public.hub_sha256(text) from public, anon, authenticated, service_role;
grant execute on function public.hub_sha256(text) to authenticated, service_role;

create table public.interview_transcripts (
    interview_id bigint primary key references public.interviews(id),
    body text not null,
    reported_chars integer,
    chars integer generated always as (char_length(body)) stored,
    sha256 text generated always as (public.hub_sha256(body)) stored,
    constraint interview_transcripts_body_min_length check (char_length(body) >= 1000),
    constraint interview_transcripts_body_not_cut check (
        reported_chars is null or char_length(body) >= reported_chars)
);

create table public.interview_hypotheses (
    interview_id bigint not null references public.interviews(id),
    hypothesis text not null,
    stance text not null,
    why text,
    primary key (interview_id, hypothesis),
    constraint interview_hypotheses_hypothesis_format check (hypothesis ~ '^H[0-9]+$'),
    constraint interview_hypotheses_stance_known check (stance in ('supports', 'contradicts', 'unclear'))
);

create table public.call_inbox (
    id bigint generated always as identity primary key,
    granola_id text,
    source text not null,
    title text,
    recorded_on date not null,
    attendee_emails text[] not null,
    overview text,
    transcript text not null,
    reported_chars integer,
    consent_to_record boolean,
    submitted_by bigint not null references public.sales(id),
    suggested_contact_ids bigint[],
    state text not null default 'waiting',
    reason text,
    interview_id bigint references public.interviews(id),
    resolved_by bigint references public.sales(id),
    resolved_at timestamp with time zone,
    constraint call_inbox_source_known check (source in ('granola', 'paste', 'other')),
    constraint call_inbox_state_known check (state in ('waiting', 'confirmed', 'dismissed'))
);

create unique index call_inbox_granola_id_key on public.call_inbox using btree (granola_id)
    where granola_id is not null;

-- An interview with no transcript row is refused when its transaction commits.
create function public.hub_interview_needs_transcript() returns trigger
    language plpgsql security definer
    set search_path to ''
    as $$
begin
    if not exists (select 1 from public.interview_transcripts t where t.interview_id = new.id) then
        raise exception 'an interview is saved with its transcript, or not at all';
    end if;
    return null;
end;
$$;

revoke all on function public.hub_interview_needs_transcript() from public, anon, authenticated, service_role;

create constraint trigger hub_interview_needs_transcript
    after insert on public.interviews
    deferrable initially deferred
    for each row execute function public.hub_interview_needs_transcript();

-- A status that claims contact needs a touch on file; interviewed needs an
-- interview. Checked when the status is set or changed.
create function public.hub_contact_status_rule() returns trigger
    language plpgsql security definer
    set search_path to ''
    as $$
begin
    if tg_op = 'UPDATE' and new.status is not distinct from old.status then
        return new;
    end if;
    if new.status in ('contacted', 'replied', 'scheduled')
        and not exists (select 1 from public.contact_notes n where n.contact_id = new.id) then
        raise exception 'the status % needs at least one touch on file', new.status;
    end if;
    if new.status = 'interviewed'
        and not exists (select 1 from public.interviews i where i.contact_id = new.id) then
        raise exception 'the status interviewed needs an interview on file';
    end if;
    return new;
end;
$$;

revoke all on function public.hub_contact_status_rule() from public, anon, authenticated, service_role;

create trigger zz_hub_2_contact_status
    before insert or update on public.contacts
    for each row execute function public.hub_contact_status_rule();

-- Row level security: read by a signed in teammate, nothing else.
alter table public.interviews enable row level security;
alter table public.interview_transcripts enable row level security;
alter table public.interview_hypotheses enable row level security;
alter table public.call_inbox enable row level security;

create policy "Enable read access for authenticated users" on public.interviews
    for select to authenticated using (true);
create policy "Enable read access for authenticated users" on public.interview_transcripts
    for select to authenticated using (true);
create policy "Enable read access for authenticated users" on public.interview_hypotheses
    for select to authenticated using (true);
create policy "Enable read access for authenticated users" on public.call_inbox
    for select to authenticated using (true);

revoke all on table public.interviews from public, anon, authenticated, service_role;
revoke all on table public.interview_transcripts from public, anon, authenticated, service_role;
revoke all on table public.interview_hypotheses from public, anon, authenticated, service_role;
revoke all on table public.call_inbox from public, anon, authenticated, service_role;
revoke all on sequence public.interviews_id_seq from public, anon, authenticated, service_role;
revoke all on sequence public.call_inbox_id_seq from public, anon, authenticated, service_role;

grant select on table public.interviews to authenticated, service_role;
grant select on table public.interview_transcripts to authenticated, service_role;
grant select on table public.interview_hypotheses to authenticated, service_role;
grant select on table public.call_inbox to authenticated, service_role;

-- =============================================================== 20261122100400_hub_security.sql
-- team hub, issue 21 (B2). Ours, not upstream's. Undo: reverts/ (same file name).
--
-- The security rules of docs/SCHEMA.md on top of upstream's "any signed in
-- user may do anything": nothing is deleted, a touch is changed only by the
-- teammate who wrote it, the anon role holds nothing on these tables, and a
-- read only role exists for the markdown export.

-- Soft delete only: the delete policies go. With row level security on and no
-- delete policy, a delete by a signed in teammate removes no row.
drop policy "Company Delete Policy" on public.companies;
drop policy "Contact Delete Policy" on public.contacts;
drop policy "Contact Notes Delete Policy" on public.contact_notes;

-- A touch is updated only by the teammate whose sales_id is on the row.
drop policy "Contact Notes Update policy" on public.contact_notes;
create policy "Contact Notes Update policy" on public.contact_notes
    for update to authenticated
    using (sales_id = (select s.id from public.sales s where s.user_id = (select auth.uid())))
    with check (sales_id = (select s.id from public.sales s where s.user_id = (select auth.uid())));

-- People, interviews and transcripts are never deleted, by any role, the
-- owner included. A transcript is never changed either.
create function public.hub_refuse_delete() returns trigger
    language plpgsql
    set search_path to ''
    as $$
begin
    raise exception 'people and interviews are never deleted';
end;
$$;

create function public.hub_refuse_transcript_update() returns trigger
    language plpgsql
    set search_path to ''
    as $$
begin
    raise exception 'a transcript is never changed';
end;
$$;

revoke all on function public.hub_refuse_delete() from public, anon, authenticated, service_role;
revoke all on function public.hub_refuse_transcript_update() from public, anon, authenticated, service_role;

create trigger hub_no_delete before delete on public.contacts
    for each row execute function public.hub_refuse_delete();
create trigger hub_no_truncate before truncate on public.contacts
    for each statement execute function public.hub_refuse_delete();

create trigger hub_no_delete before delete on public.interviews
    for each row execute function public.hub_refuse_delete();
create trigger hub_no_truncate before truncate on public.interviews
    for each statement execute function public.hub_refuse_delete();

create trigger hub_no_delete before delete on public.interview_transcripts
    for each row execute function public.hub_refuse_delete();
create trigger hub_no_truncate before truncate on public.interview_transcripts
    for each statement execute function public.hub_refuse_delete();
create trigger hub_no_update before update on public.interview_transcripts
    for each row execute function public.hub_refuse_transcript_update();

-- The anon role gets nothing on any table of docs/SCHEMA.md. Upstream grants
-- it everything and relies on there being no policy.
revoke all on table public.sales from anon;
revoke all on table public.companies from anon;
revoke all on table public.contacts from anon;
revoke all on table public.contact_notes from anon;

-- A read only role for the markdown export. No login and no password here: a
-- person gives it a password at go-live.
do $$
begin
    if not exists (select 1 from pg_catalog.pg_roles where rolname = 'hub_export') then
        create role hub_export nologin noinherit;
    end if;
end;
$$;

grant usage on schema public to hub_export;
grant select on table public.sales to hub_export;
grant select on table public.companies to hub_export;
grant select on table public.contacts to hub_export;
grant select on table public.contact_notes to hub_export;
grant select on table public.interviews to hub_export;
grant select on table public.interview_transcripts to hub_export;
grant select on table public.interview_hypotheses to hub_export;
grant select on table public.call_inbox to hub_export;
grant select on table public.follow_ups to hub_export;

create policy "Enable read access for the export" on public.sales
    for select to hub_export using (true);
create policy "Enable read access for the export" on public.companies
    for select to hub_export using (true);
create policy "Enable read access for the export" on public.contacts
    for select to hub_export using (true);
create policy "Enable read access for the export" on public.contact_notes
    for select to hub_export using (true);
create policy "Enable read access for the export" on public.interviews
    for select to hub_export using (true);
create policy "Enable read access for the export" on public.interview_transcripts
    for select to hub_export using (true);
create policy "Enable read access for the export" on public.interview_hypotheses
    for select to hub_export using (true);
create policy "Enable read access for the export" on public.call_inbox
    for select to hub_export using (true);

-- =============================================================== 20261122100500_hub_gaps.sql
-- team hub, issue 21 reopened (B2). Ours, not upstream's. Undo: reverts/ (same file name).
--
-- Two gaps left by the first five migrations.

-- 1. The functions that fetched from the internet were still there after
-- their triggers were dropped, and upstream grants them to anon. Through the
-- API, anyone holding the public key could call get_domain_favicon with a
-- domain of their choosing and have the database request it. Nothing in the
-- app, the edge functions or the database calls any of the four, so they go.
drop function public.handle_contact_saved();
drop function public.handle_company_saved();
drop function public.get_avatar_for_email(text);
drop function public.get_domain_favicon(text);

-- 2. Touches and the inbox are never deleted either, by any role, the owner
-- and the service role included. Until now contact_notes had only lost its
-- delete policy, which stops a signed in teammate and nobody else.
create trigger hub_no_delete before delete on public.contact_notes
    for each row execute function public.hub_refuse_delete();
create trigger hub_no_truncate before truncate on public.contact_notes
    for each statement execute function public.hub_refuse_delete();

create trigger hub_no_delete before delete on public.call_inbox
    for each row execute function public.hub_refuse_delete();
create trigger hub_no_truncate before truncate on public.call_inbox
    for each statement execute function public.hub_refuse_delete();

-- =============================================================== 20261122110000_hub_audit.sql
-- team hub, issue 22 (B3). Ours, not upstream's. Undo: reverts/ (same file name).
--
-- The audit table: one row for every changed row of the eight tables of
-- docs/SCHEMA.md, written by a trigger, so a change made by a fixed action,
-- by the app or by hand in the dashboard is recorded the same way. Nobody
-- can change or remove what is recorded.

create table public.audit_log (
    id bigint generated always as identity primary key,
    at timestamp with time zone not null default now(),
    actor_user_id uuid,
    actor_handle text,
    via text not null,
    action text not null,
    table_name text not null,
    row_id text not null,
    old_row jsonb,
    new_row jsonb,
    constraint audit_log_via_known check (via in ('ui', 'claude', 'job', 'dashboard'))
);

create index audit_log_row_idx on public.audit_log using btree (table_name, row_id);

-- Read by a signed in teammate. No policy and no grant for any write.
alter table public.audit_log enable row level security;
create policy "Enable read access for authenticated users" on public.audit_log
    for select to authenticated using (true);

revoke all on table public.audit_log from public, anon, authenticated, service_role;
revoke all on sequence public.audit_log_id_seq from public, anon, authenticated, service_role;
grant select on table public.audit_log to authenticated, service_role;

-- Writes the audit row. A fixed action names itself and its via in two
-- settings that last for its own call; outside one, the action is the kind
-- of write and via says who the session is.
create function public.hub_audit_row() returns trigger
    language plpgsql security definer
    set search_path to ''
    as $$
declare
    v_old jsonb;
    v_new jsonb;
    v_row jsonb;
    v_id text;
    v_uid uuid;
    v_handle text;
    v_action text;
    v_via text;
    v_role text;
begin
    if tg_op = 'TRUNCATE' then
        v_id := '*';
    else
        if tg_op <> 'INSERT' then
            v_old := to_jsonb(old);
        end if;
        if tg_op <> 'DELETE' then
            v_new := to_jsonb(new);
        end if;
        if tg_op = 'UPDATE' and v_old = v_new then
            return null;
        end if;
        -- A transcript is kept as its size and its hash, never as its text.
        if tg_table_name = 'interview_transcripts' then
            if v_old is not null then
                v_old := jsonb_set(v_old, '{body}',
                    jsonb_build_object('chars', v_old -> 'chars', 'sha256', v_old -> 'sha256'));
            end if;
            if v_new is not null then
                v_new := jsonb_set(v_new, '{body}',
                    jsonb_build_object('chars', v_new -> 'chars', 'sha256', v_new -> 'sha256'));
            end if;
        elsif tg_table_name = 'call_inbox' then
            if v_old is not null then
                v_old := jsonb_set(v_old, '{transcript}', jsonb_build_object(
                    'chars', char_length(v_old ->> 'transcript'),
                    'sha256', public.hub_sha256(v_old ->> 'transcript')));
            end if;
            if v_new is not null then
                v_new := jsonb_set(v_new, '{transcript}', jsonb_build_object(
                    'chars', char_length(v_new ->> 'transcript'),
                    'sha256', public.hub_sha256(v_new ->> 'transcript')));
            end if;
        end if;
        v_row := coalesce(v_new, v_old);
        v_id := case tg_table_name
            when 'interview_transcripts' then v_row ->> 'interview_id'
            when 'interview_hypotheses' then (v_row ->> 'interview_id') || ':' || (v_row ->> 'hypothesis')
            else v_row ->> 'id'
        end;
    end if;

    -- Who: the sign-in of the request, when there is one. A sign-in that
    -- cannot be read is recorded as none; it never stops the write.
    begin
        v_uid := auth.uid();
        v_role := nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role';
    exception when others then
        v_uid := null;
        v_role := null;
    end;
    if v_uid is not null then
        select s.handle into v_handle from public.sales s where s.user_id = v_uid;
    end if;

    v_action := nullif(current_setting('hub.action', true), '');
    v_via := nullif(current_setting('hub.via', true), '');
    if v_action is null or v_via is null or v_via not in ('ui', 'claude') then
        v_action := lower(tg_op);
        v_via := case
            when v_uid is not null then 'ui'
            when current_setting('role', true) = 'service_role'
                or v_role = 'service_role'
                or session_user in ('authenticator', 'service_role', 'supabase_auth_admin',
                                    'supabase_storage_admin') then 'job'
            else 'dashboard'
        end;
    end if;

    insert into public.audit_log (actor_user_id, actor_handle, via, action, table_name, row_id, old_row, new_row)
    values (v_uid, v_handle, v_via, v_action, tg_table_name, coalesce(v_id, '?'), v_old, v_new);
    return null;
end;
$$;

revoke all on function public.hub_audit_row() from public, anon, authenticated, service_role;

create trigger zzz_hub_audit after insert or update or delete on public.sales
    for each row execute function public.hub_audit_row();
create trigger zzz_hub_audit after insert or update or delete on public.companies
    for each row execute function public.hub_audit_row();
create trigger zzz_hub_audit after insert or update or delete on public.contacts
    for each row execute function public.hub_audit_row();
create trigger zzz_hub_audit after insert or update or delete on public.contact_notes
    for each row execute function public.hub_audit_row();
create trigger zzz_hub_audit after insert or update or delete on public.interviews
    for each row execute function public.hub_audit_row();
create trigger zzz_hub_audit after insert or update or delete on public.interview_transcripts
    for each row execute function public.hub_audit_row();
create trigger zzz_hub_audit after insert or update or delete on public.interview_hypotheses
    for each row execute function public.hub_audit_row();
create trigger zzz_hub_audit after insert or update or delete on public.call_inbox
    for each row execute function public.hub_audit_row();

-- The three tables that have no "never truncated" trigger: a truncate there
-- changes rows without a row trigger firing, so it is recorded as one line.
create trigger zzz_hub_audit_truncate after truncate on public.sales
    for each statement execute function public.hub_audit_row();
create trigger zzz_hub_audit_truncate after truncate on public.companies
    for each statement execute function public.hub_audit_row();
create trigger zzz_hub_audit_truncate after truncate on public.interview_hypotheses
    for each statement execute function public.hub_audit_row();

-- What is recorded stays: no update, delete or truncate, for any role, the
-- owner included, whether or not a row would have matched.
create function public.hub_refuse_audit_change() returns trigger
    language plpgsql
    set search_path to ''
    as $$
begin
    raise exception 'the audit log is never changed';
end;
$$;

revoke all on function public.hub_refuse_audit_change() from public, anon, authenticated, service_role;

create trigger hub_no_change before update or delete or truncate on public.audit_log
    for each statement execute function public.hub_refuse_audit_change();

-- =============================================================== 20261122110100_hub_actions_people.sql
-- team hub, issue 22 (B3). Ours, not upstream's. Undo: reverts/ (same file name).
--
-- The fixed write actions for people and touches: find_person, add_person,
-- update_person, set_owner, set_status, log_touch. These are the only way
-- Claude writes, and parts of the app call them too. Each runs as the owner
-- with an empty search path, may be called by a signed in teammate only,
-- checks every argument before it writes, and refuses in one plain sentence.
-- None takes SQL, a table name or a column name.
--
-- The functions named hub_... are their shared parts. Nobody but the owner
-- may execute those, so they cannot be called through the API.

-- ------------------------------------------------------------ shared parts

-- The teammate behind the sign-in of this request, or a refusal.
create function public.hub_caller() returns public.sales
    language plpgsql stable
    set search_path to ''
    as $$
declare
    v_uid uuid;
    v_me public.sales;
begin
    begin
        v_uid := auth.uid();
    exception when others then
        v_uid := null;
    end;
    if v_uid is null then
        raise exception 'sign in first: this action is for a signed in teammate';
    end if;
    select s.* into v_me from public.sales s where s.user_id = v_uid;
    if not found then
        raise exception 'sign in first: this sign-in is not a teammate';
    end if;
    if v_me.disabled then
        raise exception 'this teammate is disabled';
    end if;
    if v_me.handle is null then
        raise exception 'this teammate has no handle yet';
    end if;
    return v_me;
end;
$$;

-- Starts a fixed action: finds the caller, checks via, and names the action
-- and its via for the audit rows the action causes.
create function public.hub_begin(action text, via text) returns public.sales
    language plpgsql
    set search_path to ''
    as $$
declare
    v_me public.sales := public.hub_caller();
begin
    if $2 is null or $2 not in ('ui', 'claude') then
        raise exception 'via must be ui or claude';
    end if;
    perform pg_catalog.set_config('hub.action', $1, true);
    perform pg_catalog.set_config('hub.via', $2, true);
    return v_me;
end;
$$;

-- Ends a fixed action: what follows in the same transaction is no longer
-- recorded under its name.
create function public.hub_end() returns void
    language plpgsql
    set search_path to ''
    as $$
begin
    perform pg_catalog.set_config('hub.action', '', true);
    perform pg_catalog.set_config('hub.via', '', true);
end;
$$;

-- A text argument that is one line: trimmed, held to its length, never cut.
-- Null when it is empty and may be.
create function public.hub_line(value text, label text, max_length integer, required boolean) returns text
    language plpgsql immutable
    set search_path to ''
    as $$
declare
    v text := btrim(coalesce($1, ''), E' \t\n\r');
begin
    if v = '' then
        if $4 then
            raise exception 'the % is empty', $2;
        end if;
        return null;
    end if;
    if v ~ '[\n\r]' then
        raise exception 'the % must be one line', $2;
    end if;
    if char_length(v) > $3 then
        raise exception 'the % is too long: % characters, the limit is %', $2, char_length(v), $3;
    end if;
    return v;
end;
$$;

-- A text argument of several lines: stored as written, held to its length.
create function public.hub_block(value text, label text, max_length integer, required boolean) returns text
    language plpgsql immutable
    set search_path to ''
    as $$
begin
    if $1 is null or btrim($1, E' \t\n\r') = '' then
        if $4 then
            raise exception 'the % is empty', $2;
        end if;
        return null;
    end if;
    if char_length($1) > $3 then
        raise exception 'the % is too long: % characters, the limit is %', $2, char_length($1), $3;
    end if;
    return $1;
end;
$$;

-- A teammate named by handle. Null or empty means the caller.
create function public.hub_teammate(handle text, label text, caller public.sales) returns public.sales
    language plpgsql stable
    set search_path to ''
    as $$
declare
    v_handle text := lower(btrim(coalesce($1, '')));
    v_who public.sales;
begin
    if v_handle = '' then
        return $3;
    end if;
    if public.hub_prefix_for_handle(v_handle) is null then
        raise exception '% ''%'' is not a team handle (see team.json)', $2, left(v_handle, 40);
    end if;
    select s.* into v_who from public.sales s where s.handle = v_handle;
    if not found then
        raise exception '% ''%'' has no handle on file yet: an administrator sets it after their first sign-in',
            $2, v_handle;
    end if;
    if v_who.disabled then
        raise exception '% ''%'' is disabled', $2, v_handle;
    end if;
    return v_who;
end;
$$;

-- A person named by code. The row is locked until the action ends, so two
-- actions on one person happen one after the other.
create function public.hub_person(person_code text) returns public.contacts
    language plpgsql
    set search_path to ''
    as $$
declare
    v_code text := upper(btrim(coalesce($1, '')));
    v_person public.contacts;
begin
    if v_code = '' then
        raise exception 'the person code is empty';
    end if;
    select c.* into v_person from public.contacts c where c.person_code = v_code for update;
    if not found then
        raise exception 'no person has the code %', left(v_code, 40);
    end if;
    return v_person;
end;
$$;

-- One person in words, for a refusal: code, name, owner, status, last touch.
create function public.hub_describe_person(contact_id bigint) returns text
    language sql stable
    set search_path to ''
    as $$
    select pg_catalog.format('%s, %s, owner %s, status %s, last touch %s',
        c.person_code,
        btrim(coalesce(c.first_name, '') || ' ' || coalesce(c.last_name, '')),
        coalesce(s.handle, '?'),
        c.status,
        coalesce((
            select pg_catalog.format('%s by %s via %s',
                (n.date at time zone 'UTC')::date, coalesce(ns.handle, '?'), n.channel)
            from public.contact_notes n
                left join public.sales ns on ns.id = n.sales_id
            where n.contact_id = c.id
            order by n.date desc, n.id desc
            limit 1), 'none'))
    from public.contacts c
        left join public.sales s on s.id = c.sales_id
    where c.id = $1
    $$;

-- The latest date it is anywhere on earth right now. A date after it is in
-- the future for every teammate, wherever they are.
create function public.hub_latest_today() returns date
    language sql stable
    set search_path to ''
    as $$ select (now() at time zone 'Pacific/Kiritimati')::date $$;

-- The company of that name, made if it is not there. Names are compared
-- without letter case.
create function public.hub_company(name text, sales_id bigint) returns bigint
    language plpgsql
    set search_path to ''
    as $$
declare
    v_id bigint;
begin
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('hub.contacts.identity', 0));
    select co.id into v_id from public.companies co
    where lower(btrim(co.name)) = lower($1)
    order by co.id
    limit 1;
    if v_id is null then
        insert into public.companies (name, sales_id) values ($1, $2) returning id into v_id;
    end if;
    return v_id;
end;
$$;

-- ---------------------------------------------------------------- find_person
create function public.find_person(query text, via text default 'ui')
    returns table (person_code text, name text, role text, organization text, owner text, status text,
                   last_touch_date date, last_touch_channel text, last_touch_text text)
    language plpgsql stable security definer
    set search_path to ''
    as $$
#variable_conflict use_column
declare
    v_q text := lower(btrim(coalesce($1, ''), E' \t\n\r'));
    v_fold text;
begin
    perform public.hub_caller();
    if $2 is null or $2 not in ('ui', 'claude') then
        raise exception 'via must be ui or claude';
    end if;
    if v_q = '' then
        raise exception 'the query is empty: give a name, a person code, a contact detail or an organization';
    end if;
    if char_length(v_q) > 300 then
        raise exception 'the query is too long: % characters, the limit is 300', char_length(v_q);
    end if;
    v_fold := public.hub_name_fold(v_q);

    return query
    select c.person_code,
           btrim(coalesce(c.first_name, '') || ' ' || coalesce(c.last_name, '')),
           c.title,
           co.name,
           s.handle,
           c.status,
           (t.date at time zone 'UTC')::date,
           t.channel,
           left(t.text, 80)
    from public.contacts c
        left join public.companies co on co.id = c.company_id
        left join public.sales s on s.id = c.sales_id
        left join lateral (
            select n.date, n.channel, n.text
            from public.contact_notes n
            where n.contact_id = c.id
            order by n.date desc, n.id desc
            limit 1) t on true
    where position(v_q in lower(c.person_code)) > 0
        or position(v_q in lower(c.slug)) > 0
        or (v_fold <> '' and position(v_fold in c.name_key) > 0)
        or position(v_q in lower(coalesce(c.first_name, '') || ' ' || coalesce(c.last_name, ''))) > 0
        or position(v_q in lower(coalesce(c.contact_key, ''))) > 0
        or position(v_q in lower(coalesce(c.linkedin_url, ''))) > 0
        or position(v_q in lower(coalesce(co.name, ''))) > 0
        or exists (
            select 1
            from jsonb_array_elements(case when jsonb_typeof(c.email_jsonb) = 'array'
                                           then c.email_jsonb else '[]'::jsonb end) e
            where position(v_q in lower(coalesce(e ->> 'email', ''))) > 0)
        or exists (
            select 1
            from jsonb_array_elements(case when jsonb_typeof(c.phone_jsonb) = 'array'
                                           then c.phone_jsonb else '[]'::jsonb end) p
            where position(v_q in lower(coalesce(p ->> 'number', ''))) > 0)
    order by split_part(c.person_code, '-', 1), substring(c.person_code from '[0-9]+$')::integer;
end;
$$;

-- ----------------------------------------------------------------- add_person
create function public.add_person(
        name text,
        owner text default null,
        role text default null,
        organization text default null,
        contact text default null,
        referred_by text default null,
        quote_by_name boolean default null,
        via text default 'ui')
    returns jsonb
    language plpgsql security definer
    set search_path to ''
    as $$
declare
    v_me public.sales := public.hub_begin('add_person', $8);
    v_name text := public.hub_line($1, 'name', 200, true);
    v_owner public.sales := public.hub_teammate($2, 'owner', v_me);
    v_role text := public.hub_line($3, 'role', 300, false);
    v_org text := public.hub_line($4, 'organization', 300, false);
    v_contact text := public.hub_line($5, 'contact', 300, false);
    v_referred text := public.hub_line($6, 'referred by', 300, false);
    v_key text;
    v_other bigint;
    v_cut integer;
    v_first text;
    v_last text;
    v_company bigint;
    v_new public.contacts;
begin
    v_key := public.hub_name_key(v_name);
    if v_key = '' then
        raise exception '''%'' is only a title or punctuation, not a name', v_name;
    end if;
    if v_key !~ '[^0-9 ]' then
        raise exception '''%'' is only a number, not a name', v_name;
    end if;

    -- One person is added at a time (the same lock the insert takes), so two
    -- teammates adding one person at once get one person and one refusal.
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('hub.contacts.identity', 0));
    select c.id into v_other from public.contacts c where c.name_key = v_key limit 1;
    if v_other is not null then
        raise exception 'already on file (same name): %', public.hub_describe_person(v_other);
    end if;
    if v_contact is not null then
        select c.id into v_other from public.contacts c where c.contact_key = lower(v_contact) limit 1;
        if v_other is not null then
            raise exception 'already on file (same contact): %', public.hub_describe_person(v_other);
        end if;
    end if;

    -- the full name splits at its last space
    v_cut := char_length(v_name) - position(' ' in reverse(v_name)) + 1;
    if position(' ' in v_name) = 0 then
        v_first := v_name;
        v_last := '';
    else
        v_first := btrim(left(v_name, v_cut - 1));
        v_last := substr(v_name, v_cut + 1);
    end if;

    if v_org is not null then
        v_company := public.hub_company(v_org, v_me.id);
    end if;

    insert into public.contacts (first_name, last_name, title, company_id, sales_id, status, contact_key,
                                 referred_by, quote_by_name, first_seen, last_seen, tags,
                                 email_jsonb, phone_jsonb)
    values (v_first, v_last, v_role, v_company, v_owner.id, 'to-contact', v_contact,
            v_referred, coalesce($7, false), now(), now(), '{}',
            '[]'::jsonb, '[]'::jsonb)
    returning * into v_new;

    perform public.hub_end();
    return jsonb_build_object(
        'person_code', v_new.person_code,
        'slug', v_new.slug,
        'name', v_name,
        'owner', v_owner.handle,
        'status', v_new.status);
end;
$$;

-- -------------------------------------------------------------- update_person
create function public.update_person(
        person_code text,
        role text default null,
        organization text default null,
        contact text default null,
        referred_by text default null,
        quote_by_name boolean default null,
        notes text default null,
        via text default 'ui')
    returns jsonb
    language plpgsql security definer
    set search_path to ''
    as $$
declare
    v_me public.sales := public.hub_begin('update_person', $8);
    v_p public.contacts := public.hub_person($1);
    v_role text := public.hub_line($2, 'role', 300, false);
    v_org text := public.hub_line($3, 'organization', 300, false);
    v_contact text := public.hub_line($4, 'contact', 300, false);
    v_referred text := public.hub_line($5, 'referred by', 300, false);
    v_notes text := public.hub_block($7, 'notes', 10000, false);
    v_other bigint;
    v_changed text[] := '{}';
begin
    if $2 is null and $3 is null and $4 is null and $5 is null and $6 is null and $7 is null then
        raise exception 'nothing to change: give at least one of role, organization, contact, referred_by, quote_by_name, notes';
    end if;

    if $2 is not null then
        v_p.title := v_role;
        v_changed := v_changed || 'role'::text;
    end if;
    if $3 is not null then
        v_p.company_id := case when v_org is null then null else public.hub_company(v_org, v_me.id) end;
        v_changed := v_changed || 'organization'::text;
    end if;
    if $4 is not null then
        if v_contact is null then
            v_p.contact_key := null;
        else
            perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('hub.contacts.identity', 0));
            select c.id into v_other from public.contacts c
            where c.contact_key = lower(v_contact) and c.id <> v_p.id limit 1;
            if v_other is not null then
                raise exception 'already on file (same contact): %', public.hub_describe_person(v_other);
            end if;
            v_p.contact_key := lower(v_contact);
            -- the detail is also filed under its kind, as on insert
            if position('@' in v_contact) > 0 then
                if jsonb_typeof(v_p.email_jsonb) is distinct from 'array' then
                    v_p.email_jsonb := '[]'::jsonb;
                end if;
                if not exists (select 1 from jsonb_array_elements(v_p.email_jsonb) e
                               where lower(e ->> 'email') = lower(v_contact)) then
                    v_p.email_jsonb := v_p.email_jsonb
                        || jsonb_build_array(jsonb_build_object('email', lower(v_contact), 'type', 'Work'));
                end if;
            elsif lower(v_contact) like '%linkedin.com%' then
                v_p.linkedin_url := v_contact;
            elsif v_contact ~ '^[0-9 +()-]+$' and v_contact ~ '[0-9]' then
                if jsonb_typeof(v_p.phone_jsonb) is distinct from 'array' then
                    v_p.phone_jsonb := '[]'::jsonb;
                end if;
                if not exists (select 1 from jsonb_array_elements(v_p.phone_jsonb) p
                               where p ->> 'number' = v_contact) then
                    v_p.phone_jsonb := v_p.phone_jsonb
                        || jsonb_build_array(jsonb_build_object('number', v_contact, 'type', 'Work'));
                end if;
            end if;
        end if;
        v_changed := v_changed || 'contact'::text;
    end if;
    if $5 is not null then
        v_p.referred_by := v_referred;
        v_changed := v_changed || 'referred_by'::text;
    end if;
    if $6 is not null then
        v_p.quote_by_name := $6;
        v_changed := v_changed || 'quote_by_name'::text;
    end if;
    if $7 is not null then
        v_p.background := v_notes;
        v_changed := v_changed || 'notes'::text;
    end if;

    update public.contacts c
    set title = v_p.title,
        company_id = v_p.company_id,
        contact_key = v_p.contact_key,
        email_jsonb = v_p.email_jsonb,
        phone_jsonb = v_p.phone_jsonb,
        linkedin_url = v_p.linkedin_url,
        referred_by = v_p.referred_by,
        quote_by_name = v_p.quote_by_name,
        background = v_p.background
    where c.id = v_p.id;

    perform public.hub_end();
    return jsonb_build_object('person_code', v_p.person_code, 'changed', to_jsonb(v_changed));
end;
$$;

-- ------------------------------------------------------------------ set_owner
create function public.set_owner(person_code text, owner text default null, via text default 'ui')
    returns jsonb
    language plpgsql security definer
    set search_path to ''
    as $$
declare
    v_me public.sales := public.hub_begin('set_owner', $3);
    v_p public.contacts := public.hub_person($1);
    v_owner public.sales := public.hub_teammate($2, 'owner', v_me);
begin
    update public.contacts c set sales_id = v_owner.id where c.id = v_p.id;
    perform public.hub_end();
    return jsonb_build_object('person_code', v_p.person_code, 'owner', v_owner.handle);
end;
$$;

-- ----------------------------------------------------------------- set_status
create function public.set_status(person_code text, status text, via text default 'ui')
    returns jsonb
    language plpgsql security definer
    set search_path to ''
    as $$
declare
    v_me public.sales := public.hub_begin('set_status', $3);
    v_p public.contacts := public.hub_person($1);
    v_status text := lower(btrim(coalesce($2, '')));
begin
    if v_status = '' then
        raise exception 'the status is empty: use to-contact, contacted, replied, scheduled, interviewed, declined or do-not-contact';
    end if;
    if v_status not in ('to-contact', 'contacted', 'replied', 'scheduled', 'interviewed', 'declined', 'do-not-contact') then
        raise exception 'status ''%'' is not allowed: use to-contact, contacted, replied, scheduled, interviewed, declined or do-not-contact',
            left(v_status, 40);
    end if;
    if v_status in ('contacted', 'replied', 'scheduled')
        and not exists (select 1 from public.contact_notes n where n.contact_id = v_p.id) then
        raise exception 'log the touch first: ''%'' needs a touch on file for %', v_status, v_p.person_code;
    end if;
    if v_status = 'interviewed'
        and not exists (select 1 from public.interviews i where i.contact_id = v_p.id) then
        raise exception 'save the interview first: ''interviewed'' needs an interview on file for %', v_p.person_code;
    end if;
    update public.contacts c set status = v_status where c.id = v_p.id;
    perform public.hub_end();
    return jsonb_build_object('person_code', v_p.person_code, 'status', v_status);
end;
$$;

-- ------------------------------------------------------------------ log_touch
create function public.log_touch(
        person_code text,
        by text default null,
        date date default null,
        channel text default null,
        what text default null,
        next_step text default null,
        next_due date default null,
        status text default null,
        via text default 'ui')
    returns jsonb
    language plpgsql security definer
    set search_path to ''
    as $$
declare
    v_me public.sales := public.hub_begin('log_touch', $9);
    v_p public.contacts := public.hub_person($1);
    v_by public.sales := public.hub_teammate($2, 'by', v_me);
    v_channel text := lower(btrim(coalesce($4, '')));
    v_what text := public.hub_block($5, 'what', 10000, true);
    v_next text := public.hub_line($6, 'next step', 300, false);
    v_status text := nullif(lower(btrim(coalesce($8, ''))), '');
    v_when timestamp with time zone;
    v_touch bigint;
begin
    if v_channel = '' then
        raise exception 'the channel is empty: use email, linkedin, phone, intro, in-person or other';
    end if;
    if v_channel not in ('email', 'linkedin', 'phone', 'intro', 'in-person', 'other') then
        raise exception 'channel ''%'' is not allowed: use email, linkedin, phone, intro, in-person or other',
            left(v_channel, 40);
    end if;
    if $3 is not null and $3 > public.hub_latest_today() then
        raise exception 'the date % is in the future', $3;
    end if;
    if $7 is not null and v_next is null then
        raise exception 'a due date needs a next step';
    end if;
    if v_status = 'interviewed' then
        raise exception 'interviewed is set by saving an interview, not by a touch';
    end if;
    if v_status is not null
        and v_status not in ('to-contact', 'contacted', 'replied', 'scheduled', 'declined', 'do-not-contact') then
        raise exception 'status ''%'' is not allowed: use to-contact, contacted, replied, scheduled, declined or do-not-contact',
            left(v_status, 40);
    end if;
    -- with no status given, the first touch on a to-contact person makes them contacted
    if v_status is null and v_p.status = 'to-contact' then
        v_status := 'contacted';
    end if;

    -- a touch with no date happened now; one with a date, at noon UTC of that day
    v_when := case when $3 is null then now()
                   else ($3::timestamp + interval '12 hours') at time zone 'UTC' end;

    insert into public.contact_notes (contact_id, date, sales_id, channel, text, next_step, next_due, status)
    values (v_p.id, v_when, v_by.id, v_channel, v_what, v_next, $7, coalesce(v_status, v_p.status))
    returning id into v_touch;

    if v_status is not null and v_status <> v_p.status then
        update public.contacts c set status = v_status where c.id = v_p.id;
    end if;

    perform public.hub_end();
    return jsonb_build_object(
        'touch_id', v_touch,
        'person_code', v_p.person_code,
        'by', v_by.handle,
        'status', coalesce(v_status, v_p.status));
end;
$$;

-- ---------------------------------------------------------------- who may call
revoke all on function public.hub_caller() from public, anon, authenticated, service_role;
revoke all on function public.hub_begin(text, text) from public, anon, authenticated, service_role;
revoke all on function public.hub_end() from public, anon, authenticated, service_role;
revoke all on function public.hub_line(text, text, integer, boolean) from public, anon, authenticated, service_role;
revoke all on function public.hub_block(text, text, integer, boolean) from public, anon, authenticated, service_role;
revoke all on function public.hub_teammate(text, text, public.sales) from public, anon, authenticated, service_role;
revoke all on function public.hub_person(text) from public, anon, authenticated, service_role;
revoke all on function public.hub_describe_person(bigint) from public, anon, authenticated, service_role;
revoke all on function public.hub_latest_today() from public, anon, authenticated, service_role;
revoke all on function public.hub_company(text, bigint) from public, anon, authenticated, service_role;

revoke all on function public.find_person(text, text) from public, anon, authenticated, service_role;
revoke all on function public.add_person(text, text, text, text, text, text, boolean, text) from public, anon, authenticated, service_role;
revoke all on function public.update_person(text, text, text, text, text, boolean, text, text) from public, anon, authenticated, service_role;
revoke all on function public.set_owner(text, text, text) from public, anon, authenticated, service_role;
revoke all on function public.set_status(text, text, text) from public, anon, authenticated, service_role;
revoke all on function public.log_touch(text, text, date, text, text, text, date, text, text) from public, anon, authenticated, service_role;

grant execute on function public.find_person(text, text) to authenticated;
grant execute on function public.add_person(text, text, text, text, text, text, boolean, text) to authenticated;
grant execute on function public.update_person(text, text, text, text, text, boolean, text, text) to authenticated;
grant execute on function public.set_owner(text, text, text) to authenticated;
grant execute on function public.set_status(text, text, text) to authenticated;
grant execute on function public.log_touch(text, text, date, text, text, text, date, text, text) to authenticated;

-- =============================================================== 20261122110200_hub_actions_interviews.sql
-- team hub, issue 22 (B3). Ours, not upstream's. Undo: reverts/ (same file name).
--
-- The fixed write actions for interviews and the inbox of recordings:
-- save_interview, update_overview, submit_recording, confirm_recording,
-- dismiss_recording, and the read only inbox_suggestions. Same rules as the
-- people actions: owner rights, empty search path, signed in teammates only,
-- every argument checked first, one plain sentence on refusal.

-- A recording waiting in the inbox keeps its hypothesis links too, so a
-- confirm loses nothing that was submitted.
alter table public.call_inbox add column hypotheses jsonb;

-- ------------------------------------------------------------ shared parts

-- The quote rule. Every passage of the overview between double quotation
-- marks, straight or curly, that is four words or longer must be in the
-- transcript, case and punctuation as written, once runs of spaces and line
-- breaks in both are one space. Returns the first passage that is not there,
-- or null when all are.
create function public.hub_missing_quote(overview text, transcript text) returns text
    language plpgsql immutable
    set search_path to ''
    as $$
declare
    v_body text := regexp_replace($2, '\s+', ' ', 'g');
    v_match text[];
    v_quote text;
begin
    for v_match in
        select regexp_matches($1, '["\u201C\u201D]([^"\u201C\u201D]*)["\u201C\u201D]', 'g')
    loop
        v_quote := btrim(regexp_replace(v_match[1], '\s+', ' ', 'g'));
        if coalesce(array_length(string_to_array(v_quote, ' '), 1), 0) >= 4
            and position(v_quote in v_body) = 0 then
            return v_quote;
        end if;
    end loop;
    return null;
end;
$$;

-- The quote rule as a check: refuses with one sentence. An odd number of
-- double quotation marks is refused first: with a mark left open, the marks
-- after it pair up wrongly and a quote would go unchecked.
create function public.hub_check_quotes(overview text, transcript text) returns void
    language plpgsql immutable
    set search_path to ''
    as $$
declare
    v_quote text;
begin
    if char_length(regexp_replace($1, '[^"\u201C\u201D]', '', 'g')) % 2 = 1 then
        raise exception 'the overview has an odd number of double quotation marks, so its quotes cannot be told apart: close the open one, or write a lone mark another way';
    end if;
    v_quote := public.hub_missing_quote($1, $2);
    if v_quote is not null then
        raise exception 'this quote in the overview is not word for word in the transcript: "%"', left(v_quote, 60);
    end if;
end;
$$;

-- The source and the transcript of a recording, checked. Returns the source.
create function public.hub_check_transcript(source text, transcript text, reported_chars integer) returns text
    language plpgsql immutable
    set search_path to ''
    as $$
declare
    v_source text := lower(btrim(coalesce($1, '')));
    v_chars integer;
begin
    if v_source = '' then
        raise exception 'the source is empty: use granola, paste or other';
    end if;
    if v_source not in ('granola', 'paste', 'other') then
        raise exception 'source ''%'' is not allowed: use granola, paste or other', left(v_source, 40);
    end if;
    if $2 is null or $2 = '' then
        raise exception 'the transcript is empty';
    end if;
    v_chars := char_length($2);
    if v_chars > 5000000 then
        raise exception 'the transcript is too long: % characters, the limit is 5000000', v_chars;
    end if;
    if v_chars < 1000 then
        raise exception 'the transcript is too short: % characters, an interview needs at least 1000', v_chars;
    end if;
    if $3 is not null and $3 < 0 then
        raise exception 'reported_chars cannot be negative';
    end if;
    if v_source = 'granola' and $3 is null then
        raise exception 'a granola recording needs reported_chars, the size the recorder reported';
    end if;
    if $3 is not null and v_chars < $3 then
        raise exception 'the transcript is cut short: % of % characters', v_chars, $3;
    end if;
    return v_source;
end;
$$;

-- The hypothesis links of an interview, checked. Returns the list with each
-- link as {"hypothesis", "stance", "why"}. Null gives an empty list.
create function public.hub_check_hypotheses(hypotheses jsonb) returns jsonb
    language plpgsql immutable
    set search_path to ''
    as $$
declare
    v_item jsonb;
    v_h text;
    v_stance text;
    v_why text;
    v_seen text[] := '{}';
    v_out jsonb := '[]'::jsonb;
begin
    if $1 is null or jsonb_typeof($1) = 'null' then
        return v_out;
    end if;
    if jsonb_typeof($1) <> 'array' then
        raise exception 'hypotheses must be a list, for example [{"hypothesis": "H2", "stance": "supports", "why": "one line"}]';
    end if;
    if jsonb_array_length($1) > 50 then
        raise exception 'hypotheses is too long: % links, the limit is 50', jsonb_array_length($1);
    end if;
    for v_item in select e from jsonb_array_elements($1) e loop
        if jsonb_typeof(v_item) <> 'object' then
            raise exception 'each hypothesis must look like {"hypothesis": "H2", "stance": "supports", "why": "one line"}';
        end if;
        v_h := btrim(coalesce(v_item ->> 'hypothesis', ''));
        if v_h !~ '^H[0-9]+$' then
            raise exception 'hypothesis ''%'' is not of the form H<number>, for example H2', left(v_h, 40);
        end if;
        v_stance := btrim(coalesce(v_item ->> 'stance', ''));
        if v_stance not in ('supports', 'contradicts', 'unclear') then
            raise exception 'stance ''%'' is not allowed: use supports, contradicts or unclear', left(v_stance, 40);
        end if;
        v_why := public.hub_line(v_item ->> 'why', 'why of ' || v_h, 300, false);
        if v_h = any(v_seen) then
            raise exception '% is listed twice', v_h;
        end if;
        v_seen := v_seen || v_h;
        v_out := v_out || jsonb_build_array(jsonb_build_object('hypothesis', v_h, 'stance', v_stance, 'why', v_why));
    end loop;
    return v_out;
end;
$$;

-- A day given to an action: required, and not after today anywhere on earth.
create function public.hub_day(value date, label text) returns date
    language plpgsql stable
    set search_path to ''
    as $$
begin
    if $1 is null then
        raise exception 'the % is empty', $2;
    end if;
    if $1 > public.hub_latest_today() then
        raise exception 'the % % is in the future', $2, $1;
    end if;
    return $1;
end;
$$;

-- Where a recording already is, in words, or null when it is nowhere. Takes
-- a lock on the recording first, so the same one submitted twice at once is
-- saved once.
create function public.hub_recording_on_file(granola_id text, except_inbox bigint) returns text
    language plpgsql
    set search_path to ''
    as $$
declare
    v_text text;
begin
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('hub.recording.' || $1, 0));
    select pg_catalog.format('this recording is already saved as interview %s for %s', i.id, c.person_code)
    into v_text
    from public.interviews i
        join public.contacts c on c.id = i.contact_id
    where i.granola_id = $1;
    if v_text is not null then
        return v_text;
    end if;
    select pg_catalog.format('this recording is already in the inbox as item %s (%s)', b.id, b.state)
    into v_text
    from public.call_inbox b
    where b.granola_id = $1 and b.id is distinct from $2;
    return v_text;
end;
$$;

-- Writes an interview that has passed every check: the interview, its
-- transcript and its links, and the person becomes interviewed.
create function public.hub_write_interview(
        contact_id bigint, day date, interviewer_id bigint, created_by bigint, source text,
        granola_id text, title text, overview text, transcript text, reported_chars integer,
        hypotheses jsonb)
    returns bigint
    language plpgsql
    set search_path to ''
    as $$
declare
    v_id bigint;
begin
    insert into public.interviews (contact_id, date, interviewer_id, source, granola_id,
                                   consent_to_record, title, overview, created_by)
    values ($1, $2, $3, $5, $6, true, $7, $8, $4)
    returning id into v_id;
    insert into public.interview_transcripts (interview_id, body, reported_chars)
    values (v_id, $9, $10);
    insert into public.interview_hypotheses (interview_id, hypothesis, stance, why)
    select v_id, e ->> 'hypothesis', e ->> 'stance', e ->> 'why'
    from jsonb_array_elements($11) e;
    update public.contacts c set status = 'interviewed' where c.id = $1 and c.status <> 'interviewed';
    return v_id;
end;
$$;

-- The email addresses of a person: every address in email_jsonb, and the
-- contact key when it is an address. Lowercase.
create function public.hub_person_emails(contact_key text, email_jsonb jsonb) returns text[]
    language sql immutable
    set search_path to ''
    as $$
    select coalesce(array_agg(distinct a), '{}')
    from (
        select lower(btrim(e ->> 'email')) as a
        from jsonb_array_elements(case when jsonb_typeof($2) = 'array' then $2 else '[]'::jsonb end) e
        union all
        select lower(btrim($1)) where position('@' in coalesce($1, '')) > 0
    ) t
    where a is not null and a <> ''
    $$;

-- The attendee list as given, tidied: trimmed, lowercase, no empty entry, no
-- repeat, in the order given.
create function public.hub_addresses(attendee_emails text[]) returns text[]
    language plpgsql immutable
    set search_path to ''
    as $$
declare
    v_out text[];
begin
    if coalesce(cardinality($1), 0) > 200 then
        raise exception 'the attendee list is too long: % addresses, the limit is 200', cardinality($1);
    end if;
    select coalesce(array_agg(t.a order by t.o), '{}') into v_out
    from (
        select lower(btrim(x, E' \t\n\r')) as a, min(o) as o
        from unnest(coalesce($1, '{}'::text[])) with ordinality as u(x, o)
        where btrim(coalesce(x, ''), E' \t\n\r') <> ''
        group by 1
    ) t;
    if exists (select 1 from unnest(v_out) a where char_length(a) > 300 or a ~ '\s') then
        raise exception 'an attendee address is longer than 300 characters or has a space inside it';
    end if;
    return v_out;
end;
$$;

-- The attendees who are not teammates: sales.email and secondary_emails are taken out.
create function public.hub_outside_addresses(attendee_emails text[]) returns text[]
    language sql stable
    set search_path to ''
    as $$
    select coalesce(array_agg(u.a order by u.o), '{}')
    from unnest($1) with ordinality as u(a, o)
    where not exists (
        select 1 from public.sales s
        where lower(s.email::text) = u.a
            or exists (select 1 from jsonb_array_elements_text(s.secondary_emails) se
                       where lower(btrim(se)) = u.a))
    $$;

-- Up to three people a recording may belong to, best first: people with an
-- attendee's address ("email"); then people with an address on an attendee's
-- domain, public mail domains left out ("domain"); then people all of whose
-- name key words are in the meeting title ("name"). Within a group by person
-- code. A person is listed once, in the first group they match.
create function public.hub_suggestions(attendee_emails text[], title text)
    returns table (contact_id bigint, matched text, ord integer)
    language sql stable
    set search_path to ''
    as $$
    with outside as (
        select public.hub_outside_addresses(public.hub_addresses($1)) as addrs
    ), domains as (
        select distinct split_part(a, '@', 2) as d
        from outside, unnest(outside.addrs) a
        where split_part(a, '@', 2) <> ''
            and split_part(a, '@', 2) not in ('gmail.com', 'yahoo.com', 'outlook.com', 'hotmail.com',
                'icloud.com', 'me.com', 'aol.com', 'proton.me', 'protonmail.com')
    ), words as (
        select array(
            select w
            from unnest(string_to_array(public.hub_name_fold($2), ' ')
                        || string_to_array(lower(regexp_replace(coalesce($2, ''), '\s+', ' ', 'g')), ' ')) w
            where w <> '') as ws
    ), people as (
        select c.id, c.person_code, c.name_key,
               public.hub_person_emails(c.contact_key, c.email_jsonb) as emails
        from public.contacts c
    ), ranked as (
        select p.id, p.person_code,
               case
                   when p.emails && (select addrs from outside) then 1
                   when exists (select 1 from unnest(p.emails) e join domains d on split_part(e, '@', 2) = d.d) then 2
                   when string_to_array(p.name_key, ' ') <@ (select ws from words) then 3
               end as grp
        from people p
    )
    select r.id,
           case r.grp when 1 then 'email' when 2 then 'domain' else 'name' end,
           (row_number() over (order by r.grp, split_part(r.person_code, '-', 1),
                                        substring(r.person_code from '[0-9]+$')::integer))::integer
    from ranked r
    where r.grp is not null
    order by 3
    limit 3
    $$;

-- ------------------------------------------------------------- save_interview
create function public.save_interview(
        person_code text,
        date date,
        interviewer text default null,
        source text default null,
        granola_id text default null,
        consent_to_record boolean default null,
        title text default null,
        overview text default null,
        transcript text default null,
        hypotheses jsonb default null,
        reported_chars integer default null,
        via text default 'ui')
    returns jsonb
    language plpgsql security definer
    set search_path to ''
    as $$
declare
    v_me public.sales := public.hub_begin('save_interview', $12);
    v_p public.contacts;
    v_who public.sales;
    v_day date;
    v_gid text;
    v_title text;
    v_overview text;
    v_source text;
    v_hyp jsonb;
    v_on_file text;
    v_id bigint;
begin
    if $6 is not true then
        raise exception 'consent to record is not confirmed: an interview is saved only when the person agreed to be recorded';
    end if;
    v_gid := public.hub_line($5, 'granola_id', 300, false);
    -- locks are always taken in one order: the recording, then the person
    if v_gid is not null then
        perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('hub.recording.' || v_gid, 0));
    end if;
    v_p := public.hub_person($1);
    v_day := public.hub_day($2, 'date');
    v_who := public.hub_teammate($3, 'interviewer', v_me);
    v_title := public.hub_line($7, 'title', 300, true);
    v_overview := public.hub_block($8, 'overview', 100000, true);
    v_source := public.hub_check_transcript($4, $9, $11);
    v_hyp := public.hub_check_hypotheses($10);
    perform public.hub_check_quotes(v_overview, $9);
    if v_gid is not null then
        v_on_file := public.hub_recording_on_file(v_gid, null);
        if v_on_file is not null then
            raise exception '%', v_on_file;
        end if;
    end if;

    v_id := public.hub_write_interview(v_p.id, v_day, v_who.id, v_me.id, v_source, v_gid,
                                       v_title, v_overview, $9, $11, v_hyp);
    perform public.hub_end();
    return jsonb_build_object(
        'interview_id', v_id,
        'person_code', v_p.person_code,
        'interviewer', v_who.handle,
        'status', 'interviewed',
        'chars', char_length($9));
end;
$$;

-- ------------------------------------------------------------ update_overview
-- hypotheses null leaves the links as they are; a list, even an empty one, replaces them.
create function public.update_overview(
        interview_id bigint,
        overview text,
        hypotheses jsonb default null,
        via text default 'ui')
    returns jsonb
    language plpgsql security definer
    set search_path to ''
    as $$
declare
    v_me public.sales := public.hub_begin('update_overview', $4);
    v_id bigint;
    v_body text;
    v_overview text;
    v_hyp jsonb;
begin
    if $1 is null then
        raise exception 'the interview id is empty';
    end if;
    select i.id into v_id from public.interviews i where i.id = $1 for update;
    if v_id is null then
        raise exception 'no interview has the id %', $1;
    end if;
    v_overview := public.hub_block($2, 'overview', 100000, true);
    if $3 is not null then
        v_hyp := public.hub_check_hypotheses($3);
    end if;
    select t.body into v_body from public.interview_transcripts t where t.interview_id = v_id;
    perform public.hub_check_quotes(v_overview, coalesce(v_body, ''));

    update public.interviews i set overview = v_overview where i.id = v_id;
    if v_hyp is not null then
        delete from public.interview_hypotheses h where h.interview_id = v_id;
        insert into public.interview_hypotheses (interview_id, hypothesis, stance, why)
        select v_id, e ->> 'hypothesis', e ->> 'stance', e ->> 'why'
        from jsonb_array_elements(v_hyp) e;
    end if;

    perform public.hub_end();
    return jsonb_build_object(
        'interview_id', v_id,
        'hypotheses', (select count(*) from public.interview_hypotheses h where h.interview_id = v_id));
end;
$$;

-- ----------------------------------------------------------- submit_recording
create function public.submit_recording(
        granola_id text,
        source text,
        title text,
        recorded_on date,
        attendee_emails text[] default null,
        overview text default null,
        transcript text default null,
        consent_to_record boolean default null,
        hypotheses jsonb default null,
        reported_chars integer default null,
        via text default 'ui')
    returns jsonb
    language plpgsql security definer
    set search_path to ''
    as $$
declare
    v_me public.sales := public.hub_begin('submit_recording', $11);
    v_gid text := public.hub_line($1, 'granola_id', 300, false);
    v_title text := public.hub_line($3, 'title', 300, true);
    v_day date := public.hub_day($4, 'recorded_on date');
    v_attendees text[] := public.hub_addresses($5);
    v_overview text := public.hub_block($6, 'overview', 100000, true);
    v_source text := public.hub_check_transcript($2, $7, $10);
    v_hyp jsonb := public.hub_check_hypotheses($9);
    v_on_file text;
    v_outside text[];
    v_people bigint[];
    v_reason text;
    v_p public.contacts;
    v_id bigint;
    v_suggested bigint[];
begin
    perform public.hub_check_quotes(v_overview, $7);
    if v_gid is not null then
        v_on_file := public.hub_recording_on_file(v_gid, null);
        if v_on_file is not null then
            raise exception '%', v_on_file;
        end if;
    end if;

    v_outside := public.hub_outside_addresses(v_attendees);
    if cardinality(v_outside) = 0 then
        v_reason := 'no attendee outside the team';
    else
        select coalesce(array_agg(c.id order by c.id), '{}') into v_people
        from public.contacts c
        where public.hub_person_emails(c.contact_key, c.email_jsonb) && v_outside;
        if cardinality(v_people) = 0 then
            v_reason := 'no person matches an attendee';
        elsif cardinality(v_people) > 1 then
            v_reason := pg_catalog.format('%s people match an attendee', cardinality(v_people));
        elsif $8 is not true then
            v_reason := 'consent not confirmed';
        end if;
    end if;

    if v_reason is null then
        -- exactly one person, and consent: this is an interview
        select c.* into v_p from public.contacts c where c.id = v_people[1] for update;
        v_id := public.hub_write_interview(v_p.id, v_day, v_me.id, v_me.id, v_source, v_gid,
                                           v_title, v_overview, $7, $10, v_hyp);
        perform public.hub_end();
        return jsonb_build_object('result', 'saved', 'interview_id', v_id, 'person_code', v_p.person_code);
    end if;

    select coalesce(array_agg(g.contact_id order by g.ord), '{}') into v_suggested
    from public.hub_suggestions(v_attendees, v_title) g;
    insert into public.call_inbox (granola_id, source, title, recorded_on, attendee_emails, overview,
                                   transcript, reported_chars, consent_to_record, submitted_by,
                                   suggested_contact_ids, state, reason, hypotheses)
    values (v_gid, v_source, v_title, v_day, v_attendees, v_overview,
            $7, $10, $8, v_me.id,
            v_suggested, 'waiting', v_reason, v_hyp)
    returning id into v_id;
    perform public.hub_end();
    return jsonb_build_object('result', 'inbox', 'inbox_id', v_id, 'reason', v_reason);
end;
$$;

-- ---------------------------------------------------------- inbox_suggestions
-- Read only. The suggestions for one inbox item, computed now, so a person
-- added after the recording arrived is suggested too.
create function public.inbox_suggestions(inbox_id bigint)
    returns table (person_code text, name text, role text, organization text, owner text, status text,
                   matched text)
    language plpgsql stable security definer
    set search_path to ''
    as $$
#variable_conflict use_column
declare
    v_attendees text[];
    v_title text;
begin
    perform public.hub_caller();
    select b.attendee_emails, b.title into v_attendees, v_title
    from public.call_inbox b where b.id = $1;
    if not found then
        raise exception 'no inbox item has the id %', coalesce($1::text, '(none)');
    end if;
    return query
    select c.person_code,
           btrim(coalesce(c.first_name, '') || ' ' || coalesce(c.last_name, '')),
           c.title,
           co.name,
           s.handle,
           c.status,
           g.matched
    from public.hub_suggestions(v_attendees, v_title) g
        join public.contacts c on c.id = g.contact_id
        left join public.companies co on co.id = c.company_id
        left join public.sales s on s.id = c.sales_id
    order by g.ord;
end;
$$;

-- ---------------------------------------------------------- confirm_recording
create function public.confirm_recording(
        inbox_id bigint,
        person_code text,
        consent_to_record boolean default null,
        via text default 'ui')
    returns jsonb
    language plpgsql security definer
    set search_path to ''
    as $$
declare
    v_me public.sales := public.hub_begin('confirm_recording', $4);
    v_item public.call_inbox;
    v_p public.contacts;
    v_title text;
    v_overview text;
    v_source text;
    v_hyp jsonb;
    v_on_file text;
    v_id bigint;
begin
    if $1 is null then
        raise exception 'the inbox id is empty';
    end if;
    -- the item is locked, so two confirms at once happen one after the other
    select b.* into v_item from public.call_inbox b where b.id = $1 for update;
    if not found then
        raise exception 'no inbox item has the id %', $1;
    end if;
    if v_item.state = 'confirmed' then
        raise exception 'already confirmed by % as interview %',
            coalesce((select s.handle from public.sales s where s.id = v_item.resolved_by), '?'),
            coalesce(v_item.interview_id::text, '?');
    end if;
    if $3 is not true then
        raise exception 'consent to record is not confirmed: an interview is saved only when the person agreed to be recorded';
    end if;
    if v_item.granola_id is not null then
        perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('hub.recording.' || v_item.granola_id, 0));
    end if;
    v_p := public.hub_person($2);

    -- the same checks as save_interview
    v_title := public.hub_line(v_item.title, 'title', 300, true);
    v_overview := public.hub_block(v_item.overview, 'overview', 100000, true);
    v_source := public.hub_check_transcript(v_item.source, v_item.transcript, v_item.reported_chars);
    v_hyp := public.hub_check_hypotheses(v_item.hypotheses);
    perform public.hub_check_quotes(v_overview, v_item.transcript);
    if v_item.granola_id is not null then
        v_on_file := public.hub_recording_on_file(v_item.granola_id, v_item.id);
        if v_on_file is not null then
            raise exception '%', v_on_file;
        end if;
    end if;

    v_id := public.hub_write_interview(v_p.id, v_item.recorded_on, v_me.id, v_me.id, v_source,
                                       v_item.granola_id, v_title, v_overview, v_item.transcript,
                                       v_item.reported_chars, v_hyp);
    update public.call_inbox b
    set state = 'confirmed',
        consent_to_record = true,
        interview_id = v_id,
        resolved_by = v_me.id,
        resolved_at = now()
    where b.id = v_item.id;

    perform public.hub_end();
    return jsonb_build_object('inbox_id', v_item.id, 'interview_id', v_id, 'person_code', v_p.person_code);
end;
$$;

-- ---------------------------------------------------------- dismiss_recording
create function public.dismiss_recording(inbox_id bigint, reason text, via text default 'ui')
    returns jsonb
    language plpgsql security definer
    set search_path to ''
    as $$
declare
    v_me public.sales := public.hub_begin('dismiss_recording', $3);
    v_item public.call_inbox;
    v_reason text;
begin
    if $1 is null then
        raise exception 'the inbox id is empty';
    end if;
    select b.* into v_item from public.call_inbox b where b.id = $1 for update;
    if not found then
        raise exception 'no inbox item has the id %', $1;
    end if;
    v_reason := public.hub_block($2, 'reason', 10000, true);
    if v_item.state <> 'waiting' then
        raise exception 'only a waiting recording can be dismissed: this one was % by %',
            v_item.state,
            coalesce((select s.handle from public.sales s where s.id = v_item.resolved_by), '?');
    end if;

    update public.call_inbox b
    set state = 'dismissed',
        reason = v_reason,
        resolved_by = v_me.id,
        resolved_at = now()
    where b.id = v_item.id;

    perform public.hub_end();
    return jsonb_build_object('inbox_id', v_item.id, 'state', 'dismissed');
end;
$$;

-- ---------------------------------------------------------------- who may call
revoke all on function public.hub_missing_quote(text, text) from public, anon, authenticated, service_role;
revoke all on function public.hub_check_quotes(text, text) from public, anon, authenticated, service_role;
revoke all on function public.hub_check_transcript(text, text, integer) from public, anon, authenticated, service_role;
revoke all on function public.hub_check_hypotheses(jsonb) from public, anon, authenticated, service_role;
revoke all on function public.hub_day(date, text) from public, anon, authenticated, service_role;
revoke all on function public.hub_recording_on_file(text, bigint) from public, anon, authenticated, service_role;
revoke all on function public.hub_write_interview(bigint, date, bigint, bigint, text, text, text, text, text, integer, jsonb) from public, anon, authenticated, service_role;
revoke all on function public.hub_person_emails(text, jsonb) from public, anon, authenticated, service_role;
revoke all on function public.hub_addresses(text[]) from public, anon, authenticated, service_role;
revoke all on function public.hub_outside_addresses(text[]) from public, anon, authenticated, service_role;
revoke all on function public.hub_suggestions(text[], text) from public, anon, authenticated, service_role;

revoke all on function public.save_interview(text, date, text, text, text, boolean, text, text, text, jsonb, integer, text) from public, anon, authenticated, service_role;
revoke all on function public.update_overview(bigint, text, jsonb, text) from public, anon, authenticated, service_role;
revoke all on function public.submit_recording(text, text, text, date, text[], text, text, boolean, jsonb, integer, text) from public, anon, authenticated, service_role;
revoke all on function public.inbox_suggestions(bigint) from public, anon, authenticated, service_role;
revoke all on function public.confirm_recording(bigint, text, boolean, text) from public, anon, authenticated, service_role;
revoke all on function public.dismiss_recording(bigint, text, text) from public, anon, authenticated, service_role;

grant execute on function public.save_interview(text, date, text, text, text, boolean, text, text, text, jsonb, integer, text) to authenticated;
grant execute on function public.update_overview(bigint, text, jsonb, text) to authenticated;
grant execute on function public.submit_recording(text, text, text, date, text[], text, text, boolean, jsonb, integer, text) to authenticated;
grant execute on function public.inbox_suggestions(bigint) to authenticated;
grant execute on function public.confirm_recording(bigint, text, boolean, text) to authenticated;
grant execute on function public.dismiss_recording(bigint, text, text) to authenticated;

-- =============================================================== 20261122110300_hub_name_key_as_written.sql
-- team hub, issue 22 (B3). Ours, not upstream's. Undo: reverts/ (same file name).
--
-- hub_name_key() brought into step with stage one (scripts/team.py and
-- scripts/contact.py), found by holding both to scripts/fixtures/name_keys.json.
-- A name that folds to nothing is kept as written only when something other
-- than punctuation, symbols and spaces is in it: before this, "..." written
-- with one ellipsis character, or a lone dash, counted as a name. Spaces of
-- every kind, the ideographic space included, are one space. The ranges are
-- written out so the answer does not depend on the database's locale.

create or replace function public.hub_name_key(name text) returns text
    language plpgsql immutable
    set search_path to ''
    as $$
declare
    v_fold text := public.hub_name_fold(name);
    v_plain text;
    v_rest text;
begin
    if v_fold <> '' then
        return v_fold;
    end if;
    v_plain := btrim(regexp_replace(coalesce(name, ''),
        '[\s\u00A0\u1680\u2000-\u200A\u2028\u2029\u202F\u205F\u3000]+', ' ', 'g'));
    -- what is left once ASCII, punctuation, symbols and marks are taken out
    v_rest := regexp_replace(v_plain,
        '[\u0001-\u00BF\u00D7\u00F7\u0300-\u036F\u2000-\u2BFF\u2E00-\u2E7F\u3000-\u303F\uFE00-\uFE6F\uFF00-\uFF0F\uFF1A-\uFF20\uFF3B-\uFF40\uFF5B-\uFF65]',
        '', 'g');
    if v_rest <> '' then
        return lower(v_plain);
    end if;
    return '';
end;
$$;

-- =============================================================== 20261122120000_hub_export_read_only.sql
-- team hub, issue 35 (B8b). Ours, not upstream's. Undo: reverts/ (same file name).
--
-- The role hub_export is the one the markdown export signs in with. It was
-- given select on nine things and nothing else, and could still write: the
-- extension pg_net grants its two tables, and the right to enter its schema,
-- to every role. A revoke of those grants does nothing when run as the role
-- migrations run as, because the tables are not ours. So the extension goes.

-- 1. The only thing that used pg_net: upstream's cleanup of a note's
-- attachment files, which called an edge function through net.http_post when
-- a note was deleted or its attachments changed. A touch is never deleted
-- (issue 21), and the attachments column is not used by the hub.
drop trigger on_contact_notes_deleted_delete_note_attachments on public.contact_notes;
drop trigger on_contact_notes_attachments_updated_delete_note_attachments on public.contact_notes;
drop trigger on_deal_notes_deleted_delete_note_attachments on public.deal_notes;
drop trigger on_deal_notes_attachments_updated_delete_note_attachments on public.deal_notes;
drop function public.cleanup_note_attachments();
drop function public.get_note_attachments_function_url();

-- 2. The extension, with its schema net, its two tables and its functions.
drop extension pg_net;

-- 3. Upstream's functions in public that every role may call, because
-- Postgres gives execute to everyone on a new function. The roles of the API
-- hold their own grants (anon, authenticated, service_role), so they lose
-- nothing; hub_export and any other role lose the call.
revoke execute on function public.handle_contact_note_created_or_updated() from public;
revoke execute on function public.handle_new_user() from public;
revoke execute on function public.handle_tag_deleted() from public;
revoke execute on function public.handle_update_user() from public;
revoke execute on function public.is_admin() from public;
revoke execute on function public.lowercase_email_jsonb() from public;
revoke execute on function public.merge_contacts(bigint, bigint) from public;
revoke execute on function public.search_attachment_titles(jsonb[]) from public;
revoke execute on function public.search_document(text[]) from public;
revoke execute on function public.search_query(text) from public;
revoke execute on function public.search_unaccent(text) from public;
revoke execute on function public.set_sales_id_default() from public;

-- 4. Ask again: a drop or a revoke that changed nothing is silent, which is
-- how this gap came to be. Stop the migration if anything named here is left.
do $$
declare
    left_over text;
begin
    if exists (select 1 from pg_catalog.pg_extension where extname = 'pg_net')
        or pg_catalog.to_regnamespace('net') is not null then
        raise exception 'pg_net or its schema net is still here after the drop';
    end if;
    select string_agg(f.proname || '(' || pg_catalog.oidvectortypes(f.proargtypes) || ')', '; ') into left_over
    from pg_catalog.pg_proc f
    where f.pronamespace = 'public'::regnamespace
        and f.proname || '(' || pg_catalog.oidvectortypes(f.proargtypes) || ')' in ('handle_contact_note_created_or_updated()',
            'handle_new_user()',
            'handle_tag_deleted()',
            'handle_update_user()',
            'is_admin()',
            'lowercase_email_jsonb()',
            'merge_contacts(bigint, bigint)',
            'search_attachment_titles(jsonb[])',
            'search_document(text[])',
            'search_query(text)',
            'search_unaccent(text)',
            'set_sales_id_default()')
        and pg_catalog.has_function_privilege('hub_export', f.oid, 'EXECUTE');
    if left_over is not null then
        raise exception 'hub_export may still call: %', left_over;
    end if;
end $$;

-- =============================================================== 20261122130000_hub_anon_allow_list.sql
-- team hub, issue 25 (B6): the anon role keeps one right in public.
--
-- anon is what a stranger is when they hold the public key, and the public
-- key ships in the app's files. Before anyone is signed in the app asks one
-- thing: whether a first user exists (the view init_state, which answers 0
-- or 1). Upstream grants anon everything on its tables, views, sequences
-- and functions and relies on there being no policy for anon. Issue 21 took
-- the grants on the tables of docs/SCHEMA.md away; this takes the rest.
--
-- The list is written out, not found by a loop, so the undo file can give
-- back exactly what was taken. It is what the catalog answered for anon in
-- run 45130689491 (db workflow, issue 25): 9 tables and views, 9 sequences
-- and 12 functions, and the default grants for what is made later. Whatever is granted to anon later is caught by
-- app/supabase/tests/hub_anon.sql.

revoke all on table public.activity_log from anon;
revoke all on table public.companies_summary from anon;
revoke all on table public.configuration from anon;
revoke all on table public.deal_notes from anon;
revoke all on table public.deals from anon;
revoke all on table public.favicons_excluded_domains from anon;
revoke all on table public.init_state from anon;
revoke all on table public.tags from anon;
revoke all on table public.tasks from anon;

-- the one thing the sign-in page reads before sign-in
grant select on table public.init_state to anon;

revoke all on sequence public.companies_id_seq from anon;
revoke all on sequence public."contactNotes_id_seq" from anon;
revoke all on sequence public.contacts_id_seq from anon;
revoke all on sequence public."dealNotes_id_seq" from anon;
revoke all on sequence public.deals_id_seq from anon;
revoke all on sequence public.favicons_excluded_domains_id_seq from anon;
revoke all on sequence public.sales_id_seq from anon;
revoke all on sequence public.tags_id_seq from anon;
revoke all on sequence public.tasks_id_seq from anon;

revoke execute on function public.handle_contact_note_created_or_updated() from anon;
revoke execute on function public.handle_new_user() from anon;
revoke execute on function public.handle_tag_deleted() from anon;
revoke execute on function public.handle_update_user() from anon;
revoke execute on function public.is_admin() from anon;
revoke execute on function public.lowercase_email_jsonb() from anon;
revoke execute on function public.merge_contacts(bigint, bigint) from anon;
revoke execute on function public.search_attachment_titles(jsonb[]) from anon;
revoke execute on function public.search_document(text[]) from anon;
revoke execute on function public.search_query(text) from anon;
revoke execute on function public.search_unaccent(text) from anon;
revoke execute on function public.set_sales_id_default() from anon;

-- What a migration makes in public from now on. Supabase's defaults for the
-- role migrations run as hand anon every right on each new table, sequence
-- and function (seen in run 45131340113), which is why every migration of
-- ours so far had to take them away by name. From here a new table or
-- sequence starts with nothing for anon. A new function is still callable by
-- every role until its migration revokes that, as Postgres itself has it.
alter default privileges for role postgres in schema public revoke all on tables from anon;
alter default privileges for role postgres in schema public revoke all on sequences from anon;
alter default privileges for role postgres in schema public revoke all on functions from anon;

-- A revoke that changes nothing is silent (docs/FINDINGS.md, issue 35). Ask
-- the catalog whether it took, and stop if anon still holds anything in
-- public beyond select on init_state.
do $$
declare
    v_left text;
begin
    select string_agg(x.what, '; ' order by x.what) into v_left
    from (
        select c.relname || ': ' || p.priv as what
        from pg_catalog.pg_class c
            cross join unnest(array['SELECT', 'INSERT', 'UPDATE', 'DELETE', 'TRUNCATE', 'REFERENCES', 'TRIGGER']) p(priv)
        where c.relnamespace = 'public'::regnamespace
            and c.relkind in ('r', 'v', 'm', 'f', 'p')
            and pg_catalog.has_table_privilege('anon', c.oid, p.priv)
            and not (c.relname = 'init_state' and p.priv = 'SELECT')
        union all
        select c.relname || ': sequence' as what
        from pg_catalog.pg_class c
        where c.relnamespace = 'public'::regnamespace
            and c.relkind = 'S'
            and (pg_catalog.has_sequence_privilege('anon', c.oid, 'USAGE')
                 or pg_catalog.has_sequence_privilege('anon', c.oid, 'SELECT')
                 or pg_catalog.has_sequence_privilege('anon', c.oid, 'UPDATE'))
        union all
        select f.proname || '(): EXECUTE' as what
        from pg_catalog.pg_proc f
        where f.pronamespace = 'public'::regnamespace
            and pg_catalog.has_function_privilege('anon', f.oid, 'EXECUTE')
    ) x;
    if v_left is not null then
        raise exception 'anon still holds in public: %', v_left;
    end if;
    if not pg_catalog.has_table_privilege('anon', 'public.init_state', 'SELECT') then
        raise exception 'anon lost select on init_state: the sign-in page needs it';
    end if;
end $$;

-- =============================================================== 20261122130100_hub_link_columns.sql
-- team hub, issue 25 (B6), from the router's note: every link column of
-- contacts and companies holds nothing, or an address that starts with
-- https:// or http://.
--
-- Upstream's screens use these values as the href of a link with no check
-- (contacts.linkedin_url in ContactPersonalInfo.tsx, companies.linkedin_url
-- and website in CompanyAside.tsx), so a stored `javascript:` or `data:`
-- value would run when clicked. The screens are not edited here.
--
-- Covered: contacts.linkedin_url, companies.linkedin_url, companies.website,
-- and each entry of companies.context_links (a json list of addresses).
-- Not covered, on purpose: contacts.avatar, companies.logo and sales.avatar
-- (json with a picture's address, drawn as an image, never a link);
-- contacts.contact_key (drawn as text, docs/SCHEMA.md); the email and phone
-- columns (drawn as mailto: and tel: links built by the screen).
--
-- A bare address is given its https:// first, by a trigger. Why: upstream's
-- company form accepts "example.com" for a website and a context link, and
-- the hub's add_person and update_person file "linkedin.com/in/x" under
-- linkedin_url; with the check alone those ordinary saves would be refused.
-- Only a value that is a host name and nothing before it is prefixed, so a
-- value with a scheme of its own (javascript:, data:, mailto:) is left as it
-- is, and the check refuses it.
--
-- No helper function is called from a check or from inside the triggers:
-- Postgres asks for the call right on such a function as the user writing,
-- and functions of ours are closed to every API role. The rule is written
-- inline instead, and the two trigger functions call nothing of ours.
-- context_links is json, which a check cannot look inside without a
-- function, so its entries are held by the trigger, which refuses.

create function public.hub_contact_link_scheme() returns trigger
    language plpgsql
    set search_path to ''
    as $$
declare
    -- a host name, with a port, a path, a query or a fragment after it
    c_bare constant text := '^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+(:[0-9]{1,5})?([/?#][^[:space:]]*)?$';
begin
    if btrim(coalesce(new.linkedin_url, '')) ~* c_bare then
        new.linkedin_url := 'https://' || btrim(new.linkedin_url);
    end if;
    return new;
end;
$$;

create function public.hub_company_link_scheme() returns trigger
    language plpgsql
    set search_path to ''
    as $$
declare
    c_bare constant text := '^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+(:[0-9]{1,5})?([/?#][^[:space:]]*)?$';
    c_web constant text := '^https?://[^[:space:]]+$';
    v_item json;
    v_text text;
    v_out json[] := '{}';
begin
    if btrim(coalesce(new.linkedin_url, '')) ~* c_bare then
        new.linkedin_url := 'https://' || btrim(new.linkedin_url);
    end if;
    if btrim(coalesce(new.website::text, '')) ~* c_bare then
        new.website := 'https://' || btrim(new.website::text);
    end if;
    if new.context_links is not null and json_typeof(new.context_links) <> 'null' then
        if json_typeof(new.context_links) <> 'array' then
            raise exception 'context_links must be a list of web addresses'
                using errcode = 'check_violation';
        end if;
        for v_item in select * from json_array_elements(new.context_links) loop
            if json_typeof(v_item) = 'string' then
                v_text := v_item #>> '{}';
                if btrim(v_text) ~* c_bare then
                    v_text := 'https://' || btrim(v_text);
                end if;
                if btrim(v_text) <> '' and v_text !~* c_web then
                    raise exception 'a context link must start with https:// or http://: %', left(v_text, 60)
                        using errcode = 'check_violation';
                end if;
                v_out := v_out || to_json(v_text);
            elsif json_typeof(v_item) = 'null' then
                v_out := v_out || v_item;
            else
                raise exception 'context_links must be a list of web addresses'
                    using errcode = 'check_violation';
            end if;
        end loop;
        new.context_links := array_to_json(v_out);
    end if;
    return new;
end;
$$;

revoke all on function public.hub_contact_link_scheme() from public, anon, authenticated, service_role;
revoke all on function public.hub_company_link_scheme() from public, anon, authenticated, service_role;

-- Named to run after every other row trigger before the write on these
-- tables (they run in name order: zz_hub_1_... comes first), so a value
-- another trigger filed is prefixed too.
create trigger zz_hub_link_scheme before insert or update on public.contacts
    for each row execute function public.hub_contact_link_scheme();
create trigger zz_hub_link_scheme before insert or update on public.companies
    for each row execute function public.hub_company_link_scheme();

-- Empty, or http:// or https:// and something after it. Case does not matter.
alter table public.contacts
    add constraint contacts_linkedin_url_is_web
        check (linkedin_url is null or btrim(linkedin_url) = '' or linkedin_url ~* '^https?://[^[:space:]]+$');
alter table public.companies
    add constraint companies_linkedin_url_is_web
        check (linkedin_url is null or btrim(linkedin_url) = '' or linkedin_url ~* '^https?://[^[:space:]]+$'),
    add constraint companies_website_is_web
        check (website is null or btrim(website::text) = '' or website::text ~* '^https?://[^[:space:]]+$');

-- =============================================================== 20261123100000_hub_signup_allow_list.sql
-- team hub, issue 40 item 11: nobody gets an account unless their email is
-- on the hub's list, the very first user included.
--
-- Upstream's sign-up trigger makes the first sign-up of an empty database its
-- administrator, and lets nobody else in without an invitation row. With
-- sign-ups switched on in Supabase, whoever reached the sign-up endpoint
-- first would have become the administrator. Now the trigger asks the list
-- first, always: before the invitation check, before the first user rule,
-- and for users Supabase marks as SSO users too.
--
-- The list lives in its own schema, hub_private, which the API does not
-- serve and no API role may use. It is filled only through
-- allow_signup_email(), which only a direct session of the database's owner
-- (the dashboard's SQL editor) may run, so no address is ever written in this
-- repo. An entry is one exact email, kept in lower case. For throwaway test
-- stacks only, an entry may also be a whole domain that ends in .test, a
-- name reserved for tests that no real mailbox can have
-- (app/supabase/test_stack_allow_list.sql, never applied to the cloud).

create schema hub_private;
revoke all on schema hub_private from public;

create table hub_private.signup_allow_list (
    entry text primary key,
    added_at timestamptz not null default now(),
    added_by text not null default session_user,
    constraint signup_allow_list_entry_shape check (
        entry = lower(btrim(entry))
        and (
            entry ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'
            or entry ~ '^@([a-z0-9-]+\.)*[a-z0-9-]+\.test$'
        )
    )
);
revoke all on table hub_private.signup_allow_list from public, anon, authenticated, service_role;

-- true when this email may have an account
create function hub_private.signup_allowed(user_email text) returns boolean
    language sql stable
    set search_path to ''
    as $$
        select coalesce($1, '') <> '' and exists (
            select 1 from hub_private.signup_allow_list a
            where a.entry = lower(btrim($1))
               or (a.entry like '@%' and lower(btrim($1)) like '%' || a.entry)
        )
    $$;
revoke execute on function hub_private.signup_allowed(text) from public, anon, authenticated, service_role;

-- Only a direct session of the role that owns public.sales, or a superuser,
-- with nobody signed in through the API.
create function hub_private.caller_is_owner() returns boolean
    language plpgsql stable
    set search_path to ''
    as $$
declare
    v_owner text;
begin
    if auth.uid() is not null then
        return false;
    end if;
    select t.tableowner into v_owner
    from pg_catalog.pg_tables t
    where t.schemaname = 'public' and t.tablename = 'sales';
    return pg_catalog.pg_has_role(session_user, v_owner, 'usage')
        or coalesce((select r.rolsuper from pg_catalog.pg_roles r where r.rolname = session_user), false);
end $$;
revoke execute on function hub_private.caller_is_owner() from public, anon, authenticated, service_role;

create function public.allow_signup_email(user_email text) returns text
    language plpgsql security definer
    set search_path to ''
    as $$
declare
    v_entry text := lower(btrim($1));
begin
    if not hub_private.caller_is_owner() then
        raise exception 'only the database owner can change the sign-up list';
    end if;
    if v_entry is null or v_entry !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
        raise exception 'that is not one email address';
    end if;
    insert into hub_private.signup_allow_list (entry) values (v_entry)
        on conflict (entry) do nothing;
    return v_entry;
end $$;
revoke execute on function public.allow_signup_email(text) from public, anon, authenticated, service_role;

create function public.remove_signup_email(user_email text) returns text
    language plpgsql security definer
    set search_path to ''
    as $$
declare
    v_entry text := lower(btrim($1));
begin
    if not hub_private.caller_is_owner() then
        raise exception 'only the database owner can change the sign-up list';
    end if;
    delete from hub_private.signup_allow_list where entry = v_entry;
    if not found then
        raise exception 'that email is not on the sign-up list';
    end if;
    return v_entry;
end $$;
revoke execute on function public.remove_signup_email(text) from public, anon, authenticated, service_role;

-- Upstream's trigger with one check put first. The rest is as it was.
CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  sales_count int;
begin
  if not hub_private.signup_allowed(new.email) then
    raise exception 'Sign up is not allowed: this email is not on the hub''s list';
  end if;

  select count(id) into sales_count
  from public.sales;

  delete from public.user_invitations where user_id = new.id;
  if sales_count > 0 and not found and not new.is_sso_user then
    raise exception 'Sign up is not allowed';
  end if;

  insert into public.sales (first_name, last_name, email, user_id, administrator)
  values (
    coalesce(new.raw_user_meta_data ->> 'first_name', new.raw_user_meta_data -> 'custom_claims' ->> 'first_name', 'Pending'),
    coalesce(new.raw_user_meta_data ->> 'last_name', new.raw_user_meta_data -> 'custom_claims' ->> 'last_name', 'Pending'),
    new.email,
    new.id,
    case when sales_count > 0 then FALSE else TRUE end
  );
  return new;
end;
$function$
;

-- A revoke that changes nothing is silent (docs/FINDINGS.md, issue 35): ask.
do $$
declare
    r text;
begin
    foreach r in array array['anon', 'authenticated', 'service_role', 'hub_export'] loop
        if exists (select 1 from pg_catalog.pg_roles where rolname = r) and (
            pg_catalog.has_schema_privilege(r, 'hub_private', 'USAGE')
            or pg_catalog.has_function_privilege(r, 'public.allow_signup_email(text)', 'EXECUTE')
            or pg_catalog.has_function_privilege(r, 'public.remove_signup_email(text)', 'EXECUTE')
        ) then
            raise exception '% can still reach the sign-up list', r;
        end if;
    end loop;
end $$;

-- =============================================================== 20261123100100_hub_no_attachments.sql
-- team hub, issue 40 item 14: no file is attached to a touch.
--
-- Upstream lets a note carry attachments: entries whose src is shown as a
-- link with no check, kept in a bucket that serves a file to anyone holding
-- its address. The hub does not use them (a decision on issue 40). The
-- screens no longer offer attaching (hub.shows.attachments); here the
-- database refuses any new entry, on touches and on deal notes, for every
-- writer, and the bucket stops serving files without a sign-in. Taking an
-- entry away is still allowed, so an old note can be cleaned.

create function public.hub_refuse_new_attachments() returns trigger
    language plpgsql
    set search_path to ''
    as $$
begin
    if exists (
        select 1
        from unnest(coalesce(new.attachments, '{}'::jsonb[])) as a(entry)
        where tg_op = 'INSERT'
           or not (a.entry = any (coalesce(old.attachments, '{}'::jsonb[])))
    ) then
        raise exception 'files are not attached to a note in the hub: write what the file says in the note';
    end if;
    return new;
end $$;
revoke execute on function public.hub_refuse_new_attachments() from public, anon, authenticated, service_role;

create trigger hub_refuse_new_attachments
    before insert or update of attachments on public.contact_notes
    for each row execute function public.hub_refuse_new_attachments();
create trigger hub_refuse_new_attachments
    before insert or update of attachments on public.deal_notes
    for each row execute function public.hub_refuse_new_attachments();

update storage.buckets set public = false where id = 'attachments';

do $$
begin
    if exists (select 1 from storage.buckets where id = 'attachments' and public) then
        raise exception 'the attachments bucket is still public';
    end if;
end $$;

-- =============================================================== 20261123120000_hub_attachments_closed.sql
-- team hub, issue 47 item 1: nobody but the service key reaches the
-- attachments bucket.
--
-- Upstream's init migration gave every signed in user select, insert and
-- delete on the bucket's files (three policies on storage.objects). Issue 40
-- stopped notes pointing at files and made the bucket private, but those
-- policies stayed, so a teammate could still upload, read and remove files
-- through the storage API. Nothing in the hub reads the files any more: the
-- screens draw no attachment (issue 47 item 2) and the cloud holds none. So
-- all three go, select included. An old file can still be read with the
-- service key, from the Supabase dashboard.

drop policy "Attachments 1mt4rzk_0" on storage.objects;
drop policy "Attachments 1mt4rzk_1" on storage.objects;
drop policy "Attachments 1mt4rzk_3" on storage.objects;

do $$
begin
    if exists (select 1 from pg_catalog.pg_policies
               where schemaname = 'storage' and tablename = 'objects'
                 and (coalesce(qual, '') ~ 'attachments' or coalesce(with_check, '') ~ 'attachments')) then
        raise exception 'a policy on storage.objects still names the attachments bucket';
    end if;
end $$;

-- =============================================================== 20261123120100_hub_invite_teammate.sql
-- team hub, issue 47 (router addition): a teammate's account can be made
-- from the Supabase dashboard.
--
-- Upstream's sign-up trigger lets nobody in after the first user unless a
-- row in public.user_invitations holds the new user's id before the account
-- exists. The users function writes that row and then makes the account with
-- the same id; the dashboard's "Create new user" picks its own id, so it was
-- refused ("Sign up is not allowed", HTTP 500). With no mail sender at
-- go-live, the administrator makes each teammate's account in the dashboard.
--
-- So an invitation may also be an email address: invite_teammate_email(),
-- which only a direct session of the database's owner (the SQL editor) may
-- run, the same check as allow_signup_email(). The trigger accepts a new
-- account whose address was invited that way, and uses the invitation up.
-- The sign-up list is still asked first and is never bypassed: an invited
-- address that is not on the list is refused.

create table hub_private.invited_emails (
    email text primary key,
    added_at timestamptz not null default now(),
    added_by text not null default session_user,
    constraint invited_emails_shape check (
        email = lower(btrim(email))
        and email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'
    )
);
revoke all on table hub_private.invited_emails from public, anon, authenticated, service_role;

create function public.invite_teammate_email(user_email text) returns text
    language plpgsql security definer
    set search_path to ''
    as $$
declare
    v_email text := lower(btrim($1));
begin
    if not hub_private.caller_is_owner() then
        raise exception 'only the database owner can invite a teammate';
    end if;
    if v_email is null or v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
        raise exception 'that is not one email address';
    end if;
    insert into hub_private.invited_emails (email) values (v_email)
        on conflict (email) do nothing;
    return v_email;
end $$;
revoke execute on function public.invite_teammate_email(text) from public, anon, authenticated, service_role;

-- Upstream's trigger as issue 40 left it, with an invitation by address
-- counted beside an invitation by id. The rest is as it was.
CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  sales_count int;
  invited boolean;
begin
  if not hub_private.signup_allowed(new.email) then
    raise exception 'Sign up is not allowed: this email is not on the hub''s list';
  end if;

  select count(id) into sales_count
  from public.sales;

  delete from public.user_invitations where user_id = new.id;
  invited := found;
  delete from hub_private.invited_emails where email = lower(btrim(new.email));
  invited := invited or found;
  if sales_count > 0 and not invited and not new.is_sso_user then
    raise exception 'Sign up is not allowed';
  end if;

  insert into public.sales (first_name, last_name, email, user_id, administrator)
  values (
    coalesce(new.raw_user_meta_data ->> 'first_name', new.raw_user_meta_data -> 'custom_claims' ->> 'first_name', 'Pending'),
    coalesce(new.raw_user_meta_data ->> 'last_name', new.raw_user_meta_data -> 'custom_claims' ->> 'last_name', 'Pending'),
    new.email,
    new.id,
    case when sales_count > 0 then FALSE else TRUE end
  );
  return new;
end;
$function$
;

-- A revoke that changes nothing is silent (docs/FINDINGS.md, issue 35): ask.
do $$
declare
    r text;
begin
    foreach r in array array['anon', 'authenticated', 'service_role', 'hub_export'] loop
        if exists (select 1 from pg_catalog.pg_roles where rolname = r) and (
            pg_catalog.has_function_privilege(r, 'public.invite_teammate_email(text)', 'EXECUTE')
            or pg_catalog.has_table_privilege(r, 'hub_private.invited_emails', 'SELECT, INSERT, UPDATE, DELETE')
        ) then
            raise exception '% can still reach the invitations by address', r;
        end if;
    end loop;
end $$;

-- =============================================================== 20261123120200_hub_export_seatbelt.sql
-- team hub, issue 47 item 4: a seatbelt on the export's role.
--
-- Every role may call the functions that make, change or remove a large
-- object (lo_creat, lo_create, lo_unlink, lo_put, lowrite, lo_from_bytea,
-- lo_truncate, lo_truncate64). They belong to Supabase's superuser, and a
-- revoke run as the role migrations run as does nothing (docs/FINDINGS.md,
-- issue 47). Accepted as a limit (docs/DECISIONS.md, issue 47): whoever holds
-- the export's password could store data in large objects, and could not
-- read or change anything else in the hub.
--
-- This sets hub_export's sessions to start read only, so a session that does
-- nothing about it writes no table. It does not stop the large object
-- functions, which Postgres lets run in a read only transaction (seen in the
-- export-test workflow, issue 47). It is a seatbelt, not a wall: the role may
-- switch it off for its own session (set default_transaction_read_only =
-- off), as any role may.

alter role hub_export set default_transaction_read_only = on;

do $$
begin
    if not exists (
        select 1 from pg_catalog.pg_db_role_setting s
            join pg_catalog.pg_roles r on r.oid = s.setrole
        where r.rolname = 'hub_export' and s.setdatabase = 0
          and 'default_transaction_read_only=on' = any (s.setconfig)
    ) then
        raise exception 'hub_export does not start read only';
    end if;
end $$;

-- =============================================================== 20261123130000_hub_set_teammate.sql
-- team hub, issue 62. Ours, not upstream's. Undo: reverts/ (same file name).
--
-- A teammate's name is right from the start, and stays right.
--
-- 1. public.set_teammate(email, handle, first_name, last_name): the handle
--    and the name in one call, at invite. The dashboard's "Create new user"
--    has no name field, so every account it made started as "Pending"
--    "Pending" (upstream's handle_new_user falls back to 'Pending', and that
--    default stays). The name is written to public.sales and to the auth
--    user's raw_user_meta_data, so the two never disagree.
--
-- 2. public.handle_update_user(), upstream's trigger on every update of
--    auth.users, rewrote first_name and last_name from the user's metadata,
--    falling back to 'Pending'. A sign-in updates the user row, so a name
--    kept only in public.sales was wiped at the next sign-in (seen live at
--    go-live, docs/FINDINGS.md). It now keeps the name already in sales when
--    the metadata holds none (missing or blank), and still copies the email.
--
-- No row of public.sales is written by this migration: the last block checks
-- that every name is as it was before it ran.

do $$
begin
    perform pg_catalog.set_config('hub.names_before_62', coalesce((
        select pg_catalog.md5(pg_catalog.string_agg(
            s.id::text || ':' || coalesce(s.first_name, '(null)') || ':' || coalesce(s.last_name, '(null)'),
            ',' order by s.id))
        from public.sales s), 'none'), false);
end $$;

CREATE OR REPLACE FUNCTION public.handle_update_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  -- team hub (issue 62): a name missing or blank (spaces, tabs) in the
  -- metadata keeps the name already in sales, never 'Pending'. A name is
  -- trimmed, as set_teammate() trims it.
  update public.sales s
  set
    first_name = coalesce(
      nullif(pg_catalog.regexp_replace(new.raw_user_meta_data ->> 'first_name', '^\s+|\s+$', '', 'g'), ''),
      nullif(pg_catalog.regexp_replace(new.raw_user_meta_data -> 'custom_claims' ->> 'first_name', '^\s+|\s+$', '', 'g'), ''),
      s.first_name),
    last_name = coalesce(
      nullif(pg_catalog.regexp_replace(new.raw_user_meta_data ->> 'last_name', '^\s+|\s+$', '', 'g'), ''),
      nullif(pg_catalog.regexp_replace(new.raw_user_meta_data -> 'custom_claims' ->> 'last_name', '^\s+|\s+$', '', 'g'), ''),
      s.last_name),
    email = new.email
  where s.user_id = new.id;

  return new;
end;
$function$
;

-- The same callers and refusals as set_teammate_handle(), which it calls for
-- the handle: an administrator through the API, or a direct session of the
-- database's owner (the SQL editor). Names are trimmed and kept as typed,
-- accents included; a blank one is refused. Called twice the same way, the
-- second call writes nothing.
create function public.set_teammate(email text, handle text, first_name text, last_name text) returns text
    language plpgsql security definer
    set search_path to ''
    as $$
#variable_conflict use_column
declare
    v_email text := lower(btrim($1));
    v_first text := pg_catalog.regexp_replace($3, '^\s+|\s+$', '', 'g');
    v_last text := pg_catalog.regexp_replace($4, '^\s+|\s+$', '', 'g');
    v_handle text;
    v_sales_id bigint;
    v_user_id uuid;
begin
    if auth.uid() is not null then
        if not public.is_admin() then
            raise exception 'only an administrator can set a handle';
        end if;
    elsif not hub_private.caller_is_owner() then
        raise exception 'only an administrator can set a handle';
    end if;

    if coalesce(v_first, '') = '' or coalesce(v_last, '') = '' then
        raise exception 'a first name and a last name are needed';
    end if;

    -- the handle, with set_teammate_handle's own checks and sentences
    perform public.set_teammate_handle(v_email, $2);
    v_handle := lower(btrim($2));

    select s.id, s.user_id into v_sales_id, v_user_id
    from public.sales s
    where lower(s.email::text) = v_email;

    update public.sales s
    set first_name = v_first, last_name = v_last
    where s.id = v_sales_id
        and (s.first_name is distinct from v_first or s.last_name is distinct from v_last);

    update auth.users u
    set raw_user_meta_data = coalesce(u.raw_user_meta_data, '{}'::jsonb)
        || jsonb_build_object('first_name', v_first, 'last_name', v_last)
    where u.id = v_user_id
        and (u.raw_user_meta_data ->> 'first_name' is distinct from v_first
             or u.raw_user_meta_data ->> 'last_name' is distinct from v_last);

    return v_handle || ': ' || v_first || ' ' || v_last;
end;
$$;

revoke all on function public.set_teammate(text, text, text, text) from public, anon, authenticated, service_role;
grant execute on function public.set_teammate(text, text, text, text) to authenticated, service_role;

-- A revoke that changes nothing is silent (docs/FINDINGS.md, issue 35): ask.
-- And no name was changed by this migration.
do $$
declare
    r text;
begin
    foreach r in array array['anon', 'hub_export'] loop
        if exists (select 1 from pg_catalog.pg_roles where rolname = r)
            and pg_catalog.has_function_privilege(r, 'public.set_teammate(text, text, text, text)', 'EXECUTE') then
            raise exception '% can still call set_teammate', r;
        end if;
    end loop;
    if coalesce((
        select pg_catalog.md5(pg_catalog.string_agg(
            s.id::text || ':' || coalesce(s.first_name, '(null)') || ':' || coalesce(s.last_name, '(null)'),
            ',' order by s.id))
        from public.sales s), 'none') is distinct from pg_catalog.current_setting('hub.names_before_62', true) then
        raise exception 'a name in public.sales changed while this migration ran';
    end if;
end $$;

-- =============================================================== 20261123140000_hub_text_channel.sql
-- team hub, issue 63: a 'text' channel for touches (SMS, iMessage, WhatsApp
-- and the like). Ours, not upstream's. Undo: reverts/ (same file name).
--
-- The allowed channels become, in this order: email, linkedin, phone, text,
-- intro, in-person, other. Two places hold the list and both change here: the
-- check on contact_notes and log_touch, whose refusal names the list. Old
-- touches logged as 'other' stay 'other': nothing is backfilled.
--
-- log_touch is replaced in place (same arguments, so its grants and revokes
-- stay as issue 22 set them). Its body is the one of
-- 20261122110100_hub_actions_people.sql with the list changed, nothing else.

alter table public.contact_notes
    drop constraint contact_notes_channel_known;
alter table public.contact_notes
    add constraint contact_notes_channel_known check (channel in (
        'email', 'linkedin', 'phone', 'text', 'intro', 'in-person', 'other'));

create or replace function public.log_touch(
        person_code text,
        by text default null,
        date date default null,
        channel text default null,
        what text default null,
        next_step text default null,
        next_due date default null,
        status text default null,
        via text default 'ui')
    returns jsonb
    language plpgsql security definer
    set search_path to ''
    as $$
declare
    v_me public.sales := public.hub_begin('log_touch', $9);
    v_p public.contacts := public.hub_person($1);
    v_by public.sales := public.hub_teammate($2, 'by', v_me);
    v_channel text := lower(btrim(coalesce($4, '')));
    v_what text := public.hub_block($5, 'what', 10000, true);
    v_next text := public.hub_line($6, 'next step', 300, false);
    v_status text := nullif(lower(btrim(coalesce($8, ''))), '');
    v_when timestamp with time zone;
    v_touch bigint;
begin
    if v_channel = '' then
        raise exception 'the channel is empty: use email, linkedin, phone, text, intro, in-person or other';
    end if;
    if v_channel not in ('email', 'linkedin', 'phone', 'text', 'intro', 'in-person', 'other') then
        raise exception 'channel ''%'' is not allowed: use email, linkedin, phone, text, intro, in-person or other',
            left(v_channel, 40);
    end if;
    if $3 is not null and $3 > public.hub_latest_today() then
        raise exception 'the date % is in the future', $3;
    end if;
    if $7 is not null and v_next is null then
        raise exception 'a due date needs a next step';
    end if;
    if v_status = 'interviewed' then
        raise exception 'interviewed is set by saving an interview, not by a touch';
    end if;
    if v_status is not null
        and v_status not in ('to-contact', 'contacted', 'replied', 'scheduled', 'declined', 'do-not-contact') then
        raise exception 'status ''%'' is not allowed: use to-contact, contacted, replied, scheduled, declined or do-not-contact',
            left(v_status, 40);
    end if;
    -- with no status given, the first touch on a to-contact person makes them contacted
    if v_status is null and v_p.status = 'to-contact' then
        v_status := 'contacted';
    end if;

    -- a touch with no date happened now; one with a date, at noon UTC of that day
    v_when := case when $3 is null then now()
                   else ($3::timestamp + interval '12 hours') at time zone 'UTC' end;

    insert into public.contact_notes (contact_id, date, sales_id, channel, text, next_step, next_due, status)
    values (v_p.id, v_when, v_by.id, v_channel, v_what, v_next, $7, coalesce(v_status, v_p.status))
    returning id into v_touch;

    if v_status is not null and v_status <> v_p.status then
        update public.contacts c set status = v_status where c.id = v_p.id;
    end if;

    perform public.hub_end();
    return jsonb_build_object(
        'touch_id', v_touch,
        'person_code', v_p.person_code,
        'by', v_by.handle,
        'status', coalesce(v_status, v_p.status));
end;
$$;

-- =============================================================== 20261124100000_hub_contact_details.sql
-- team hub, issue 64: a person carries several contact details, each filed
-- where it belongs and each found by find_person. Ours, not upstream's.
-- Undo: reverts/ (same file name).
--
-- What changes:
-- - contacts gains links text[] (never null, empty by default): web addresses
--   that are not the person's LinkedIn. A check holds every entry to http://
--   or https:// and no space, as contacts_linkedin_url_is_web does for
--   linkedin_url (which stays as it is). No helper is called from the check,
--   for the reason 20261122130100_hub_link_columns.sql gives.
-- - hub_sort_contact_detail sorts one detail, in this order: email (an @ and
--   no space), LinkedIn (names linkedin.com), web link (http:// or https://,
--   or a bare host with a path, given https://), phone (digits, spaces and
--   + ( ) -, seven digits or more). Anything else is refused in one plain
--   line, never a constraint name. add_person and update_person both use it,
--   so the app and hub.py file a detail the same way.
-- - add_person and update_person take contacts text[] (new, last): every
--   detail is sorted before anything is written, at most 10 a call, one bad
--   detail refuses the call. The old single contact text still works and is
--   sorted the same way. A detail already on another person refuses the
--   call, naming that person; one already on this person is skipped. Details
--   are compared without letter case, https:// and a trailing /; phones by
--   their digits. The identity lock every person write takes keeps two at
--   once from both passing the check.
-- - find_person also matches links and returns contact: every detail of the
--   person, emails, phones, LinkedIn, then links.
--
-- Existing rows are not rewritten. The three actions are dropped and made
-- again (new argument or new column), with the same grants.

alter table public.contacts
    add column links text[] not null default '{}';

-- Every entry http:// or https:// and something with no space after it. The
-- entries are joined with a line break, which no entry may hold.
alter table public.contacts
    add constraint contacts_links_are_web
        check (cardinality(links) = 0
               or (array_position(links, null) is null
                   and array_to_string(links, E'\n')
                       ~* '^https?://[^[:space:][:cntrl:]]+(\nhttps?://[^[:space:][:cntrl:]]+)*$'));

-- The person page and the people list read this view: it gains links at its
-- end, so it is replaced in place and keeps its grants.
create or replace view public.contacts_summary with (security_invoker = on) as
select
    co.id,
    co.first_name,
    co.last_name,
    co.gender,
    co.title,
    co.background,
    co.avatar,
    co.first_seen,
    co.last_seen,
    co.has_newsletter,
    co.status,
    co.tags,
    co.company_id,
    co.sales_id,
    co.linkedin_url,
    co.email_jsonb,
    co.phone_jsonb,
    (jsonb_path_query_array(co.email_jsonb, '$[*]."email"'))::text as email_fts,
    (jsonb_path_query_array(co.phone_jsonb, '$[*]."number"'))::text as phone_fts,
    c.name as company_name,
    count(distinct t.id) filter (where t.done_date is null) as nb_tasks,
    co.person_code,
    co.slug,
    co.name_key,
    co.quote_by_name,
    co.contact_key,
    co.referred_by,
    co.referred_by_contact_id,
    co.links
from public.contacts co
    left join public.tasks t on co.id = t.contact_id
    left join public.companies c on co.company_id = c.id
group by co.id, c.name;

-- ---------------------------------------------------------------- shared parts

-- A detail as it is compared: no letter case, no http:// or https://, no
-- trailing /, and a phone as its digits only.
create function public.hub_contact_norm(detail text) returns text
    language plpgsql immutable
    set search_path to ''
    as $$
declare
    v text := lower(btrim(coalesce($1, ''), E' \t\n\r'));
begin
    if v ~ '^[0-9 +()-]+$' then
        return regexp_replace(v, '[^0-9]', '', 'g');
    end if;
    v := regexp_replace(v, '^https?://', '');
    return regexp_replace(v, '/+$', '');
end;
$$;

-- One detail sorted: {"kind": email | linkedin | link | phone, "value": as
-- stored}. Null for a blank detail. A detail of no kind is refused.
create function public.hub_sort_contact_detail(detail text) returns jsonb
    language plpgsql immutable
    set search_path to ''
    as $$
declare
    -- a host name, then a path, a query or a fragment
    c_bare_path constant text := '^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+(:[0-9]{1,5})?[/?#][^[:space:]]*$';
    c_web constant text := '^https?://[^[:space:]]+$';
    v text := public.hub_line($1, 'contact detail', 300, false);
begin
    if v is null then
        return null;
    end if;
    if position('@' in v) > 0 and v !~ '[[:space:]]' then
        return jsonb_build_object('kind', 'email', 'value', lower(v));
    end if;
    if lower(v) like '%linkedin.com%' then
        if v ~* c_web then
            return jsonb_build_object('kind', 'linkedin', 'value', v);
        elsif v ~* c_bare_path then
            return jsonb_build_object('kind', 'linkedin', 'value', 'https://' || v);
        end if;
    elsif v ~* c_web then
        return jsonb_build_object('kind', 'link', 'value', v);
    elsif v ~* c_bare_path then
        return jsonb_build_object('kind', 'link', 'value', 'https://' || v);
    elsif v ~ '^[0-9 +()-]+$' and char_length(regexp_replace(v, '[^0-9]', '', 'g')) >= 7 then
        return jsonb_build_object('kind', 'phone', 'value', v);
    end if;
    raise exception 'contact detail "%" is not an email, phone, LinkedIn or web link', left(v, 40)
        using errcode = 'check_violation';
end;
$$;

-- Every detail of a call sorted, each once, in the order given. At most 10.
create function public.hub_sort_contact_details(details text[]) returns jsonb
    language plpgsql immutable
    set search_path to ''
    as $$
declare
    v_given text[] := array(select d from unnest(coalesce($1, '{}'::text[])) d
                            where btrim(coalesce(d, ''), E' \t\n\r') <> '');
    v_detail text;
    v_one jsonb;
    v_out jsonb := '[]'::jsonb;
    v_seen text[] := '{}';
    v_norm text;
begin
    if cardinality(v_given) > 10 then
        raise exception 'at most 10 contact details in one call: % given', cardinality(v_given)
            using errcode = 'check_violation';
    end if;
    foreach v_detail in array v_given loop
        v_one := public.hub_sort_contact_detail(v_detail);
        v_norm := public.hub_contact_norm(v_one ->> 'value');
        if not v_norm = any(v_seen) then
            v_seen := v_seen || v_norm;
            v_out := v_out || jsonb_build_array(v_one || jsonb_build_object('norm', v_norm));
        end if;
    end loop;
    return v_out;
end;
$$;

-- Every detail a person holds, as compared.
create function public.hub_contact_norms(person public.contacts) returns text[]
    language sql immutable
    set search_path to ''
    as $$
    select coalesce(array_agg(distinct public.hub_contact_norm(d)) filter (where btrim(coalesce(d, '')) <> ''), '{}')
    from (
        select e ->> 'email' as d
        from jsonb_array_elements(case when jsonb_typeof(($1).email_jsonb) = 'array'
                                       then ($1).email_jsonb else '[]'::jsonb end) e
        union all
        select p ->> 'number'
        from jsonb_array_elements(case when jsonb_typeof(($1).phone_jsonb) = 'array'
                                       then ($1).phone_jsonb else '[]'::jsonb end) p
        union all
        select ($1).linkedin_url
        union all
        select ($1).contact_key
        union all
        select l from unnest(coalesce(($1).links, '{}'::text[])) l) all_details
    $$;

-- Files sorted details on a person (not yet written): each is refused when
-- another person holds it, skipped when this one does, and otherwise added
-- under its kind. A first LinkedIn goes to linkedin_url, another to links.
-- The caller holds the identity lock and writes the row.
create function public.hub_file_contact_details(person public.contacts, sorted jsonb) returns public.contacts
    language plpgsql
    set search_path to ''
    as $$
declare
    v_p public.contacts := $1;
    v_one jsonb;
    v_value text;
    v_norm text;
    v_other bigint;
begin
    for v_one in select * from jsonb_array_elements(coalesce($2, '[]'::jsonb)) loop
        v_value := v_one ->> 'value';
        v_norm := v_one ->> 'norm';
        select c.id into v_other from public.contacts c
        where c.id is distinct from v_p.id and v_norm = any(public.hub_contact_norms(c))
        order by c.id
        limit 1;
        if v_other is not null then
            raise exception 'already on file (same contact): %', public.hub_describe_person(v_other);
        end if;
        continue when v_norm = any(public.hub_contact_norms(v_p));

        if v_one ->> 'kind' = 'email' then
            v_p.email_jsonb := case when jsonb_typeof(v_p.email_jsonb) = 'array' then v_p.email_jsonb else '[]'::jsonb end
                || jsonb_build_array(jsonb_build_object('email', v_value, 'type', 'Work'));
        elsif v_one ->> 'kind' = 'phone' then
            v_p.phone_jsonb := case when jsonb_typeof(v_p.phone_jsonb) = 'array' then v_p.phone_jsonb else '[]'::jsonb end
                || jsonb_build_array(jsonb_build_object('number', v_value, 'type', 'Work'));
        elsif v_one ->> 'kind' = 'linkedin' and coalesce(btrim(v_p.linkedin_url), '') = '' then
            v_p.linkedin_url := v_value;
        else
            v_p.links := coalesce(v_p.links, '{}'::text[]) || v_value;
        end if;
    end loop;
    return v_p;
end;
$$;

revoke all on function public.hub_contact_norm(text) from public, anon, authenticated, service_role;
revoke all on function public.hub_sort_contact_detail(text) from public, anon, authenticated, service_role;
revoke all on function public.hub_sort_contact_details(text[]) from public, anon, authenticated, service_role;
revoke all on function public.hub_contact_norms(public.contacts) from public, anon, authenticated, service_role;
revoke all on function public.hub_file_contact_details(public.contacts, jsonb) from public, anon, authenticated, service_role;

-- ---------------------------------------------------------------- find_person
drop function public.find_person(text, text);

create function public.find_person(query text, via text default 'ui')
    returns table (person_code text, name text, role text, organization text, owner text, status text,
                   last_touch_date date, last_touch_channel text, last_touch_text text, contact text[])
    language plpgsql stable security definer
    set search_path to ''
    as $$
#variable_conflict use_column
declare
    v_q text := lower(btrim(coalesce($1, ''), E' \t\n\r'));
    v_fold text;
begin
    perform public.hub_caller();
    if $2 is null or $2 not in ('ui', 'claude') then
        raise exception 'via must be ui or claude';
    end if;
    if v_q = '' then
        raise exception 'the query is empty: give a name, a person code, a contact detail or an organization';
    end if;
    if char_length(v_q) > 300 then
        raise exception 'the query is too long: % characters, the limit is 300', char_length(v_q);
    end if;
    v_fold := public.hub_name_fold(v_q);

    return query
    select c.person_code,
           btrim(coalesce(c.first_name, '') || ' ' || coalesce(c.last_name, '')),
           c.title,
           co.name,
           s.handle,
           c.status,
           (t.date at time zone 'UTC')::date,
           t.channel,
           left(t.text, 80),
           array(select every_detail.detail from (
                     select em.val ->> 'email' as detail, 1 as part, em.ord
                     from jsonb_array_elements(case when jsonb_typeof(c.email_jsonb) = 'array'
                                                    then c.email_jsonb else '[]'::jsonb end) with ordinality em(val, ord)
                     union all
                     select ph.val ->> 'number', 2, ph.ord
                     from jsonb_array_elements(case when jsonb_typeof(c.phone_jsonb) = 'array'
                                                    then c.phone_jsonb else '[]'::jsonb end) with ordinality ph(val, ord)
                     union all
                     select c.linkedin_url, 3, 1
                     union all
                     select lk.val, 4, lk.ord from unnest(c.links) with ordinality lk(val, ord)) every_detail
                 where btrim(coalesce(every_detail.detail, '')) <> ''
                 order by every_detail.part, every_detail.ord)
    from public.contacts c
        left join public.companies co on co.id = c.company_id
        left join public.sales s on s.id = c.sales_id
        left join lateral (
            select n.date, n.channel, n.text
            from public.contact_notes n
            where n.contact_id = c.id
            order by n.date desc, n.id desc
            limit 1) t on true
    where position(v_q in lower(c.person_code)) > 0
        or position(v_q in lower(c.slug)) > 0
        or (v_fold <> '' and position(v_fold in c.name_key) > 0)
        or position(v_q in lower(coalesce(c.first_name, '') || ' ' || coalesce(c.last_name, ''))) > 0
        or position(v_q in lower(coalesce(c.contact_key, ''))) > 0
        or position(v_q in lower(coalesce(c.linkedin_url, ''))) > 0
        or position(v_q in lower(coalesce(co.name, ''))) > 0
        or exists (select 1 from unnest(c.links) lk(val) where position(v_q in lower(lk.val)) > 0)
        or exists (
            select 1
            from jsonb_array_elements(case when jsonb_typeof(c.email_jsonb) = 'array'
                                           then c.email_jsonb else '[]'::jsonb end) e
            where position(v_q in lower(coalesce(e ->> 'email', ''))) > 0)
        or exists (
            select 1
            from jsonb_array_elements(case when jsonb_typeof(c.phone_jsonb) = 'array'
                                           then c.phone_jsonb else '[]'::jsonb end) p
            where position(v_q in lower(coalesce(p ->> 'number', ''))) > 0)
    order by split_part(c.person_code, '-', 1), substring(c.person_code from '[0-9]+$')::integer;
end;
$$;

-- ----------------------------------------------------------------- add_person
drop function public.add_person(text, text, text, text, text, text, boolean, text);

create function public.add_person(
        name text,
        owner text default null,
        role text default null,
        organization text default null,
        contact text default null,
        referred_by text default null,
        quote_by_name boolean default null,
        via text default 'ui',
        contacts text[] default null)
    returns jsonb
    language plpgsql security definer
    set search_path to ''
    as $$
declare
    v_me public.sales := public.hub_begin('add_person', $8);
    v_name text := public.hub_line($1, 'name', 200, true);
    v_owner public.sales := public.hub_teammate($2, 'owner', v_me);
    v_role text := public.hub_line($3, 'role', 300, false);
    v_org text := public.hub_line($4, 'organization', 300, false);
    v_details jsonb := public.hub_sort_contact_details(array[$5] || coalesce($9, '{}'::text[]));
    v_referred text := public.hub_line($6, 'referred by', 300, false);
    v_key text;
    v_other bigint;
    v_cut integer;
    v_first text;
    v_last text;
    v_company bigint;
    v_p public.contacts;
    v_new public.contacts;
begin
    v_key := public.hub_name_key(v_name);
    if v_key = '' then
        raise exception '''%'' is only a title or punctuation, not a name', v_name;
    end if;
    if v_key !~ '[^0-9 ]' then
        raise exception '''%'' is only a number, not a name', v_name;
    end if;

    -- One person is added at a time (the same lock the insert takes), so two
    -- teammates adding one person, or one detail, at once get one person and
    -- one refusal.
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('hub.contacts.identity', 0));
    select c.id into v_other from public.contacts c where c.name_key = v_key limit 1;
    if v_other is not null then
        raise exception 'already on file (same name): %', public.hub_describe_person(v_other);
    end if;
    v_p.email_jsonb := '[]'::jsonb;
    v_p.phone_jsonb := '[]'::jsonb;
    v_p.links := '{}';
    v_p := public.hub_file_contact_details(v_p, v_details);

    -- the full name splits at its last space
    v_cut := char_length(v_name) - position(' ' in reverse(v_name)) + 1;
    if position(' ' in v_name) = 0 then
        v_first := v_name;
        v_last := '';
    else
        v_first := btrim(left(v_name, v_cut - 1));
        v_last := substr(v_name, v_cut + 1);
    end if;

    if v_org is not null then
        v_company := public.hub_company(v_org, v_me.id);
    end if;

    insert into public.contacts (first_name, last_name, title, company_id, sales_id, status, contact_key,
                                 referred_by, quote_by_name, first_seen, last_seen, tags,
                                 email_jsonb, phone_jsonb, linkedin_url, links)
    values (v_first, v_last, v_role, v_company, v_owner.id, 'to-contact', v_details -> 0 ->> 'value',
            v_referred, coalesce($7, false), now(), now(), '{}',
            v_p.email_jsonb, v_p.phone_jsonb, v_p.linkedin_url, v_p.links)
    returning * into v_new;

    perform public.hub_end();
    return jsonb_build_object(
        'person_code', v_new.person_code,
        'slug', v_new.slug,
        'name', v_name,
        'owner', v_owner.handle,
        'status', v_new.status);
end;
$$;

-- -------------------------------------------------------------- update_person
drop function public.update_person(text, text, text, text, text, boolean, text, text);

create function public.update_person(
        person_code text,
        role text default null,
        organization text default null,
        contact text default null,
        referred_by text default null,
        quote_by_name boolean default null,
        notes text default null,
        via text default 'ui',
        contacts text[] default null)
    returns jsonb
    language plpgsql security definer
    set search_path to ''
    as $$
declare
    v_me public.sales := public.hub_begin('update_person', $8);
    v_p public.contacts := public.hub_person($1);
    v_role text := public.hub_line($2, 'role', 300, false);
    v_org text := public.hub_line($3, 'organization', 300, false);
    v_contact jsonb := public.hub_sort_contact_details(array[$4]);
    v_details jsonb := public.hub_sort_contact_details($9);
    v_referred text := public.hub_line($5, 'referred by', 300, false);
    v_notes text := public.hub_block($7, 'notes', 10000, false);
    v_before public.contacts;
    v_changed text[] := '{}';
begin
    if $2 is null and $3 is null and $4 is null and $5 is null and $6 is null and $7 is null
        and coalesce(cardinality($9), 0) = 0 then
        raise exception 'nothing to change: give at least one of role, organization, contact, referred_by, quote_by_name, notes';
    end if;

    if $2 is not null then
        v_p.title := v_role;
        v_changed := v_changed || 'role'::text;
    end if;
    if $3 is not null then
        v_p.company_id := case when v_org is null then null else public.hub_company(v_org, v_me.id) end;
        v_changed := v_changed || 'organization'::text;
    end if;
    if $4 is not null or jsonb_array_length(v_details) > 0 then
        perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('hub.contacts.identity', 0));
    end if;
    -- The one contact, as before: it becomes the contact key (an empty one
    -- clears it) and is filed under its kind.
    if $4 is not null then
        if jsonb_array_length(v_contact) = 0 then
            v_p.contact_key := null;
        else
            v_p := public.hub_file_contact_details(v_p, v_contact);
            v_p.contact_key := lower(v_contact -> 0 ->> 'value');
        end if;
        v_changed := v_changed || 'contact'::text;
    end if;
    -- The list: added, never replacing.
    if jsonb_array_length(v_details) > 0 then
        v_before := v_p;
        v_p := public.hub_file_contact_details(v_p, v_details);
        if v_p.contact_key is null then
            v_p.contact_key := lower(v_details -> 0 ->> 'value');
        end if;
        if (v_p.email_jsonb, v_p.phone_jsonb, v_p.linkedin_url, v_p.links, v_p.contact_key)
            is distinct from (v_before.email_jsonb, v_before.phone_jsonb, v_before.linkedin_url, v_before.links,
                              v_before.contact_key)
            and not 'contact' = any(v_changed) then
            v_changed := v_changed || 'contact'::text;
        end if;
    end if;
    if $5 is not null then
        v_p.referred_by := v_referred;
        v_changed := v_changed || 'referred_by'::text;
    end if;
    if $6 is not null then
        v_p.quote_by_name := $6;
        v_changed := v_changed || 'quote_by_name'::text;
    end if;
    if $7 is not null then
        v_p.background := v_notes;
        v_changed := v_changed || 'notes'::text;
    end if;

    if cardinality(v_changed) > 0 then
        update public.contacts c
        set title = v_p.title,
            company_id = v_p.company_id,
            contact_key = v_p.contact_key,
            email_jsonb = v_p.email_jsonb,
            phone_jsonb = v_p.phone_jsonb,
            linkedin_url = v_p.linkedin_url,
            links = v_p.links,
            referred_by = v_p.referred_by,
            quote_by_name = v_p.quote_by_name,
            background = v_p.background
        where c.id = v_p.id;
    end if;

    perform public.hub_end();
    return jsonb_build_object('person_code', v_p.person_code, 'changed', to_jsonb(v_changed));
end;
$$;

revoke all on function public.find_person(text, text) from public, anon, authenticated, service_role;
revoke all on function public.add_person(text, text, text, text, text, text, boolean, text, text[]) from public, anon, authenticated, service_role;
revoke all on function public.update_person(text, text, text, text, text, boolean, text, text, text[]) from public, anon, authenticated, service_role;

grant execute on function public.find_person(text, text) to authenticated;
grant execute on function public.add_person(text, text, text, text, text, text, boolean, text, text[]) to authenticated;
grant execute on function public.update_person(text, text, text, text, text, boolean, text, text, text[]) to authenticated;

-- =============================================================== 20261124180000_hub_interview_kinds.sql
-- team hub, issue 83: an interview from notes or a debrief, not only from a
-- recorded transcript. Ours, not upstream's. Undo: reverts/ (same file name).
--
-- Every interview gets a kind:
--   transcript  today's: verbatim, 1000 characters or more (unchanged)
--   notes       typed or handwritten notes, typed in exactly as written
--   debrief     a teammate talking the interview through afterwards
-- Notes and debriefs need 100 characters or more. The text is kept as given,
-- in interview_transcripts, whatever the kind. The default is transcript, so
-- every interview already on file and every call made the old way reads and
-- works as before.
--
-- The kind is held on the interview and on its text, so the length rule stays
-- a check on the table itself; a foreign key on (interview_id, kind) keeps the
-- two the same. The inbox of recordings holds a kind too, so a Granola debrief
-- waits there as a debrief.
--
-- The quote rule: for notes, a quoted passage must be in the notes, as it must
-- be in a transcript. In a debrief the speaker is the teammate, so its overview
-- may not hold a double quotation mark at all.
--
-- save_interview, submit_recording and confirm_recording gain one argument,
-- kind, at the end, so calls by position and by name made before still work.
-- An added argument would make a second function beside the old one, so each
-- is dropped and made again, and given the rights issue 22 gave it.
-- hub_write_interview, which only they call, likewise. update_overview keeps
-- its arguments and is replaced in place. Each body is issue 22's
-- (20261122110200_hub_actions_interviews.sql) with the kind added.

-- ------------------------------------------------------------------ the tables
alter table public.interviews
    add column kind text not null default 'transcript';
alter table public.interviews
    add constraint interviews_kind_known check (kind in ('transcript', 'notes', 'debrief'));
alter table public.interviews
    add constraint interviews_id_kind_key unique (id, kind);

alter table public.interview_transcripts
    add column kind text not null default 'transcript';
alter table public.interview_transcripts
    drop constraint interview_transcripts_body_min_length;
alter table public.interview_transcripts
    add constraint interview_transcripts_body_min_length check (
        char_length(body) >= case when kind = 'transcript' then 1000 else 100 end);
alter table public.interview_transcripts
    add constraint interview_transcripts_kind_matches foreign key (interview_id, kind)
        references public.interviews (id, kind);

alter table public.call_inbox
    add column kind text not null default 'transcript';
alter table public.call_inbox
    add constraint call_inbox_kind_known check (kind in ('transcript', 'notes', 'debrief'));

-- ------------------------------------------------------------ shared parts
-- The kind given to an action. Null is transcript, as for every call made
-- before kinds existed; anything else must be one of the three.
create function public.hub_kind(kind text) returns text
    language plpgsql immutable
    set search_path to ''
    as $$
declare
    v_kind text := lower(btrim($1));
begin
    if $1 is null then
        return 'transcript';
    end if;
    if v_kind = '' then
        raise exception 'the kind is empty: use transcript, notes or debrief';
    end if;
    if v_kind not in ('transcript', 'notes', 'debrief') then
        raise exception 'kind ''%'' is not allowed: use transcript, notes or debrief', left(v_kind, 40);
    end if;
    return v_kind;
end;
$$;

-- The sentence when consent is not confirmed. For notes and a debrief the
-- question is whether the person agreed to be interviewed, not recorded.
create function public.hub_consent_refusal(kind text) returns text
    language sql immutable
    set search_path to ''
    as $$
    select case when $1 = 'transcript'
        then 'consent to record is not confirmed: an interview is saved only when the person agreed to be recorded'
        else 'consent is not confirmed: notes or a debrief are saved only when the person agreed to be interviewed'
    end
    $$;

-- The source and the text of an interview, checked by its kind. A transcript
-- goes through hub_check_transcript, unchanged. Notes and a debrief have the
-- same checks with 100 characters as the least. Returns the source.
create function public.hub_check_text(kind text, source text, body text, reported_chars integer) returns text
    language plpgsql immutable
    set search_path to ''
    as $$
declare
    v_source text := lower(btrim(coalesce($2, '')));
    v_chars integer;
begin
    if $1 = 'transcript' then
        return public.hub_check_transcript($2, $3, $4);
    end if;
    if v_source = '' then
        raise exception 'the source is empty: use granola, paste or other';
    end if;
    if v_source not in ('granola', 'paste', 'other') then
        raise exception 'source ''%'' is not allowed: use granola, paste or other', left(v_source, 40);
    end if;
    if $3 is null or $3 = '' then
        if $1 = 'notes' then
            raise exception 'the notes are empty';
        end if;
        raise exception 'the debrief is empty';
    end if;
    v_chars := char_length($3);
    if v_chars > 5000000 then
        raise exception 'the text is too long: % characters, the limit is 5000000', v_chars;
    end if;
    if v_chars < 100 then
        if $1 = 'notes' then
            raise exception 'the notes are too short: % characters, notes need at least 100', v_chars;
        end if;
        raise exception 'the debrief is too short: % characters, a debrief needs at least 100', v_chars;
    end if;
    if $4 is not null and $4 < 0 then
        raise exception 'reported_chars cannot be negative';
    end if;
    if v_source = 'granola' and $4 is null then
        raise exception 'a granola recording needs reported_chars, the size the recorder reported';
    end if;
    if $4 is not null and v_chars < $4 then
        raise exception 'the text is cut short: % of % characters', v_chars, $4;
    end if;
    return v_source;
end;
$$;

-- The quote rule by kind. A transcript: hub_check_quotes, unchanged. Notes:
-- the same rule against the notes. A debrief: no double quotation mark at all.
create function public.hub_check_overview(kind text, overview text, body text) returns void
    language plpgsql immutable
    set search_path to ''
    as $$
declare
    v_quote text;
begin
    if $1 = 'debrief' then
        if $2 ~ '["\u201C\u201D]' then
            raise exception 'a debrief overview cannot quote the interviewee: the words in a debrief are the teammate''s, so write the overview without double quotation marks';
        end if;
        return;
    end if;
    if $1 = 'transcript' then
        perform public.hub_check_quotes($2, $3);
        return;
    end if;
    if char_length(regexp_replace($2, '[^"\u201C\u201D]', '', 'g')) % 2 = 1 then
        raise exception 'the overview has an odd number of double quotation marks, so its quotes cannot be told apart: close the open one, or write a lone mark another way';
    end if;
    v_quote := public.hub_missing_quote($2, $3);
    if v_quote is not null then
        raise exception 'this quote in the overview is not word for word in the notes: "%"', left(v_quote, 60);
    end if;
end;
$$;

-- Writes an interview that has passed every check: the interview, its text
-- and its links, and the person becomes interviewed.
drop function public.hub_write_interview(bigint, date, bigint, bigint, text, text, text, text, text, integer, jsonb);
create function public.hub_write_interview(
        contact_id bigint, day date, interviewer_id bigint, created_by bigint, source text,
        granola_id text, title text, overview text, transcript text, reported_chars integer,
        hypotheses jsonb, kind text)
    returns bigint
    language plpgsql
    set search_path to ''
    as $$
declare
    v_id bigint;
begin
    insert into public.interviews (contact_id, date, interviewer_id, source, granola_id,
                                   consent_to_record, title, overview, created_by, kind)
    values ($1, $2, $3, $5, $6, true, $7, $8, $4, $12)
    returning id into v_id;
    insert into public.interview_transcripts (interview_id, body, reported_chars, kind)
    values (v_id, $9, $10, $12);
    insert into public.interview_hypotheses (interview_id, hypothesis, stance, why)
    select v_id, e ->> 'hypothesis', e ->> 'stance', e ->> 'why'
    from jsonb_array_elements($11) e;
    update public.contacts c set status = 'interviewed' where c.id = $1 and c.status <> 'interviewed';
    return v_id;
end;
$$;

-- ------------------------------------------------------------- save_interview
drop function public.save_interview(text, date, text, text, text, boolean, text, text, text, jsonb, integer, text);
create function public.save_interview(
        person_code text,
        date date,
        interviewer text default null,
        source text default null,
        granola_id text default null,
        consent_to_record boolean default null,
        title text default null,
        overview text default null,
        transcript text default null,
        hypotheses jsonb default null,
        reported_chars integer default null,
        via text default 'ui',
        kind text default 'transcript')
    returns jsonb
    language plpgsql security definer
    set search_path to ''
    as $$
declare
    v_me public.sales := public.hub_begin('save_interview', $12);
    v_kind text := public.hub_kind($13);
    v_p public.contacts;
    v_who public.sales;
    v_day date;
    v_gid text;
    v_title text;
    v_overview text;
    v_source text;
    v_hyp jsonb;
    v_on_file text;
    v_id bigint;
begin
    if $6 is not true then
        raise exception '%', public.hub_consent_refusal(v_kind);
    end if;
    v_gid := public.hub_line($5, 'granola_id', 300, false);
    -- locks are always taken in one order: the recording, then the person
    if v_gid is not null then
        perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('hub.recording.' || v_gid, 0));
    end if;
    v_p := public.hub_person($1);
    v_day := public.hub_day($2, 'date');
    v_who := public.hub_teammate($3, 'interviewer', v_me);
    v_title := public.hub_line($7, 'title', 300, true);
    v_overview := public.hub_block($8, 'overview', 100000, true);
    v_source := public.hub_check_text(v_kind, $4, $9, $11);
    v_hyp := public.hub_check_hypotheses($10);
    perform public.hub_check_overview(v_kind, v_overview, $9);
    if v_gid is not null then
        v_on_file := public.hub_recording_on_file(v_gid, null);
        if v_on_file is not null then
            raise exception '%', v_on_file;
        end if;
    end if;

    v_id := public.hub_write_interview(v_p.id, v_day, v_who.id, v_me.id, v_source, v_gid,
                                       v_title, v_overview, $9, $11, v_hyp, v_kind);
    perform public.hub_end();
    return jsonb_build_object(
        'interview_id', v_id,
        'person_code', v_p.person_code,
        'interviewer', v_who.handle,
        'status', 'interviewed',
        'kind', v_kind,
        'chars', char_length($9));
end;
$$;

-- ------------------------------------------------------------ update_overview
-- hypotheses null leaves the links as they are; a list, even an empty one, replaces them.
create or replace function public.update_overview(
        interview_id bigint,
        overview text,
        hypotheses jsonb default null,
        via text default 'ui')
    returns jsonb
    language plpgsql security definer
    set search_path to ''
    as $$
declare
    v_me public.sales := public.hub_begin('update_overview', $4);
    v_id bigint;
    v_kind text;
    v_body text;
    v_overview text;
    v_hyp jsonb;
begin
    if $1 is null then
        raise exception 'the interview id is empty';
    end if;
    select i.id, i.kind into v_id, v_kind from public.interviews i where i.id = $1 for update;
    if v_id is null then
        raise exception 'no interview has the id %', $1;
    end if;
    v_overview := public.hub_block($2, 'overview', 100000, true);
    if $3 is not null then
        v_hyp := public.hub_check_hypotheses($3);
    end if;
    select t.body into v_body from public.interview_transcripts t where t.interview_id = v_id;
    perform public.hub_check_overview(v_kind, v_overview, coalesce(v_body, ''));

    update public.interviews i set overview = v_overview where i.id = v_id;
    if v_hyp is not null then
        delete from public.interview_hypotheses h where h.interview_id = v_id;
        insert into public.interview_hypotheses (interview_id, hypothesis, stance, why)
        select v_id, e ->> 'hypothesis', e ->> 'stance', e ->> 'why'
        from jsonb_array_elements(v_hyp) e;
    end if;

    perform public.hub_end();
    return jsonb_build_object(
        'interview_id', v_id,
        'hypotheses', (select count(*) from public.interview_hypotheses h where h.interview_id = v_id));
end;
$$;

-- ----------------------------------------------------------- submit_recording
drop function public.submit_recording(text, text, text, date, text[], text, text, boolean, jsonb, integer, text);
create function public.submit_recording(
        granola_id text,
        source text,
        title text,
        recorded_on date,
        attendee_emails text[] default null,
        overview text default null,
        transcript text default null,
        consent_to_record boolean default null,
        hypotheses jsonb default null,
        reported_chars integer default null,
        via text default 'ui',
        kind text default 'transcript')
    returns jsonb
    language plpgsql security definer
    set search_path to ''
    as $$
declare
    v_me public.sales := public.hub_begin('submit_recording', $11);
    v_kind text := public.hub_kind($12);
    v_gid text := public.hub_line($1, 'granola_id', 300, false);
    v_title text := public.hub_line($3, 'title', 300, true);
    v_day date := public.hub_day($4, 'recorded_on date');
    v_attendees text[] := public.hub_addresses($5);
    v_overview text := public.hub_block($6, 'overview', 100000, true);
    v_source text := public.hub_check_text(v_kind, $2, $7, $10);
    v_hyp jsonb := public.hub_check_hypotheses($9);
    v_on_file text;
    v_outside text[];
    v_people bigint[];
    v_reason text;
    v_p public.contacts;
    v_id bigint;
    v_suggested bigint[];
begin
    perform public.hub_check_overview(v_kind, v_overview, $7);
    if v_gid is not null then
        v_on_file := public.hub_recording_on_file(v_gid, null);
        if v_on_file is not null then
            raise exception '%', v_on_file;
        end if;
    end if;

    v_outside := public.hub_outside_addresses(v_attendees);
    if cardinality(v_outside) = 0 then
        v_reason := 'no attendee outside the team';
    else
        select coalesce(array_agg(c.id order by c.id), '{}') into v_people
        from public.contacts c
        where public.hub_person_emails(c.contact_key, c.email_jsonb) && v_outside;
        if cardinality(v_people) = 0 then
            v_reason := 'no person matches an attendee';
        elsif cardinality(v_people) > 1 then
            v_reason := pg_catalog.format('%s people match an attendee', cardinality(v_people));
        elsif $8 is not true then
            v_reason := 'consent not confirmed';
        end if;
    end if;

    if v_reason is null then
        -- exactly one person, and consent: this is an interview
        select c.* into v_p from public.contacts c where c.id = v_people[1] for update;
        v_id := public.hub_write_interview(v_p.id, v_day, v_me.id, v_me.id, v_source, v_gid,
                                           v_title, v_overview, $7, $10, v_hyp, v_kind);
        perform public.hub_end();
        return jsonb_build_object('result', 'saved', 'interview_id', v_id, 'person_code', v_p.person_code,
                                  'kind', v_kind);
    end if;

    select coalesce(array_agg(g.contact_id order by g.ord), '{}') into v_suggested
    from public.hub_suggestions(v_attendees, v_title) g;
    insert into public.call_inbox (granola_id, source, title, recorded_on, attendee_emails, overview,
                                   transcript, reported_chars, consent_to_record, submitted_by,
                                   suggested_contact_ids, state, reason, hypotheses, kind)
    values (v_gid, v_source, v_title, v_day, v_attendees, v_overview,
            $7, $10, $8, v_me.id,
            v_suggested, 'waiting', v_reason, v_hyp, v_kind)
    returning id into v_id;
    perform public.hub_end();
    return jsonb_build_object('result', 'inbox', 'inbox_id', v_id, 'reason', v_reason, 'kind', v_kind);
end;
$$;

-- ---------------------------------------------------------- confirm_recording
-- kind null keeps the kind the recording was sent with; a kind given is the
-- teammate saying what it is (a Granola debrief is confirmed as debrief).
drop function public.confirm_recording(bigint, text, boolean, text);
create function public.confirm_recording(
        inbox_id bigint,
        person_code text,
        consent_to_record boolean default null,
        via text default 'ui',
        kind text default null)
    returns jsonb
    language plpgsql security definer
    set search_path to ''
    as $$
declare
    v_me public.sales := public.hub_begin('confirm_recording', $4);
    v_kind text := case when $5 is null then null else public.hub_kind($5) end;
    v_item public.call_inbox;
    v_p public.contacts;
    v_title text;
    v_overview text;
    v_source text;
    v_hyp jsonb;
    v_on_file text;
    v_id bigint;
begin
    if $1 is null then
        raise exception 'the inbox id is empty';
    end if;
    -- the item is locked, so two confirms at once happen one after the other
    select b.* into v_item from public.call_inbox b where b.id = $1 for update;
    if not found then
        raise exception 'no inbox item has the id %', $1;
    end if;
    if v_item.state = 'confirmed' then
        raise exception 'already confirmed by % as interview %',
            coalesce((select s.handle from public.sales s where s.id = v_item.resolved_by), '?'),
            coalesce(v_item.interview_id::text, '?');
    end if;
    v_kind := coalesce(v_kind, v_item.kind);
    if $3 is not true then
        raise exception '%', public.hub_consent_refusal(v_kind);
    end if;
    if v_item.granola_id is not null then
        perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('hub.recording.' || v_item.granola_id, 0));
    end if;
    v_p := public.hub_person($2);

    -- the same checks as save_interview
    v_title := public.hub_line(v_item.title, 'title', 300, true);
    v_overview := public.hub_block(v_item.overview, 'overview', 100000, true);
    v_source := public.hub_check_text(v_kind, v_item.source, v_item.transcript, v_item.reported_chars);
    v_hyp := public.hub_check_hypotheses(v_item.hypotheses);
    perform public.hub_check_overview(v_kind, v_overview, v_item.transcript);
    if v_item.granola_id is not null then
        v_on_file := public.hub_recording_on_file(v_item.granola_id, v_item.id);
        if v_on_file is not null then
            raise exception '%', v_on_file;
        end if;
    end if;

    v_id := public.hub_write_interview(v_p.id, v_item.recorded_on, v_me.id, v_me.id, v_source,
                                       v_item.granola_id, v_title, v_overview, v_item.transcript,
                                       v_item.reported_chars, v_hyp, v_kind);
    update public.call_inbox b
    set state = 'confirmed',
        consent_to_record = true,
        kind = v_kind,
        interview_id = v_id,
        resolved_by = v_me.id,
        resolved_at = now()
    where b.id = v_item.id;

    perform public.hub_end();
    return jsonb_build_object('inbox_id', v_item.id, 'interview_id', v_id, 'person_code', v_p.person_code,
                              'kind', v_kind);
end;
$$;

-- ---------------------------------------------------------------- who may call
revoke all on function public.hub_kind(text) from public, anon, authenticated, service_role;
revoke all on function public.hub_consent_refusal(text) from public, anon, authenticated, service_role;
revoke all on function public.hub_check_text(text, text, text, integer) from public, anon, authenticated, service_role;
revoke all on function public.hub_check_overview(text, text, text) from public, anon, authenticated, service_role;
revoke all on function public.hub_write_interview(bigint, date, bigint, bigint, text, text, text, text, text, integer, jsonb, text) from public, anon, authenticated, service_role;

revoke all on function public.save_interview(text, date, text, text, text, boolean, text, text, text, jsonb, integer, text, text) from public, anon, authenticated, service_role;
revoke all on function public.submit_recording(text, text, text, date, text[], text, text, boolean, jsonb, integer, text, text) from public, anon, authenticated, service_role;
revoke all on function public.confirm_recording(bigint, text, boolean, text, text) from public, anon, authenticated, service_role;

grant execute on function public.save_interview(text, date, text, text, text, boolean, text, text, text, jsonb, integer, text, text) to authenticated;
grant execute on function public.submit_recording(text, text, text, date, text[], text, text, boolean, jsonb, integer, text, text) to authenticated;
grant execute on function public.confirm_recording(bigint, text, boolean, text, text) to authenticated;

-- A revoke or a drop that changes nothing is silent (docs/FINDINGS.md, issue
-- 35): ask. One function of each name, the three actions callable by a signed
-- in teammate alone, and every interview on file a transcript.
do $$
declare
    v_name text;
    v_role text;
begin
    foreach v_name in array array['save_interview', 'submit_recording', 'confirm_recording', 'update_overview',
                                  'hub_write_interview', 'hub_kind', 'hub_consent_refusal', 'hub_check_text',
                                  'hub_check_overview'] loop
        if (select count(*) from pg_catalog.pg_proc p
            where p.pronamespace = 'public'::regnamespace and p.proname = v_name) <> 1 then
            raise exception 'there is not exactly one function public.% after this migration', v_name;
        end if;
        foreach v_role in array array['anon', 'hub_export'] loop
            if exists (select 1 from pg_catalog.pg_roles where rolname = v_role)
                and exists (select 1 from pg_catalog.pg_proc p
                            where p.pronamespace = 'public'::regnamespace and p.proname = v_name
                                and pg_catalog.has_function_privilege(v_role, p.oid, 'EXECUTE')) then
                raise exception '% can call public.%', v_role, v_name;
            end if;
        end loop;
    end loop;
    if exists (select 1 from public.interviews where kind <> 'transcript')
        or exists (select 1 from public.interview_transcripts where kind <> 'transcript')
        or exists (select 1 from public.call_inbox where kind <> 'transcript') then
        raise exception 'a row already on file did not become kind transcript';
    end if;
end $$;

-- =============================================================== 20261124200000_hub_add_with_touches.sql
-- team hub, issue 65: a new person and their first touches in one call, all
-- or nothing. Ours, not upstream's. Undo: reverts/ (same file name).
--
-- add_person_with_touches(person jsonb, touches jsonb, request_id uuid, via)
-- calls add_person, then log_touch once for each touch, inside the one
-- function call: a refusal anywhere rolls back everything, so the hub never
-- holds a person with half a history. It calls the two actions, it does not
-- copy them, so their checks, their audit rows (action add_person and
-- log_touch, via as given) and their refusals stay exactly theirs.
--
-- Named without the hub_ prefix, like the other actions a teammate may call:
-- in this schema hub_... means a shared part closed to every API role.
--
-- A request id makes a retry safe after "not known whether this was saved":
-- the first call that succeeds keeps its result in log_requests, against the
-- caller and a hash of the person and touches. The same id again from the
-- same caller with the same body returns that result and writes nothing;
-- with anything else it is refused. A refused call keeps nothing, so it can
-- be fixed and sent again with the same id. log_requests holds no text of
-- the request, only its hash, and is closed to every API role.

create table public.log_requests (
    request_id uuid primary key,
    sales_id bigint not null references public.sales (id),
    body_sha256 text not null,
    result jsonb not null,
    created_at timestamp with time zone not null default now()
);

alter table public.log_requests enable row level security;
revoke all on table public.log_requests from public, anon, authenticated, service_role;

create function public.add_person_with_touches(
        person jsonb,
        touches jsonb,
        request_id uuid default null,
        via text default 'ui')
    returns jsonb
    language plpgsql security definer
    set search_path to ''
    as $$
declare
    v_me public.sales := public.hub_begin('add_person_with_touches', $4);
    v_person_keys constant text[] := array['name', 'role', 'organization', 'contact', 'referred_by', 'owner', 'quote_by_name'];
    v_touch_keys constant text[] := array['channel', 'what', 'date', 'by', 'next', 'due', 'status'];
    v_hash text;
    v_done public.log_requests;
    v_bad text;
    v_n integer;
    v_t jsonb;
    v_i bigint;
    v_contacts text[];
    v_added jsonb;
    v_touch jsonb;
    v_ids jsonb := '[]'::jsonb;
    v_status text;
    v_result jsonb;
begin
    -- ------------------------------------------------ the same request again
    if $3 is not null then
        v_hash := encode(pg_catalog.sha256(convert_to(jsonb_build_array($1, $2)::text, 'UTF8')), 'hex');
        perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('hub.log_requests.' || $3::text, 0));
        select * into v_done from public.log_requests r where r.request_id = $3;
        if found then
            if v_done.sales_id <> v_me.id or v_done.body_sha256 <> v_hash then
                raise exception 'request id already used for something else: make a new one for a new log';
            end if;
            perform public.hub_end();
            return v_done.result || jsonb_build_object('repeat', true);
        end if;
    end if;

    -- ------------------------------------------------------------ the person
    if $1 is null or jsonb_typeof($1) <> 'object' then
        raise exception 'person must be an object with at least a name';
    end if;
    select string_agg(format('''%s''', left(k, 40)), ', ' order by k) into v_bad
    from jsonb_object_keys($1) k where k <> all (v_person_keys);
    if v_bad is not null then
        raise exception 'person: unknown key %: use name, role, organization, contact, referred_by, owner or quote_by_name', v_bad;
    end if;
    select string_agg(k, ', ' order by k) into v_bad
    from jsonb_each($1) e(k, v)
    where k in ('name', 'role', 'organization', 'referred_by', 'owner') and jsonb_typeof(v) not in ('string', 'null');
    if v_bad is not null then
        raise exception 'person: % must be text', v_bad;
    end if;
    if jsonb_typeof($1 -> 'quote_by_name') not in ('boolean', 'null') then
        raise exception 'person: quote_by_name must be true or false';
    end if;
    case jsonb_typeof($1 -> 'contact')
        when 'string' then
            v_contacts := array[$1 ->> 'contact'];
        when 'array' then
            if exists (select 1 from jsonb_array_elements($1 -> 'contact') c where jsonb_typeof(c) <> 'string') then
                raise exception 'person: contact must be a list of text';
            end if;
            v_contacts := array(select jsonb_array_elements_text($1 -> 'contact'));
        when 'null' then
            v_contacts := null;
        else
            if $1 ? 'contact' then
                raise exception 'person: contact must be a list of text';
            end if;
    end case;

    -- ----------------------------------------------------------- the touches
    if $2 is null or jsonb_typeof($2) <> 'array' then
        raise exception 'touches must be a list of 1 to 20 touches';
    end if;
    v_n := jsonb_array_length($2);
    if v_n < 1 or v_n > 20 then
        raise exception 'touches: give 1 to 20 touches, not %', v_n;
    end if;
    for v_t, v_i in select e.t, e.i from jsonb_array_elements($2) with ordinality e(t, i) order by e.i loop
        if jsonb_typeof(v_t) <> 'object' then
            raise exception 'touch %: must be an object with at least a channel and what', v_i;
        end if;
        select string_agg(format('''%s''', left(k, 40)), ', ' order by k) into v_bad
        from jsonb_object_keys(v_t) k where k <> all (v_touch_keys);
        if v_bad is not null then
            raise exception 'touch %: unknown key %: use channel, what, date, by, next, due or status', v_i, v_bad;
        end if;
        select string_agg(k, ', ' order by k) into v_bad
        from jsonb_each(v_t) e(k, v) where jsonb_typeof(v) not in ('string', 'null');
        if v_bad is not null then
            raise exception 'touch %: % must be text', v_i, v_bad;
        end if;
        foreach v_bad in array array['date', 'due'] loop
            if v_t ->> v_bad is not null then
                begin
                    if v_t ->> v_bad !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then
                        raise exception using errcode = '22007';
                    end if;
                    perform (v_t ->> v_bad)::date;
                exception when others then
                    raise exception 'touch %: % must be a date as YYYY-MM-DD, not ''%''', v_i, v_bad, left(v_t ->> v_bad, 40);
                end;
            end if;
        end loop;
    end loop;

    -- ------------------------------------------------- the writes, all or none
    v_added := public.add_person($1 ->> 'name', $1 ->> 'owner', $1 ->> 'role', $1 ->> 'organization', null,
                                 $1 ->> 'referred_by', ($1 ->> 'quote_by_name')::boolean, $4, v_contacts);
    v_status := v_added ->> 'status';

    -- in date order (no date means now, so last), then in the order given
    for v_t, v_i in
        select e.t, e.i from jsonb_array_elements($2) with ordinality e(t, i)
        order by (e.t ->> 'date')::date nulls last, e.i
    loop
        begin
            v_touch := public.log_touch(v_added ->> 'person_code', v_t ->> 'by', (v_t ->> 'date')::date,
                                        v_t ->> 'channel', v_t ->> 'what', v_t ->> 'next', (v_t ->> 'due')::date,
                                        v_t ->> 'status', $4);
        exception when others then
            raise exception using errcode = sqlstate, message = format('touch %s: %s', v_i, sqlerrm);
        end;
        v_ids := v_ids || to_jsonb((v_touch ->> 'touch_id')::bigint);
        v_status := v_touch ->> 'status';
    end loop;

    v_result := jsonb_build_object(
        'person_code', v_added ->> 'person_code',
        'slug', v_added ->> 'slug',
        'name', v_added ->> 'name',
        'owner', v_added ->> 'owner',
        'status', v_status,
        'touches', jsonb_array_length(v_ids),
        'touch_ids', v_ids,
        'request_id', $3);
    if $3 is not null then
        insert into public.log_requests (request_id, sales_id, body_sha256, result)
        values ($3, v_me.id, v_hash, v_result);
    end if;
    perform public.hub_end();
    return v_result;
end;
$$;

revoke all on function public.add_person_with_touches(jsonb, jsonb, uuid, text) from public, anon, authenticated, service_role;
grant execute on function public.add_person_with_touches(jsonb, jsonb, uuid, text) to authenticated;

-- =============================================================== 20261125100000_hub_library.sql
-- team hub, issue 95: the library (hypotheses, research, competition,
-- diagrams) inside the hub. Ours, not upstream's. Undo: reverts/ (same file
-- name).
--
-- The markdown files in the repo stay the source; the team edits them there.
-- scripts/sync_library.py copies them here on every push to main that
-- changes them (.github/workflows/library.yml). The site's built files can be
-- downloaded by anyone who knows the address, so private research is never
-- baked into the build: it lives here, behind row security, and only a
-- signed in, switched on teammate can read it.
--
-- library_pages: one row per file, known by its path. Teammates read it;
-- nobody writes it directly, not even a teammate.
--
-- library_sync(pages jsonb) replaces the whole set in one transaction:
-- every page given is added or updated, every page whose file is gone is
-- removed. Any bad page refuses the whole call and nothing changes. An empty
-- list is refused, so a broken walk can never empty the library. Only the
-- database owner (the role the migrate job connects as) may call it; it is
-- closed to anon, authenticated and service_role.

create table public.library_pages (
    path text primary key,
    section text not null,
    title text not null,
    body text not null,
    commit text not null,
    updated_at timestamp with time zone not null default now(),
    constraint library_pages_section_known
        check (section in ('hypotheses', 'research', 'competition', 'diagrams')),
    constraint library_pages_path_in_section
        check (split_part(path, '/', 1) = section
               and path ~ '^[a-z]+(/[^/]+)+\.md$'
               and path !~ '(^|/)\.\.?(/|$)'
               and length(path) <= 300),
    constraint library_pages_title_size check (length(btrim(title)) between 1 and 300),
    constraint library_pages_body_size check (length(body) <= 1000000),
    constraint library_pages_commit_sha check (commit ~ '^[0-9a-f]{40}$')
);

alter table public.library_pages enable row level security;

-- A teammate reads while their sales row says they are switched on. A
-- sign-in with no sales row behind it, or a switched off one, reads nothing.
create policy "Enable read access for switched on teammates" on public.library_pages
    for select to authenticated
    using (exists (select 1 from public.sales s
                   where s.user_id = (select auth.uid()) and not s.disabled));

revoke all on table public.library_pages from public, anon, authenticated, service_role;
grant select on table public.library_pages to authenticated;

create function public.library_sync(pages jsonb)
    returns jsonb
    language plpgsql
    set search_path to ''
    as $$
declare
    v_keys constant text[] := array['path', 'section', 'title', 'body', 'commit'];
    v_sections constant text[] := array['hypotheses', 'research', 'competition', 'diagrams'];
    v_page jsonb;
    v_i bigint;
    v_bad text;
    v_n integer;
    v_added integer;
    v_changed integer;
    v_removed integer;
begin
    if $1 is null or jsonb_typeof($1) <> 'array' then
        raise exception 'pages must be a list of pages';
    end if;
    v_n := jsonb_array_length($1);
    if v_n = 0 then
        raise exception 'pages is empty: a sync never empties the whole library';
    end if;
    if v_n > 5000 then
        raise exception 'pages is too long: % pages, the limit is 5000', v_n;
    end if;

    for v_page, v_i in select e.p, e.i from jsonb_array_elements($1) with ordinality e(p, i) order by e.i loop
        if jsonb_typeof(v_page) <> 'object' then
            raise exception 'page %: must be an object with path, section, title, body and commit', v_i;
        end if;
        select string_agg(left(k, 40), ', ' order by k) into v_bad
        from jsonb_object_keys(v_page) k where k <> all (v_keys);
        if v_bad is not null then
            raise exception 'page %: unknown key %: use path, section, title, body and commit', v_i, v_bad;
        end if;
        select string_agg(k, ', ' order by o) into v_bad
        from unnest(v_keys) with ordinality u(k, o) where not v_page ? k;
        if v_bad is not null then
            raise exception 'page %: missing %', v_i, v_bad;
        end if;
        select string_agg(k, ', ' order by o) into v_bad
        from unnest(v_keys) with ordinality u(k, o) where jsonb_typeof(v_page -> k) <> 'string';
        if v_bad is not null then
            raise exception 'page %: % must be text', v_i, v_bad;
        end if;
        if not (v_page ->> 'section') = any (v_sections) then
            raise exception 'page %: section % is not one of hypotheses, research, competition, diagrams',
                v_i, left(v_page ->> 'section', 40);
        end if;
        if split_part(v_page ->> 'path', '/', 1) <> v_page ->> 'section'
            or (v_page ->> 'path') !~ '^[a-z]+(/[^/]+)+\.md$'
            or (v_page ->> 'path') ~ '(^|/)\.\.?(/|$)'
            or length(v_page ->> 'path') > 300 then
            raise exception 'page %: the path % is not a .md file under %/',
                v_i, left(v_page ->> 'path', 300), v_page ->> 'section';
        end if;
        if (v_page ->> 'commit') !~ '^[0-9a-f]{40}$' then
            raise exception 'page %: commit must be a full git sha (40 lowercase hex characters)', v_i;
        end if;
        if btrim(v_page ->> 'title') = '' then
            raise exception 'page %: the title is empty', v_i;
        end if;
        if length(v_page ->> 'title') > 300 then
            raise exception 'page %: the title is too long: % characters, the limit is 300',
                v_i, length(v_page ->> 'title');
        end if;
        if length(v_page ->> 'body') > 1000000 then
            raise exception 'page %: the body is too long: % characters, the limit is 1000000',
                v_i, length(v_page ->> 'body');
        end if;
    end loop;

    select min(p ->> 'path') into v_bad
    from jsonb_array_elements($1) p
    group by p ->> 'path' having count(*) > 1
    order by 1 limit 1;
    if v_bad is not null then
        raise exception 'the path % is given twice', v_bad;
    end if;

    -- One sync at a time: two pushes close together run one after the
    -- other, and the later one's set is what stays.
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('hub.library_sync', 0));

    select count(*) filter (where l.path is null),
           count(*) filter (where l.path is not null
                            and (l.section, l.title, l.body) is distinct from
                                (p ->> 'section', p ->> 'title', p ->> 'body'))
        into v_added, v_changed
    from jsonb_array_elements($1) p
        left join public.library_pages l on l.path = p ->> 'path';

    insert into public.library_pages as l (path, section, title, body, commit)
    select p ->> 'path', p ->> 'section', p ->> 'title', p ->> 'body', p ->> 'commit'
    from jsonb_array_elements($1) p
    on conflict (path) do update
        set section = excluded.section,
            title = excluded.title,
            body = excluded.body,
            commit = excluded.commit,
            updated_at = case
                when (l.section, l.title, l.body) is distinct from (excluded.section, excluded.title, excluded.body)
                then now() else l.updated_at end;

    delete from public.library_pages l
    where not exists (select 1 from jsonb_array_elements($1) p where p ->> 'path' = l.path);
    get diagnostics v_removed = row_count;

    return jsonb_build_object('pages', v_n, 'added', v_added, 'changed', v_changed, 'removed', v_removed);
end;
$$;

revoke all on function public.library_sync(jsonb) from public, anon, authenticated, service_role;

-- =============================================================== 20261125120000_hub_stakeholder_category.sql
-- team hub, issue 97: every person has one stakeholder category, and the
-- team sees per category how many people it has interviewed, scheduled and
-- contacted. Ours, not upstream's. Undo: reverts/ (same file name).
--
-- What changes:
-- - contacts gains category text, null for uncategorized. A check holds it to
--   the categories table, which team.json fills.
-- - hub_category reads one category: null or blank is null, anything not in
--   the categories table is refused in one plain line, never a constraint name.
-- - add_person and update_person take category text (new, last); in
--   update_person an empty category clears it. add_person_with_touches (the
--   log JSON) takes a category key in person. The three are dropped and made
--   again with the same grants.
-- - contacts_summary gains category at its end, replaced in place.
-- - category_tally, a view: per category (and uncategorized, and total), the
--   people with status interviewed, with status scheduled, and contacted or
--   later (contacted, replied, scheduled, interviewed). It counts people, so a
--   person with two interviews counts once; declined and do-not-contact are
--   not contacted or later. It reads contacts as the caller.

alter table public.contacts
    add column category text;

-- The categories: loaded from team.json by `python3 scripts/team.py sql`.
create table public.categories (
    value text primary key check (value ~ '^[a-z][a-z0-9-]{0,40}$'),
    label text not null,
    position integer not null default 0
);

alter table public.categories enable row level security;
revoke all on table public.categories from public, anon, authenticated;
grant select on table public.categories to authenticated, service_role;
create policy categories_read on public.categories
    for select to authenticated using (true);

alter table public.contacts
    add constraint contacts_category_known
        foreign key (category) references public.categories (value);

-- ---------------------------------------------------------------- shared part
create function public.hub_category(category text) returns text
    language plpgsql stable
    set search_path to ''
    as $$
begin
    if $1 is null or btrim($1) = '' then
        return null;
    end if;
    if not exists (select 1 from public.categories c where c.value = btrim($1)) then
        raise exception 'category must be one of: % (not ''%'')',
            (select string_agg(c.value, ', ' order by c.position, c.value) from public.categories c),
            left($1, 40);
    end if;
    return btrim($1);
end;
$$;

revoke all on function public.hub_category(text) from public, anon, authenticated, service_role;

-- The person page and the people list read this view: it gains category at
-- its end, so it is replaced in place and keeps its grants.
create or replace view public.contacts_summary with (security_invoker = on) as
select
    co.id,
    co.first_name,
    co.last_name,
    co.gender,
    co.title,
    co.background,
    co.avatar,
    co.first_seen,
    co.last_seen,
    co.has_newsletter,
    co.status,
    co.tags,
    co.company_id,
    co.sales_id,
    co.linkedin_url,
    co.email_jsonb,
    co.phone_jsonb,
    (jsonb_path_query_array(co.email_jsonb, '$[*]."email"'))::text as email_fts,
    (jsonb_path_query_array(co.phone_jsonb, '$[*]."number"'))::text as phone_fts,
    c.name as company_name,
    count(distinct t.id) filter (where t.done_date is null) as nb_tasks,
    co.person_code,
    co.slug,
    co.name_key,
    co.quote_by_name,
    co.contact_key,
    co.referred_by,
    co.referred_by_contact_id,
    co.links,
    co.category
from public.contacts co
    left join public.tasks t on co.id = t.contact_id
    left join public.companies c on co.company_id = c.id
group by co.id, c.name;

-- ---------------------------------------------------------------- add_person
drop function public.add_person(text, text, text, text, text, text, boolean, text, text[]);

create function public.add_person(
        name text,
        owner text default null,
        role text default null,
        organization text default null,
        contact text default null,
        referred_by text default null,
        quote_by_name boolean default null,
        via text default 'ui',
        contacts text[] default null,
        category text default null)
    returns jsonb
    language plpgsql security definer
    set search_path to ''
    as $$
declare
    v_me public.sales := public.hub_begin('add_person', $8);
    v_name text := public.hub_line($1, 'name', 200, true);
    v_owner public.sales := public.hub_teammate($2, 'owner', v_me);
    v_role text := public.hub_line($3, 'role', 300, false);
    v_org text := public.hub_line($4, 'organization', 300, false);
    v_details jsonb := public.hub_sort_contact_details(array[$5] || coalesce($9, '{}'::text[]));
    v_referred text := public.hub_line($6, 'referred by', 300, false);
    v_category text := public.hub_category($10);
    v_key text;
    v_other bigint;
    v_cut integer;
    v_first text;
    v_last text;
    v_company bigint;
    v_p public.contacts;
    v_new public.contacts;
begin
    v_key := public.hub_name_key(v_name);
    if v_key = '' then
        raise exception '''%'' is only a title or punctuation, not a name', v_name;
    end if;
    if v_key !~ '[^0-9 ]' then
        raise exception '''%'' is only a number, not a name', v_name;
    end if;

    -- One person is added at a time (the same lock the insert takes), so two
    -- teammates adding one person, or one detail, at once get one person and
    -- one refusal.
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('hub.contacts.identity', 0));
    select c.id into v_other from public.contacts c where c.name_key = v_key limit 1;
    if v_other is not null then
        raise exception 'already on file (same name): %', public.hub_describe_person(v_other);
    end if;
    v_p.email_jsonb := '[]'::jsonb;
    v_p.phone_jsonb := '[]'::jsonb;
    v_p.links := '{}';
    v_p := public.hub_file_contact_details(v_p, v_details);

    -- the full name splits at its last space
    v_cut := char_length(v_name) - position(' ' in reverse(v_name)) + 1;
    if position(' ' in v_name) = 0 then
        v_first := v_name;
        v_last := '';
    else
        v_first := btrim(left(v_name, v_cut - 1));
        v_last := substr(v_name, v_cut + 1);
    end if;

    if v_org is not null then
        v_company := public.hub_company(v_org, v_me.id);
    end if;

    insert into public.contacts (first_name, last_name, title, company_id, sales_id, status, contact_key,
                                 referred_by, quote_by_name, first_seen, last_seen, tags,
                                 email_jsonb, phone_jsonb, linkedin_url, links, category)
    values (v_first, v_last, v_role, v_company, v_owner.id, 'to-contact', v_details -> 0 ->> 'value',
            v_referred, coalesce($7, false), now(), now(), '{}',
            v_p.email_jsonb, v_p.phone_jsonb, v_p.linkedin_url, v_p.links, v_category)
    returning * into v_new;

    perform public.hub_end();
    return jsonb_build_object(
        'person_code', v_new.person_code,
        'slug', v_new.slug,
        'name', v_name,
        'owner', v_owner.handle,
        'status', v_new.status);
end;
$$;

-- -------------------------------------------------------------- update_person
drop function public.update_person(text, text, text, text, text, boolean, text, text, text[]);

create function public.update_person(
        person_code text,
        role text default null,
        organization text default null,
        contact text default null,
        referred_by text default null,
        quote_by_name boolean default null,
        notes text default null,
        via text default 'ui',
        contacts text[] default null,
        category text default null)
    returns jsonb
    language plpgsql security definer
    set search_path to ''
    as $$
declare
    v_me public.sales := public.hub_begin('update_person', $8);
    v_p public.contacts := public.hub_person($1);
    v_role text := public.hub_line($2, 'role', 300, false);
    v_org text := public.hub_line($3, 'organization', 300, false);
    v_contact jsonb := public.hub_sort_contact_details(array[$4]);
    v_details jsonb := public.hub_sort_contact_details($9);
    v_referred text := public.hub_line($5, 'referred by', 300, false);
    v_notes text := public.hub_block($7, 'notes', 10000, false);
    v_category text := public.hub_category($10);
    v_before public.contacts;
    v_changed text[] := '{}';
begin
    if $2 is null and $3 is null and $4 is null and $5 is null and $6 is null and $7 is null
        and coalesce(cardinality($9), 0) = 0 and $10 is null then
        raise exception 'nothing to change: give at least one of role, organization, contact, referred_by, quote_by_name, notes, category';
    end if;

    if $2 is not null then
        v_p.title := v_role;
        v_changed := v_changed || 'role'::text;
    end if;
    if $3 is not null then
        v_p.company_id := case when v_org is null then null else public.hub_company(v_org, v_me.id) end;
        v_changed := v_changed || 'organization'::text;
    end if;
    if $4 is not null or jsonb_array_length(v_details) > 0 then
        perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('hub.contacts.identity', 0));
    end if;
    -- The one contact, as before: it becomes the contact key (an empty one
    -- clears it) and is filed under its kind.
    if $4 is not null then
        if jsonb_array_length(v_contact) = 0 then
            v_p.contact_key := null;
        else
            v_p := public.hub_file_contact_details(v_p, v_contact);
            v_p.contact_key := lower(v_contact -> 0 ->> 'value');
        end if;
        v_changed := v_changed || 'contact'::text;
    end if;
    -- The list: added, never replacing.
    if jsonb_array_length(v_details) > 0 then
        v_before := v_p;
        v_p := public.hub_file_contact_details(v_p, v_details);
        if v_p.contact_key is null then
            v_p.contact_key := lower(v_details -> 0 ->> 'value');
        end if;
        if (v_p.email_jsonb, v_p.phone_jsonb, v_p.linkedin_url, v_p.links, v_p.contact_key)
            is distinct from (v_before.email_jsonb, v_before.phone_jsonb, v_before.linkedin_url, v_before.links,
                              v_before.contact_key)
            and not 'contact' = any(v_changed) then
            v_changed := v_changed || 'contact'::text;
        end if;
    end if;
    if $5 is not null then
        v_p.referred_by := v_referred;
        v_changed := v_changed || 'referred_by'::text;
    end if;
    if $6 is not null then
        v_p.quote_by_name := $6;
        v_changed := v_changed || 'quote_by_name'::text;
    end if;
    if $7 is not null then
        v_p.background := v_notes;
        v_changed := v_changed || 'notes'::text;
    end if;
    -- an empty category clears it, so a person can go back to uncategorized
    if $10 is not null and v_category is distinct from v_p.category then
        v_p.category := v_category;
        v_changed := v_changed || 'category'::text;
    end if;

    if cardinality(v_changed) > 0 then
        update public.contacts c
        set title = v_p.title,
            company_id = v_p.company_id,
            contact_key = v_p.contact_key,
            email_jsonb = v_p.email_jsonb,
            phone_jsonb = v_p.phone_jsonb,
            linkedin_url = v_p.linkedin_url,
            links = v_p.links,
            referred_by = v_p.referred_by,
            quote_by_name = v_p.quote_by_name,
            background = v_p.background,
            category = v_p.category
        where c.id = v_p.id;
    end if;

    perform public.hub_end();
    return jsonb_build_object('person_code', v_p.person_code, 'changed', to_jsonb(v_changed));
end;
$$;

-- ---------------------------------------------------- add_person_with_touches
drop function public.add_person_with_touches(jsonb, jsonb, uuid, text);

create function public.add_person_with_touches(
        person jsonb,
        touches jsonb,
        request_id uuid default null,
        via text default 'ui')
    returns jsonb
    language plpgsql security definer
    set search_path to ''
    as $$
declare
    v_me public.sales := public.hub_begin('add_person_with_touches', $4);
    v_person_keys constant text[] := array['name', 'role', 'organization', 'contact', 'referred_by', 'owner', 'quote_by_name', 'category'];
    v_touch_keys constant text[] := array['channel', 'what', 'date', 'by', 'next', 'due', 'status'];
    v_hash text;
    v_done public.log_requests;
    v_bad text;
    v_n integer;
    v_t jsonb;
    v_i bigint;
    v_contacts text[];
    v_added jsonb;
    v_touch jsonb;
    v_ids jsonb := '[]'::jsonb;
    v_status text;
    v_result jsonb;
begin
    -- ------------------------------------------------ the same request again
    if $3 is not null then
        v_hash := encode(pg_catalog.sha256(convert_to(jsonb_build_array($1, $2)::text, 'UTF8')), 'hex');
        perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('hub.log_requests.' || $3::text, 0));
        select * into v_done from public.log_requests r where r.request_id = $3;
        if found then
            if v_done.sales_id <> v_me.id or v_done.body_sha256 <> v_hash then
                raise exception 'request id already used for something else: make a new one for a new log';
            end if;
            perform public.hub_end();
            return v_done.result || jsonb_build_object('repeat', true);
        end if;
    end if;

    -- ------------------------------------------------------------ the person
    if $1 is null or jsonb_typeof($1) <> 'object' then
        raise exception 'person must be an object with at least a name';
    end if;
    select string_agg(format('''%s''', left(k, 40)), ', ' order by k) into v_bad
    from jsonb_object_keys($1) k where k <> all (v_person_keys);
    if v_bad is not null then
        raise exception 'person: unknown key %: use name, role, organization, contact, referred_by, owner, quote_by_name or category', v_bad;
    end if;
    select string_agg(k, ', ' order by k) into v_bad
    from jsonb_each($1) e(k, v)
    where k in ('name', 'role', 'organization', 'referred_by', 'owner', 'category') and jsonb_typeof(v) not in ('string', 'null');
    if v_bad is not null then
        raise exception 'person: % must be text', v_bad;
    end if;
    if jsonb_typeof($1 -> 'quote_by_name') not in ('boolean', 'null') then
        raise exception 'person: quote_by_name must be true or false';
    end if;
    case jsonb_typeof($1 -> 'contact')
        when 'string' then
            v_contacts := array[$1 ->> 'contact'];
        when 'array' then
            if exists (select 1 from jsonb_array_elements($1 -> 'contact') c where jsonb_typeof(c) <> 'string') then
                raise exception 'person: contact must be a list of text';
            end if;
            v_contacts := array(select jsonb_array_elements_text($1 -> 'contact'));
        when 'null' then
            v_contacts := null;
        else
            if $1 ? 'contact' then
                raise exception 'person: contact must be a list of text';
            end if;
    end case;

    -- ----------------------------------------------------------- the touches
    if $2 is null or jsonb_typeof($2) <> 'array' then
        raise exception 'touches must be a list of 1 to 20 touches';
    end if;
    v_n := jsonb_array_length($2);
    if v_n < 1 or v_n > 20 then
        raise exception 'touches: give 1 to 20 touches, not %', v_n;
    end if;
    for v_t, v_i in select e.t, e.i from jsonb_array_elements($2) with ordinality e(t, i) order by e.i loop
        if jsonb_typeof(v_t) <> 'object' then
            raise exception 'touch %: must be an object with at least a channel and what', v_i;
        end if;
        select string_agg(format('''%s''', left(k, 40)), ', ' order by k) into v_bad
        from jsonb_object_keys(v_t) k where k <> all (v_touch_keys);
        if v_bad is not null then
            raise exception 'touch %: unknown key %: use channel, what, date, by, next, due or status', v_i, v_bad;
        end if;
        select string_agg(k, ', ' order by k) into v_bad
        from jsonb_each(v_t) e(k, v) where jsonb_typeof(v) not in ('string', 'null');
        if v_bad is not null then
            raise exception 'touch %: % must be text', v_i, v_bad;
        end if;
        foreach v_bad in array array['date', 'due'] loop
            if v_t ->> v_bad is not null then
                begin
                    if v_t ->> v_bad !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then
                        raise exception using errcode = '22007';
                    end if;
                    perform (v_t ->> v_bad)::date;
                exception when others then
                    raise exception 'touch %: % must be a date as YYYY-MM-DD, not ''%''', v_i, v_bad, left(v_t ->> v_bad, 40);
                end;
            end if;
        end loop;
    end loop;

    -- ------------------------------------------------- the writes, all or none
    v_added := public.add_person($1 ->> 'name', $1 ->> 'owner', $1 ->> 'role', $1 ->> 'organization', null,
                                 $1 ->> 'referred_by', ($1 ->> 'quote_by_name')::boolean, $4, v_contacts, $1 ->> 'category');
    v_status := v_added ->> 'status';

    -- in date order (no date means now, so last), then in the order given
    for v_t, v_i in
        select e.t, e.i from jsonb_array_elements($2) with ordinality e(t, i)
        order by (e.t ->> 'date')::date nulls last, e.i
    loop
        begin
            v_touch := public.log_touch(v_added ->> 'person_code', v_t ->> 'by', (v_t ->> 'date')::date,
                                        v_t ->> 'channel', v_t ->> 'what', v_t ->> 'next', (v_t ->> 'due')::date,
                                        v_t ->> 'status', $4);
        exception when others then
            raise exception using errcode = sqlstate, message = format('touch %s: %s', v_i, sqlerrm);
        end;
        v_ids := v_ids || to_jsonb((v_touch ->> 'touch_id')::bigint);
        v_status := v_touch ->> 'status';
    end loop;

    v_result := jsonb_build_object(
        'person_code', v_added ->> 'person_code',
        'slug', v_added ->> 'slug',
        'name', v_added ->> 'name',
        'owner', v_added ->> 'owner',
        'status', v_status,
        'touches', jsonb_array_length(v_ids),
        'touch_ids', v_ids,
        'request_id', $3);
    if $3 is not null then
        insert into public.log_requests (request_id, sales_id, body_sha256, result)
        values ($3, v_me.id, v_hash, v_result);
    end if;
    perform public.hub_end();
    return v_result;
end;
$$;

-- ------------------------------------------------------------- category_tally
create view public.category_tally with (security_invoker = on) as
with categories (id, category) as (
    select (row_number() over (order by c.position, c.value))::integer, c.value
    from public.categories c
    union all
    select 1000000, 'uncategorized'
), counts as (
    select coalesce(co.category, 'uncategorized') as category,
           count(*) filter (where co.status = 'interviewed') as interviewed,
           count(*) filter (where co.status = 'scheduled') as scheduled,
           count(*) filter (where co.status in ('contacted', 'replied', 'scheduled', 'interviewed')) as contacted_or_later
    from public.contacts co
    group by 1
)
select k.id,
       k.category,
       coalesce(n.interviewed, 0)::integer as interviewed,
       coalesce(n.scheduled, 0)::integer as scheduled,
       coalesce(n.contacted_or_later, 0)::integer as contacted_or_later
from categories k
    left join counts n on n.category = k.category
union all
select 1000001,
       'total',
       coalesce(sum(n.interviewed), 0)::integer,
       coalesce(sum(n.scheduled), 0)::integer,
       coalesce(sum(n.contacted_or_later), 0)::integer
from counts n;

revoke all on table public.category_tally from public, anon, authenticated, service_role;
grant select on table public.category_tally to authenticated;
grant select on table public.category_tally to service_role;

-- -------------------------------------------------------------------- grants
revoke all on function public.add_person(text, text, text, text, text, text, boolean, text, text[], text) from public, anon, authenticated, service_role;
revoke all on function public.update_person(text, text, text, text, text, boolean, text, text, text[], text) from public, anon, authenticated, service_role;
revoke all on function public.add_person_with_touches(jsonb, jsonb, uuid, text) from public, anon, authenticated, service_role;

grant execute on function public.add_person(text, text, text, text, text, text, boolean, text, text[], text) to authenticated;
grant execute on function public.update_person(text, text, text, text, text, boolean, text, text, text[], text) to authenticated;
grant execute on function public.add_person_with_touches(jsonb, jsonb, uuid, text) to authenticated;

-- =============================================================== 20261125140000_hub_interview_sessions.sql
-- team hub, issue 98: one conversation captured twice (notes and a
-- recording, or recorded twice) is one interview session. Ours, not
-- upstream's. Undo: reverts/ (same file name).
--
-- What changes:
-- - interviews gains session_of bigint, referencing interviews(id). Null: the
--   interview is its own session (and the primary of any linked to it). Set:
--   the primary of its session. Nothing is merged or deleted: every capture
--   keeps its row and its text.
-- - link_interviews(primary_id, other_id, via) links two interviews of the
--   same person. Each side is followed to its primary first, so there are no
--   chains; the earliest saved (the lowest id) becomes the primary of all.
--   Refused: an interview linked to itself, interviews of different people,
--   an unknown id. Linking two already in one session is a no-op that says
--   "already linked".
-- - hub_same_conversation(contact, day, id): the primary of another interview
--   of the same person on the same day, or null. save_interview and
--   submit_recording (when saved) return it as same_conversation_as, so
--   scripts/hub.py can ask "same conversation?". Each is replaced in place with
--   the same arguments, its body issue 83's (20261124180000_hub_interview_kinds.sql)
--   with that one key added, so its grants stay.
-- - Backfill: interview 3 is linked to interview 2 (Casey Lane, 2026-11-25),
--   only when both are on file, of the same person, on the same day, and 3 is
--   not linked yet. Anywhere else it changes nothing.

-- ------------------------------------------------------------------ the table
alter table public.interviews
    add column session_of bigint references public.interviews (id);
alter table public.interviews
    add constraint interviews_session_not_self check (session_of is null or session_of <> id);
create index interviews_session_of_idx on public.interviews (session_of);

-- ------------------------------------------------------------ shared part
create function public.hub_same_conversation(contact_id bigint, day date, interview_id bigint) returns bigint
    language sql stable
    set search_path to ''
    as $$
    select min(coalesce(i.session_of, i.id))
    from public.interviews i
    where i.contact_id = $1 and i.date = $2 and i.id <> $3
    $$;

-- ------------------------------------------------------------ link_interviews
create function public.link_interviews(
        primary_id bigint,
        other_id bigint,
        via text default 'ui')
    returns jsonb
    language plpgsql security definer
    set search_path to ''
    as $$
declare
    v_me public.sales := public.hub_begin('link_interviews', $3);
    v_a public.interviews;
    v_b public.interviews;
    v_root_a bigint;
    v_root_b bigint;
    v_primary bigint;
    v_moved bigint;
begin
    if $1 is null or $2 is null then
        raise exception 'two interview ids are needed: the primary and the other';
    end if;
    if $1 = $2 then
        raise exception 'an interview cannot be linked to itself';
    end if;
    -- both rows locked, lower id first, so two links at once wait in turn
    perform 1 from public.interviews i where i.id in ($1, $2) order by i.id for update;
    select i.* into v_a from public.interviews i where i.id = $1;
    if not found then
        raise exception 'no interview has the id %', $1;
    end if;
    select i.* into v_b from public.interviews i where i.id = $2;
    if not found then
        raise exception 'no interview has the id %', $2;
    end if;
    if v_a.contact_id <> v_b.contact_id then
        raise exception 'these are interviews of different people';
    end if;
    v_root_a := coalesce(v_a.session_of, v_a.id);
    v_root_b := coalesce(v_b.session_of, v_b.id);
    v_primary := least(v_root_a, v_root_b);
    if v_root_a = v_root_b then
        perform public.hub_end();
        return jsonb_build_object('result', 'already linked', 'primary_id', v_primary, 'interview_id', $2);
    end if;
    v_moved := greatest(v_root_a, v_root_b);
    -- the later session, its primary and every capture in it, joins the earlier
    update public.interviews i set session_of = v_primary
    where i.id = v_moved or i.session_of = v_moved;
    perform public.hub_end();
    return jsonb_build_object('result', 'linked', 'primary_id', v_primary, 'interview_id', $2);
end;
$$;

-- ------------------------------------------------------------- save_interview
create or replace function public.save_interview(
        person_code text,
        date date,
        interviewer text default null,
        source text default null,
        granola_id text default null,
        consent_to_record boolean default null,
        title text default null,
        overview text default null,
        transcript text default null,
        hypotheses jsonb default null,
        reported_chars integer default null,
        via text default 'ui',
        kind text default 'transcript')
    returns jsonb
    language plpgsql security definer
    set search_path to ''
    as $$
declare
    v_me public.sales := public.hub_begin('save_interview', $12);
    v_kind text := public.hub_kind($13);
    v_p public.contacts;
    v_who public.sales;
    v_day date;
    v_gid text;
    v_title text;
    v_overview text;
    v_source text;
    v_hyp jsonb;
    v_on_file text;
    v_id bigint;
begin
    if $6 is not true then
        raise exception '%', public.hub_consent_refusal(v_kind);
    end if;
    v_gid := public.hub_line($5, 'granola_id', 300, false);
    -- locks are always taken in one order: the recording, then the person
    if v_gid is not null then
        perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('hub.recording.' || v_gid, 0));
    end if;
    v_p := public.hub_person($1);
    v_day := public.hub_day($2, 'date');
    v_who := public.hub_teammate($3, 'interviewer', v_me);
    v_title := public.hub_line($7, 'title', 300, true);
    v_overview := public.hub_block($8, 'overview', 100000, true);
    v_source := public.hub_check_text(v_kind, $4, $9, $11);
    v_hyp := public.hub_check_hypotheses($10);
    perform public.hub_check_overview(v_kind, v_overview, $9);
    if v_gid is not null then
        v_on_file := public.hub_recording_on_file(v_gid, null);
        if v_on_file is not null then
            raise exception '%', v_on_file;
        end if;
    end if;

    v_id := public.hub_write_interview(v_p.id, v_day, v_who.id, v_me.id, v_source, v_gid,
                                       v_title, v_overview, $9, $11, v_hyp, v_kind);
    perform public.hub_end();
    return jsonb_build_object(
        'interview_id', v_id,
        'same_conversation_as', public.hub_same_conversation(v_p.id, v_day, v_id),
        'person_code', v_p.person_code,
        'interviewer', v_who.handle,
        'status', 'interviewed',
        'kind', v_kind,
        'chars', char_length($9));
end;
$$;

-- ----------------------------------------------------------- submit_recording
create or replace function public.submit_recording(
        granola_id text,
        source text,
        title text,
        recorded_on date,
        attendee_emails text[] default null,
        overview text default null,
        transcript text default null,
        consent_to_record boolean default null,
        hypotheses jsonb default null,
        reported_chars integer default null,
        via text default 'ui',
        kind text default 'transcript')
    returns jsonb
    language plpgsql security definer
    set search_path to ''
    as $$
declare
    v_me public.sales := public.hub_begin('submit_recording', $11);
    v_kind text := public.hub_kind($12);
    v_gid text := public.hub_line($1, 'granola_id', 300, false);
    v_title text := public.hub_line($3, 'title', 300, true);
    v_day date := public.hub_day($4, 'recorded_on date');
    v_attendees text[] := public.hub_addresses($5);
    v_overview text := public.hub_block($6, 'overview', 100000, true);
    v_source text := public.hub_check_text(v_kind, $2, $7, $10);
    v_hyp jsonb := public.hub_check_hypotheses($9);
    v_on_file text;
    v_outside text[];
    v_people bigint[];
    v_reason text;
    v_p public.contacts;
    v_id bigint;
    v_suggested bigint[];
begin
    perform public.hub_check_overview(v_kind, v_overview, $7);
    if v_gid is not null then
        v_on_file := public.hub_recording_on_file(v_gid, null);
        if v_on_file is not null then
            raise exception '%', v_on_file;
        end if;
    end if;

    v_outside := public.hub_outside_addresses(v_attendees);
    if cardinality(v_outside) = 0 then
        v_reason := 'no attendee outside the team';
    else
        select coalesce(array_agg(c.id order by c.id), '{}') into v_people
        from public.contacts c
        where public.hub_person_emails(c.contact_key, c.email_jsonb) && v_outside;
        if cardinality(v_people) = 0 then
            v_reason := 'no person matches an attendee';
        elsif cardinality(v_people) > 1 then
            v_reason := pg_catalog.format('%s people match an attendee', cardinality(v_people));
        elsif $8 is not true then
            v_reason := 'consent not confirmed';
        end if;
    end if;

    if v_reason is null then
        -- exactly one person, and consent: this is an interview
        select c.* into v_p from public.contacts c where c.id = v_people[1] for update;
        v_id := public.hub_write_interview(v_p.id, v_day, v_me.id, v_me.id, v_source, v_gid,
                                           v_title, v_overview, $7, $10, v_hyp, v_kind);
        perform public.hub_end();
        return jsonb_build_object('result', 'saved', 'interview_id', v_id, 'person_code', v_p.person_code,
                                  'kind', v_kind,
                                  'same_conversation_as', public.hub_same_conversation(v_p.id, v_day, v_id));
    end if;

    select coalesce(array_agg(g.contact_id order by g.ord), '{}') into v_suggested
    from public.hub_suggestions(v_attendees, v_title) g;
    insert into public.call_inbox (granola_id, source, title, recorded_on, attendee_emails, overview,
                                   transcript, reported_chars, consent_to_record, submitted_by,
                                   suggested_contact_ids, state, reason, hypotheses, kind)
    values (v_gid, v_source, v_title, v_day, v_attendees, v_overview,
            $7, $10, $8, v_me.id,
            v_suggested, 'waiting', v_reason, v_hyp, v_kind)
    returning id into v_id;
    perform public.hub_end();
    return jsonb_build_object('result', 'inbox', 'inbox_id', v_id, 'reason', v_reason, 'kind', v_kind);
end;
$$;


-- ------------------------------------------------------------------ backfill
update public.interviews o
set session_of = p.id
from public.interviews p
where o.id = 3 and p.id = 2
    and o.contact_id = p.contact_id and o.date = p.date
    and o.session_of is null and p.session_of is null;

-- ---------------------------------------------------------------- who may call
revoke all on function public.hub_same_conversation(bigint, date, bigint) from public, anon, authenticated, service_role;
revoke all on function public.link_interviews(bigint, bigint, text) from public, anon, authenticated, service_role;
grant execute on function public.link_interviews(bigint, bigint, text) to authenticated;

-- A revoke that changes nothing is silent (docs/FINDINGS.md, issue 35): ask.
do $$
declare
    v_name text;
    v_role text;
begin
    foreach v_name in array array['link_interviews', 'hub_same_conversation', 'save_interview', 'submit_recording'] loop
        if (select count(*) from pg_catalog.pg_proc p
            where p.pronamespace = 'public'::regnamespace and p.proname = v_name) <> 1 then
            raise exception 'there is not exactly one function public.% after this migration', v_name;
        end if;
        foreach v_role in array array['anon', 'hub_export'] loop
            if exists (select 1 from pg_catalog.pg_roles where rolname = v_role)
                and exists (select 1 from pg_catalog.pg_proc p
                            where p.pronamespace = 'public'::regnamespace and p.proname = v_name
                                and pg_catalog.has_function_privilege(v_role, p.oid, 'EXECUTE')) then
                raise exception '% can call public.%', v_role, v_name;
            end if;
        end loop;
    end loop;
    if pg_catalog.has_function_privilege('authenticated', 'public.hub_same_conversation(bigint, date, bigint)', 'EXECUTE') then
        raise exception 'authenticated can call public.hub_same_conversation';
    end if;
end $$;
